    -- ═══════════════════════════════════
    -- MythicTracker Noms EJ (2.9.10)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- Correction CD PartyFrame + Performances (2.9.12)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- =======================================
    -- Installer Overhaul & AB Toggle (2.9.17)
    -- =======================================
    -- ═══════════════════════════════════
    -- Waypoint intelligent (2.9.20)
    -- ═══════════════════════════════════
    ["wn_2920_waypoint_redirect"]       = "Waypoint intelligent — redirection cross-zone : le waypoint suit désormais la prochaine étape du chemin sur la carte actuelle (portail, entrée de donjon) via C_SuperTrack.GetNextWaypointForMap(), mis à jour sur SUPER_TRACKING_PATH_UPDATED et les changements de zone.",
    ["wn_2920_waypoint_blob"]           = "Waypoint intelligent — correction du point mort à 0 m : la balise se masque automatiquement quand le joueur est dans la zone blob de l'objectif de quête (C_Minimap.IsInsideQuestBlob), empêchant le waypoint de rester figé à 0 m.",
    ["wn_2920_waypoint_label"]          = "Waypoint intelligent — label dynamique : la destination affiche désormais la description de l'étape de redirection (ex. « Voyage à Durotar ») ou le titre de la quête suivie au lieu d'un champ vide.",

    -- Suivi des objectifs — Stabilité (2.9.19)
    -- ═══════════════════════════════════
    ["wn_2919_antiflicker"]             = "Anti-tremblement — élimination du « tremblement » visible du suivi causé par une boucle de rétroaction entre la mise en page de TomoMod et les hooks natifs Update / MarkDirty de Blizzard. Nouveau garde de réentrée, regroupement différé des mises à jour et fenêtre de silence post-layout de 0,20 s qui brisent la récursion.",
    ["wn_2919_collapsed_persist"]       = "Persistance des catégories repliées — les blocs de quête sous une catégorie repliée ne réapparaissent plus quand Blizzard relance sa mise en page ; chaque bloc reçoit un hook Show unique qui le re-masque automatiquement.",
    ["wn_2919_header_detection"]        = "Détection des en-têtes — comparaison insensible aux accents et à la casse (Métier / métier / MÉTIER correspondent au même mot-clé) avec variantes singulières ajoutées. Les titres de quête et lignes d'objectif sont désormais explicitement exclus, donc la description de quête n'est plus accidentellement masquée.",
    ["wn_2919_recipe_height"]           = "Hauteur des blocs de recette — les recettes de métier ne chevauchent plus la quête suivante. La mesure de profondeur s'exécute désormais systématiquement et descend jusqu'à 8 niveaux pour atteindre les FontStrings de réactifs.",
    ["wn_2919_reward_preview"]          = "Exclusion des aperçus de récompense — les Delves (ex. « La Sombrevoie »), scénarios M+, popups de quêtes monde et blocs du coffre hebdomadaire (ex. « Halte de l'Ombre-Garde » avec aperçu ilvl) sont désormais ignorés par le système de catégories. Ils restent à leur emplacement Blizzard natif et ne chevauchent plus nos quêtes.",

    -- ═══════════════════════════════════
    -- Suivi des objectifs — Catégories (2.9.18)
    -- ═══════════════════════════════════
    ["wn_2918_buckets"]                 = "Catégories de quêtes dans le suivi — les quêtes, quêtes du monde, hebdomadaires, quotidiennes, donjons, raids, métiers et hauts faits sont désormais regroupés en sections repliables avec en-têtes colorés et compteurs en direct.",
    ["wn_2918_bucket_toggle"]           = "Nouvelle case « Grouper les quêtes par catégories repliables » dans Config → Apparences → Suivi des objectifs ; la décocher restaure instantanément la disposition Blizzard d'origine, sans /reload.",
    ["wn_2918_tracker_width"]           = "Panneau de suivi élargi de 10 px afin que les icônes des objets de quête ne soient plus rognées sur le bord droit.",
    ["wn_2918_layout_fix"]              = "Les blocs de quête re-parentés sont désormais ancrés à la fois TOPLEFT et TOPRIGHT pour éviter l'effondrement de largeur, et les hauteurs périmées après pliage/dépliage sont corrigées via une mise en page multi-passe.",

    ["wn_2917_ab_master_toggle"]        = "Toggle master des barres d'action \226\128\148 une nouvelle case \194\171 Activer le syst\195\168me de barres d'action TomoMod \194\187 dans l'installeur et le panneau Config permet de d\195\169sactiver enti\195\168rement la gestion des barres ; apr\195\168s /reload, les barres Blizzard par d\195\169faut sont restaur\195\169es.",
    ["wn_2917_installer_raid"]          = "\195\137tape 5 de l'installeur \226\128\148 Cadres de raid : activer/d\195\169sactiver, masquer les cadres Blizzard, surlignage dispel, suivi HoT, ic\195\180nes debuff, d\195\169fensifs CD, et choix grille/liste.",
    ["wn_2917_installer_coverage"]      = "Installeur enrichi \226\128\148 l'\195\169tape Skins inclut d\195\169sormais Objective Tracker, Courrier et Barre de r\195\169putation ; l'\195\169tape QOL ajoute Auto Summon, Auto Qu\195\170tes, Rappel de classe, Barre de niveau, Waypoint, Qu\195\170tes mondiales, Ancres de fen\195\170tres et Aide aux m\195\169tiers.",
    ["wn_2917_chat_skin_fix"]           = "Fix Chat Skin \226\128\148 l'installeur \195\169crivait dans une cl\195\169 orpheline \194\171 chatSkin \194\187 au lieu de la vraie cl\195\169 \194\171 chatFrameSkin \194\187, rendant le toggle non fonctionnel.",
    ["wn_2917_talking_head_fix"]        = "Fix HideTalkingHead \226\128\148 le module v\195\169rifie maintenant son toggle DB avant de supprimer le cadre TalkingHead, au lieu de s'appliquer inconditionnellement.",
    ["wn_2917_minimal_style"]           = "Style \194\171 Minimal \194\187 des barres d'action \226\128\148 le 5e style (sans bordure avec ombres int\195\169rieures) manquait du dropdown de l'installeur malgr\195\169 son impl\195\169mentation ; d\195\169sormais s\195\169lectionnable.",

    -- AuctionRecipeTracker (2.9.15)
    -- ═══════════════════════════════════
    ["wn_2916_layout_fix"]              = "Bouton Layout silencieux corrigé — sur une nouvelle installation, cliquer sur 'Layout' ne faisait rien car le système de movers ne terminait pas son initialisation. Toggle effectue maintenant une initialisation paresseuse via pcall et affiche toute erreur dans le chat au lieu d'échouer silencieusement.",
    ["wn_2916_safe_init"]               = "Renforcement de la chaîne d'init des modules — chaque appel TomoMod Initialize() est désormais encapsulé dans xpcall via un helper safeInit ; un module défaillant ne casse plus les ~45 modules qui s'initialisent après lui, et le module fautif est signalé dans le chat.",
    ["wn_2916_art_total"]               = "AuctionRecipeTracker — chaque en-tête de recette suivie affiche maintenant le coût total global de ses composants à droite ; si au moins un composant n'a pas de prix enregistré, un (~) gris indique que le total est une estimation partielle.",
    ["wn_2916_avr_gui"]                 = "GUI Auto Vendeur / Réparation — deux nouvelles cases à cocher dans Config → QOL → Automatisations permettent d'activer indépendamment la réparation automatique chez le marchand et la vente automatique des objets gris ; les réglages sont persistés dans TomoModDB et s'appliquent en direct sans /reload.",
    ["wn_2915_art_module"]              = "Nouveau module QOL — AuctionRecipeTracker : un GUI s'ouvre automatiquement chez le commissaire-priseur quand au moins une recette d'artisanat est suivie ; les lignes affichent '14x icône Nom de l'objet prix', clic pour rechercher à l'HDV, et un bouton de scan complet manuel.",
    ["wn_2915_art_tooltip"]             = "Ligne TomoHDV dans les infobulles — après un scan, chaque objet (sacs, banque, liens du chat, équipement) affiche le prix unitaire enregistré, plus le prix total de la pile si stack > 1, et depuis quand le scan a été fait.",
    ["wn_2915_art_scrollbar"]           = "Scrollbar moderne TomoMod — la scrollbar Blizzard par défaut est remplacée par un track fin de 4 px avec un thumb couleur accent dimensionné proportionnellement au contenu ; supporte le drag, le clic sur le track pour sauter, la molette, et s'auto-masque quand le contenu tient dans la fenêtre.",
    ["wn_2915_art_anchor"]              = "Ancrage par défaut de l'AuctionRecipeTracker — la fenêtre se colle au bord droit de la fenêtre HDV (TOPLEFT, AuctionHouseFrame, TOPRIGHT, 8, 0) ; les positions personnalisées par drag restent persistantes et prioritaires.",
    ["wn_2915_art_scan_fix"]            = "Fiabilité du bouton de scan — OnShow réinitialise maintenant scanInProgress, réactive le bouton et restaure son label ; les retours silencieux (scan en cours, HDV fermé, API absente) affichent un message rouge en bas au lieu de ne rien faire.",

    -- ═══════════════════════════════════
    -- MythicTracker Boss Names Fix (2.9.13)
    -- ═══════════════════════════════════
    ["wn_2913_boss_names"]               = "MythicTracker : les noms des boss s'affichent désormais correctement au lieu de \"Boss 1\", \"Boss 2\" etc. — en WoW 12.x le champ des critères de scénario a été renommé de criteriaString en description ; TomoMod lit désormais description en priorité avec criteriaString en repli.",
    ["wn_2913_boss_checkmark"]           = "MythicTracker : le préfixe de coche de Blizzard (ajouté aux objectifs boss complétés en 12.x) est maintenant supprimé avant l'affichage.",
    ["wn_2913_ej_pcall"]                 = "MythicTracker : l'appel EncounterJournal_OpenJournal dans FetchEJBossNames est désormais encapsulé dans pcall pour éviter un taint potentiel en 12.x.",

    ["wn_2912_party_cd_fix"]             = "PartyFrame : le suivi des CD d'interrupt et de résurrection de combat utilise désormais UNIT_SPELLCAST_SUCCEEDED avec résolution d'ID de sort sécurisée (string.format) ; COMBAT_LOG_EVENT_UNFILTERED supprimé — son enregistrement depuis un addon provoque du taint en 12.x.",
    ["wn_2912_healer_interrupt"]         = "PartyFrame : l'icône du tracker d'interrupt est maintenant masquée pour les healers — depuis la 12.x les healers n'ont plus de sort d'interrupt.",
    ["wn_2912_perf_cdm"]                 = "CooldownManager : UpdateButtonState met en cache GetCooldownTimes, GetCachedCooldownID et GetCooldownViewerCooldownInfo une seule fois par bouton par tick au lieu de deux ; ~50% d'appels API en moins dans la boucle principale.",
    ["wn_2912_perf_aura"]                = "AuraTracker : fréquence de rafraîchissement réduite de 10 fps (0,1 s) à 5 fps (0,2 s) ; aucune différence visible, la charge du ticker est divisée par deux.",
    ["wn_2912_perf_resbars"]             = "ResourceBars : seuil OnUpdate pour les runes DK / stagger Moine passé de 50 ms à 100 ms ; fréquence d'exécution divisée par deux sans impact perceptible sur l'affichage.",

    -- ═══════════════════════════════════
    -- Corrections CooldownManager / ProcGlow / BuffSkin (2.9.11)
    -- ═══════════════════════════════════
    ["wn_2911_cdm_hooks"]                = "CooldownManager : les couleurs de swipe et le masquage du GCD sont fusionnés en un seul hook par bouton ; la détection GCD utilise le cache Scanner au lieu de pcall(C_CooldownViewer).",
    ["wn_2911_procglow_fixes"]           = "CDMProcGlow : le glow est appliqué de façon synchrone dans ShowAlert pour éviter une race condition avec HideAlert dans le même frame ; les timers par frame remplacés par un ticker global unique ; RefreshAll filtre correctement les procs actifs.",
    ["wn_2911_buffskin_fixes"]           = "BuffSkin : SkinButton ré-applique les ancres et masques d'icône sur les frames recyclés par Blizzard ; hooks installés une seule fois via hooksInstalled (activer/désactiver fonctionne maintenant) ; TemporaryEnchantFrame hooké pour les enchantements d'arme ; hooks installés immédiatement.",

    -- ═══════════════════════════════════
    -- MythicTracker Noms EJ (2.9.10)
    -- ═══════════════════════════════════
    ["wn_2910_ej_boss_names"]            = "MythicTracker : noms de boss résolus via l'Encounter Journal — localisés, compatibles accents, couvrant tous les donjons de Cata à The War Within.",
    ["wn_2910_ej_fallback"]              = "MythicTracker : résolution en 3 niveaux — dungeonEncounterID > index EJ > criteriaString filtré en dernier recours, avec retry automatique (×5) si l'EJ n'est pas encore chargé.",

    -- =====================
    -- AuctionRecipeTracker
    -- =====================
    ["art_title"]            = "Suivi de recettes",
    ["art_no_recipes"]       = "Aucune recette suivie — suivez une recette depuis votre fenêtre de métier.",
    ["art_status_idle"]      = "Cliquez sur un ingrédient pour le chercher à l'HDV.",
    ["art_scan_btn"]         = "Scanner l'HDV",
    ["art_scan_running"]     = "Scan en cours...",
    ["art_scan_started"]     = "Scan démarré — veuillez patienter...",
    ["art_scan_done"]        = "Scan terminé : %d objets enregistrés.",
    ["art_scan_failed"]      = "Scan échoué ou interrompu.",
    ["art_scan_cooldown"]    = "Prochain scan disponible dans %dm %ds.",
    ["art_scan_tip_title"]   = "Scan complet de l'Hôtel des Ventes",
    ["art_scan_tip_desc"]    = "Enregistre le prix d'achat immédiat le plus bas par objet. Limité à une fois toutes les 15 minutes.",
    ["art_only_at_ah"]       = "Ouvrez d'abord l'Hôtel des Ventes.",
    ["art_scan_already"]     = "Un scan est déjà en cours.",
    ["art_tt_stack"]         = "Pile",
    ["art_tt_scanned"]       = "Scanné",
    ["art_tt_just_now"]      = "à l'instant",
    ["art_tt_min_ago"]       = "il y a %dm",
    ["art_tt_hour_ago"]      = "il y a %dh",
    ["art_tt_day_ago"]       = "il y a %dj",

    -- Player Auras Mover (v2.9.5)
    ["mover_player_auras"]       = "Auras du joueur",
    ["opt_auras_spacing"]        = "Espacement entre icônes",
    ["btn_reset_aura_position"]  = "Réinitialiser position auras",

    -- Module Reload Safety (v2.9.21)
    ["msg_module_reload"]        = "Ce changement nécessite un rechargement de l'interface.\nRecharger maintenant ?",
    ["info_module_reload"]       = "Nécessite un /reload pour prendre effet.",
    ["wn_2921_aura_mover"]       = "Les auras du joueur ont désormais leur propre mover dans le mode Layout (overlay teinté, label, drag & drop indépendant).",
    ["wn_2921_aura_gui"]         = "Nouveau slider d'espacement des auras et bouton de réinitialisation de position dans l'onglet Auras du GUI.",
    ["wn_2921_reload_safety"]    = "Activer/désactiver un module majeur (UnitFrames, Nameplates, Castbars, ActionBars, Party, Raid) propose désormais un /reload automatique.",

    -- Waypoint Arrow Reversed (v2.9.22)
    ["wn_2922_waypoint_arrow"]    = "La flèche du navigateur hors-écran du waypoint est maintenant du côté opposé de l'orbite : quand l'objectif est devant vous, la flèche apparaît en bas et pointe vers le haut.",

    -- 3.0.4
    ["wn_304_consumable_bar"]    = "ConsumableBar — nouveau module QOL affichant les icônes Flacon et Bien Nourri avec minuterie. Entièrement configurable (taille, écart, orientation, position du timer) et déplaçable en mode Layout.",
    ["wn_304_cursor_textures"]   = "Anneau de curseur — deux nouvelles textures ajoutées (Cygle et Cœur). Sélecteur de texture disponible dans Général → Anneau de curseur.",
    ["wn_304_mythichub_tp"]      = "Téléportation MythicHub corrigée — plus de taint (ADDON_ACTION_FORBIDDEN) ni d'erreur d'ancrage en cliquant sur les donjons. Les SpellID de Cavernes de Maisara et de la Flèche Sylvevente sont également corrigés.",

    -- 3.0.3
    ["wn_303_tracking_panel"]    = "Panneau de pistage custom — cliquer sur le bouton de pistage ouvre désormais un panneau style TomoMod à gauche de la minimap au lieu du menu Blizzard natif.",
    ["wn_303_collector_panel"]   = "Refonte du panneau collecteur — les boutons d'addon sont regroupés dans un vrai panneau TomoMod (fond sombre, titre teal, bordure couleur de classe) ancré à gauche de la minimap.",
    ["wn_303_collector_autoclose"] = "Le collecteur se referme automatiquement 0,5 s après le login/rechargement une fois les boutons capturés — le panneau reste propre à l'entrée et se rouvre normalement au clic.",
    ["wn_303_tooltip_fix"]       = "Correction skin tooltip — le grand rectangle noir qui apparaissait en survolant des unités ou des sorts a été résolu.",
    ["wn_303_coords_pos"]        = "Les coordonnées de la minimap sont déplacées en bas au centre pour une meilleure lisibilité.",

    -- 3.0.0
    ["wn_300_installer"]  = "Tout nouvel assistant de configuration — « presets d'abord » : choisis Recommandé, Tank, Soigneur, DPS, Minimal ou Personnalisé et c'est réglé en quelques secondes.",
    ["wn_300_presets"]    = "Presets de configuration — un clic applique une config cohérente et ajustée au rôle sur tous les modules ; réutilisable à tout moment via /tm.",
    ["wn_300_dashboard"]  = "Nouveau tableau de bord Accueil dans /tm — gros toggles de modules, relance de l'assistant, application d'un preset, changement de profil et reset, au même endroit.",
    ["wn_300_search"]     = "Sidebar avec recherche — filtre les catégories par nom ou mot-clé (tape 'soin', 'cd', 'sacs'…).",
    ["wn_300_minimap"]    = "La minimap carrée retrouve ses boutons natifs — pistage, alertes courrier et craft, difficulté d'instance, et le bouton d'extension — chacun activable et librement positionné/redimensionné depuis le GUI.",
    ["wn_300_buttonbag"] = "Collecteur de boutons d'addon — un bouton de minimap ouvre une boîte regroupant tous tes boutons d'addon (DBM, Details!, WeakAuras…), pour garder la minimap propre.",

    -- =====================
    -- QOL: Rare Alert (RareAlert.lua)
    -- =====================
    ["tab_qol_rare_alert"]       = "Alerte Rare",
    ["section_rare_alert"]       = "Alerte Rare",
    ["opt_rare_alert_enable"]    = "Activer les alertes de rare à proximité",
    ["opt_rare_alert_sound"]     = "Jouer un son d'alerte",
    ["opt_rare_alert_duration"]  = "Durée d'affichage de la bannière (s)",
    ["btn_reset_rare_alert_pos"] = "Réinitialiser la position de la bannière",
    ["rare_alert_info"]          = "Vous avertit quand un PNJ rare est à proximité. Cliquez la bannière pour le cibler, poser la Tête de mort et créer un point de route. Clic droit pour fermer. Utilisez /tm layout pour déplacer la bannière.",
    ["rare_alert_tooltip"]       = "Clic gauche : cibler + Tête de mort + point de route. Clic droit : fermer.",

    -- 3.0.5
    ["wn_305_rare_alert"]        = "RareAlert — nouveau module QoL : un son et une bannière cliquable quand un PNJ rare est proche (via les vignettes). Monde ouvert uniquement — jamais en donjon ni en raid.",
    ["wn_305_rare_alert_marker"] = "Cliquez la bannière du rare pour le cibler, poser la Tête de mort et créer un point de route. Son et durée configurables ; déplaçable en mode Layout.",
    ["wn_305_tm_fix"]            = "Corrigé — cliquer une alerte de rare de RareScanner n'ouvre plus la config de TomoMod (collision de la commande /tm résolue).",

    -- =====================
    -- Extra Action Button (v3.0.6)
    -- =====================
    ["mover_ab_extra"] = "Bouton extra",
    ["mover_ab_pet"] = "Barre du familier",
    ["mover_ab_stance"] = "Barre de posture",
    ["section_extra_button"] = "Bouton d'action supplémentaire",
    ["opt_extra_enabled"] = "Gérer le bouton d'action supplémentaire (recharge pour libérer)",
    ["opt_extra_scale"] = "Échelle du bouton supplémentaire",
    ["btn_extra_reset_pos"] = "Réinitialiser la position",
    ["info_extra_button"] = "Positionnez le bouton d'action supplémentaire en mode Layout. Il apparaît pendant les quêtes et les combats de boss. Le désactiver le rend à Blizzard après un /reload.",
    ["wn_306_extra_button"] = "Nouveau — le bouton d'action supplémentaire fait désormais partie du système de barres d'action de TomoMod.",
    ["wn_306_extra_mover"] = "Nouveau — déplacez le bouton d'action supplémentaire (et le bouton de capacité de zone) en mode Layout, comme n'importe quelle barre. Position et échelle enregistrées dans votre profil.",
    ["wn_306_extra_scale"] = "Nouveau — options du bouton d'action supplémentaire dans Barres d'action, onglet Gestion des barres : activer, échelle et réinitialiser la position.",
    ["wn_306_compass"] = "Correction — Boussole : corrigé une erreur Lua fréquente (x417) dans la conversion de coordonnées monde (C_Map.GetWorldPosFromMapPos renvoie continentID + worldPosition ; le continentID est désormais correctement ignoré).",
    ["wn_306_bagskin"] = "BagSkin — les slots utilisent maintenant ContainerFrameItemButtonTemplate de Blizzard : clic, utilisation, ramassage et division sont gérés par du code sécurisé natif (plus de PreClick potentiellement tainté). Les slots différés en combat sont rejoués automatiquement à la fin du combat.",
    -- 3.0.7
    ["wn_307_objective_tracker"] = "Suivi des objectifs — Les blocs de quêtes mondiales sont maintenant triés dans le bucket Quêtes Mondiales au lieu de flotter au-dessus du tracker. Les barres de progression (forces ennemies, % hebdomadaire) sont masquées lorsque leur bucket est réduit.",
    ["wn_307_guardian_rage"]     = "Barres de ressources — Les Druides Gardiens voient désormais leur barre de Rage centrée à l'écran par défaut. Le Mana reste en barre secondaire en dessous. La barre de puissance de l'UnitFrame est masquée automatiquement.",
    ["wn_307_resource_bars"]     = "Barres de ressources — Corrigé : les sliders de hauteur de pouvoir de classe et de mana druide s'appliquent désormais correctement (conflit de nom global résolu). Nouveau slider pour la hauteur de la barre centrale. Nouvelle checkbox dans UnitFrames › Joueur › Dimensions pour déplacer la barre de puissance au centre.",
    ["wn_310_brez_counter"]       = "Compteur Battle Rez — Nouveau HUD déplaçable affichant le nombre de résurrections de combat disponibles et le délai avant la prochaine charge. Lit le pool partagé, fonctionne sur toutes les classes. À configurer dans Raid Frames → Fonctionnalités.",
    ["wn_310_resurrect"]          = "Indicateur de résurrection — Une icône de rez apparaît désormais sur un membre du groupe ou du raid pendant qu'une résurrection est en cours de lancement sur lui.",
    ["wn_310_raid_sizes"]         = "Raid Frames — Nouvelles dispositions par taille optionnelles (10 / 25 / 40) : la largeur et la hauteur des frames s'adaptent automatiquement à la taille du groupe actuel. À configurer dans Raid Frames → Fonctionnalités.",
    ["wn_310_brez_fix"]           = "Frames de groupe — Corrigé : le suivi du cooldown de résurrection de combat affiche désormais correctement l'icône grisée et le minuteur de rechargement dès qu'un brez est consommé dans l'instance.",

    -- 3.1.1
    ["art_searching"]        = "Recherche : %s",
    ["art_searching_qty"]    = "Recherche : %s × %d",
    ["wn_311_icicles"]        = "Mage Givre : nouveau suivi des Glaçons dans la barre de ressources (5 segments + lueur Glacial Spike au maximum). Couleur personnalisable dans CD & Ressources → Couleurs.",
    ["wn_311_taint_money"]   = "Correction d'une erreur de taint (Midnight) : survoler un objet dans le Journal des donjons ne déclenche plus l'erreur « secret number » sur la valeur en or — TomoMod ne contamine plus les infobulles de comparaison.",
    ["wn_311_art_qty"]       = "AuctionRecipeTracker : cliquer sur un composant recherche l'objet à l'Hôtel des ventes et affiche la quantité requise dans la barre de statut (ex. Recherche : Awakened Fire × 14).",

    -- 3.1.2
    ["wn_312_brand"]         = "Couleur accent mise à jour de #0cd29f vers #2ed884 (vert menthe) sur toute l'interface — barre de titre, panneaux, messages, popups et valeurs de couleur par défaut.",
    ["wn_312_brand_api"]     = "Nouvelles constantes TomoMod_Utils.BRAND / BRAND_DARK / BRAND_HOVER : tous les panneaux de configuration et le thème des Widgets lisent désormais la couleur accent depuis une source unique.",
    ["wn_312_companion_fix"] = "CompanionStatus : correction d'une fuite de variable globale (UpdateIcon n'était pas déclaré local).",

    -- 3.1.3
    ["wn_313_nav"]        = "Interface de configuration repensée : 16 panneaux regroupés en 6 catégories (Interface, Unités, Combat, Confort, Outils), chacune avec sa propre couleur accent et un en-tête de page.",
    ["wn_313_accent"]     = "Les widgets adoptent désormais automatiquement la couleur accent de leur panneau parent — cartes, en-têtes, séparateurs, cases à cocher, boutons et onglets s'adaptent au contexte actif.",
    ["wn_313_segmented"]  = "Nouveau widget SegmentedControl remplaçant les menus déroulants courts (Barre de sacs, Menu Micro, Style chat, Layout sacs, Tri, Canal audio).",
    ["wn_313_dashboard"]  = "Tableau de bord Accueil refondu : bandeau héro avec statut diagnostics en direct, raccourcis rapides (Installeur, Profils, Diagnostics, Recharger) et toggles modules redesignés.",
    ["wn_313_np_preview"] = "Nameplates : nouvel aperçu en direct en haut du panneau de configuration — affiche allié, hostile et boss, se met à jour en temps réel lors des ajustements de taille, barre de cast et police.",
    ["wn_313_loot_filter"] = "Correction du filtre de classe sur le butin : les objets absents de l'IDB (ex. nouveaux raids) utilisent désormais le type d'armure comme repli au lieu d'être affichés pour toutes les classes.",
    ["wn_313_sporefall"]   = "Données de butin : raid Sporefall (ejEncounterID 2711) ajouté avec 15 objets depuis KeystoneLoot build 12.0.7.",
    ["wn_313_diag"]       = "Diagnostics : 7 nouveaux mots-clés d'exclusion UIError (marchand, monture, inventaire, suppression, mise à niveau, apparence, duel) + la console s'affiche toujours au-dessus du menu de configuration.",
    ["wn_313_tooltip_anchor"] = "Position de l'infobulle : nouveau système à 4 modes — Défaut, Souris (suit le curseur), Coin (ancré sur un coin de l'écran) et Personnalisé (cadre déplaçable par glisser).",

    -- Ancrage infobulle
    ["opt_tooltip_anchor"]        = "Position de l'infobulle",
    ["tooltip_anchor_default"]    = "Défaut",
    ["tooltip_anchor_cursor"]     = "Souris",
    ["tooltip_anchor_corner"]     = "Coin de l'écran",
    ["tooltip_anchor_custom"]     = "Personnalisé",
    ["opt_tooltip_anchor_corner"] = "Coin (mode Coin)",
    ["corner_br"]                 = "Bas droite",
    ["corner_bl"]                 = "Bas gauche",
    ["corner_tr"]                 = "Haut droite",
    ["corner_tl"]                 = "Haut gauche",
    ["info_tooltip_anchor"]       = "Personnalisé : choisis ce mode puis glisse le cadre teal à l'endroit voulu.",
    ["btn_tooltip_toggle_anchor"] = "Afficher/Masquer le repère",
    ["mover_tooltip_anchor"]      = "Ancre de l'infobulle",

    -- Nameplates preview
    ["np_preview_title"]   = "Aperçu des plaques",
    ["np_preview_hint"]    = "Lisibilité rapide : couleur, cast, auras et menace au même endroit.",
    ["preview_np_friendly"] = "Allié",
    ["preview_np_target"]  = "Cible hostile",
    ["preview_np_boss"]    = "Boss marqué",

    -- 3.1.4
    ["wn_314_tooltip_anchor"] = "Position de l'infobulle : nouveau système à 4 modes — Défaut, Souris (suit le curseur), Coin (coin de l'écran) et Personnalisé (cadre déplaçable). Réglable dans Skins → Tooltip.",
    ["wn_314_locale_fix"]     = "Correction des libellés manquants : les sélecteurs de couleur de fond et de bordure dans Skins → Tooltip s'affichent désormais correctement.",

    -- 3.1.5
    ["wn_315_ot_itembutton"] = "Traqueur d'objectifs : les boutons d'objet de quête se masquent désormais correctement lors de la réduction d'un bucket (le bouton est parenté au traqueur natif, pas au bloc — il restait visible au-dessus des buckets réduits).",
    ["wn_315_talkinghead"] = "QOL : l'option « Masquer le Talking Head » est de retour dans le GUI de configuration (QOL → Automatisations). Elle s'applique désormais instantanément sans /reload et est réversible — la décocher réaffiche les dialogues à défilement.",

    -- 3.1.6
    ["wn_316_party_combat"] = "Frames de groupe : correction des bugs de visibilité lorsqu'un membre rejoint, quitte, ou que le groupe se transforme en raid en plein combat — les frames s'affichent/se masquent désormais de façon fiable dans toutes les situations.",
    ["wn_316_raid_combat"] = "Frames de raid : correction des frames qui restaient bloquées visibles ou masquées lorsque des membres rejoignaient ou quittaient le raid en combat — la visibilité est désormais gérée par un système sécurisé, compatible combat.",
    ["wn_316_roster_repaint"] = "Frames de groupe & raid : correction d'informations obsolètes (couleur de classe, absorptions, surbrillance dissipation) affichant brièvement le mauvais joueur après un changement de composition, même en combat.",
    ["wn_317_cdm_holders"] = "Cooldown Manager : nouveau système de « Holders » — déplacez et verrouillez librement chaque visualiseur de cooldown (Essentiel, Utilitaire, Icônes de buff, Barres de buff) indépendamment de la grille du Mode Édition de Blizzard, avec aperçu en direct des icônes/barres quand ils sont vides.",
    ["wn_317_resourcebars_health"] = "Barres de ressources : nouvelle barre de vie optionnelle — hauteur configurable, format (%, valeur ou les deux), couleur de classe, animation fluide et seuil de couleur pour vie basse.",
    ["wn_317_config_cards"] = "Interface de configuration : le panneau Cooldown & Ressources a désormais une disposition en cartes et un nouvel onglet Barres regroupant tous les réglages de la barre de vie.",
    ["wn_316_locale_cdm"] = "Correction de l'onglet Barres, des cartes de placement/aperçu live et de la section barre de vie & animations qui affichaient des clés brutes au lieu du texte traduit — traduit dans les 6 langues.",
    ["wn_316_taint_chat"] = "Correction d'une erreur de taint (« secret string value ») dans le skin du chat lors de la réception de messages de canal.",
    ["wn_316_taint_skyride"] = "Correction d'une erreur de taint (« secret number value ») dans la barre de vitesse Skyriding, causée par les valeurs de vitesse de vol/planage protégées par le jeu.",
    ["wn_316_durability_pos"] = "Minimap : la position du texte de durabilité est désormais configurable (coin + décalage X/Y) dans Interface → Général → Info Panel — utile pour éviter le chevauchement avec le nouveau bouton d'extension du patch 12.0.7.",

    -- 3.1.7
    ["wn_317_libserialize_namespace"] = "Profils : la bibliothèque LibSerialize embarquée utilise désormais un espace de noms privé (« TomoSerialize-1.0 ») au lieu du nom partagé « LibSerialize », ce qui évite les conflits d'export/import avec d'autres addons qui embarquent aussi LibSerialize.",
    ["wn_317_drag_absolute_coords"] = "Frames déplaçables : correction des positions enregistrées qui dérivaient ou s'inversaient après un glisser sur la Barre de niveau, Movers, AuctionRecipeTracker, le Traqueur Mythique+, TomoScore, Frame Anchors, Bag Skin, les barres de cast, les ancres de frames de groupe/raid, la Boussole, la Barre de consommables, le Butin, la Minimap, le Traqueur d'objectifs, la barre Skyriding, les barres de ressources et les UnitFrames — les positions sont désormais enregistrées en coordonnées absolues à l'écran, stables.",
    ["wn_317_ot_combat_taint"] = "Traqueur d'objectifs : correction d'une possible erreur de taint lorsque Blizzard réaffiche un bloc de bucket de quête réduit pendant une mise à jour de quête en plein combat.",
    ["wn_317_deadcode_cleanup"] = "Nettoyage interne : suppression de plusieurs modules inutilisés/désactivés afin de réduire la taille de l'addon — aucune fonctionnalité visible par l'utilisateur n'a été affectée.",
    ["wn_317_raidmanager_fix"] = "Cadres de raid : correction du panneau du leader de groupe Blizzard par défaut (vérification de disponibilité, marqueurs de raid, conversion en raid, limite de pings, quitter le groupe) qui était masqué en même temps que les cadres de raid lorsque « Masquer les cadres de raid Blizzard » est activé — seul le conteneur des cadres de membres est désormais supprimé, la barre d'outils du leader reste disponible.",
    ["wn_317_groupmanager_skin"] = "Cadres de raid : l'option « Reskin le panneau du leader de groupe » habille désormais entièrement la barre d'outils Blizzard dans le thème sombre/menthe de TomoMod — menus déroulants de mode et de limite de pings, filtres rôle/groupe, icônes de la barre d'outils (mode édition, paramètres, ready check, sondage de rôle, compte à rebours), boutons de marqueurs de raid avec leurs onglets Unité/Sol, et boutons Quitter le groupe en rouge — tout en conservant intactes les icônes Blizzard, avec bascule en direct sans /reload.",
    ["wn_317_groupmanager_collapsetab"] = "Cadres de raid : correction du bouton de repli du panneau du leader de groupe qui laissait une bande résiduelle sur le bord de l'écran, et remplacement par une véritable languette menthe au lieu d'un simple bouton reskinné.",

    -- 3.1.8
    ["wn_318_bagskin_itemclass_enum"] = "Bag Skin : la correspondance des catégories utilise désormais les constantes Enum.ItemClass de Blizzard (avec repli numérique) au lieu de nombres de classe d'objet codés en dur, garantissant une catégorisation fiable sur tous les clients.",
    ["wn_318_bagskin_cat_order"] = "Bag Skin : ordre des catégories par défaut mis à jour — les Objets de quête sont désormais regroupés juste après l'Équipement, avant les Consommables et les Matériaux.",
    ["wn_318_bagskin_cat_foundation"] = "Bag Skin : ajout des bases internes pour une future option de masquage/réorganisation des catégories — Divers et Emplacements libres restent toujours visibles pour qu'aucun objet ne puisse jamais disparaître.",

    -- 3.1.9
    ["wn_3110_actionbar_spelldrag"] = "Barres d'action : le correctif 3.1.9 des emplacements vides ne fonctionnait toujours pas pour un sort, une macro ou une monture déjà placé sur une barre (avec « Afficher les emplacements vides » désactivé) — les déplacer sur un emplacement vide fonctionne désormais pendant tout glisser-déposer, sans ouvrir le Grimoire/les Talents.",
    ["wn_3110_skyride_taint"] = "Vol planant : correction d'une erreur de corruption récurrente sur l'affichage de la vitesse au sol, qui pouvait encore se déclencher des centaines de fois par session malgré un correctif précédent — le calcul de vitesse est désormais renforcé par une sécurité supplémentaire pour qu'il ne puisse plus générer d'erreur.",
    ["wn_3110_diag_exclusions"] = "Diagnostics : ajout de deux nouveaux mots-clés d'exclusion (marchand refusant d'acheter un objet, ramassage de butin bloqué pendant que le mode Défi est actif) afin que ces messages normaux du jeu ne soient plus consignés comme des bugs.",
    ["wn_319_actionbar_dragfix"] = "Barres d'action : correction de sorts impossibles à glisser sur un emplacement vide (avec l'option « Afficher les emplacements vides » désactivée) sauf si le Grimoire/les Talents étaient ouverts — les emplacements vides se révèlent désormais pendant tout glisser-déposer.",
    ["wn_319_ot_mover_fix"] = "Suivi des quêtes : correction du repère qui réinitialisait parfois sa position (le Mode Édition de Blizzard pouvait le contourner silencieusement) — le glisser-déplacer reste désormais fiable.",
    ["wn_319_ot_quest_limit"] = "Suivi des quêtes : correction du curseur « Nombre max. de quêtes affichées » qui n'avait aucun effet dans la disposition par Catégories par défaut.",
    ["wn_319_minimap_drift"] = "Minimap : correction de la minimap qui se déplaçait toute seule après un /reload (un bug de calcul d'échelle appliquait deux fois le facteur d'échelle à la position enregistrée).",
    ["wn_319_minimap_collector"] = "Minimap : correction du collecteur de boutons qui masquait encore les boutons des autres addons après un reload même désactivé.",
    ["wn_319_minimap_tracking"] = "Minimap : correction du bouton de pistage qui disparaissait parfois, et du bouton de pistage natif Blizzard qui restait non cliquable après avoir été révélé.",
    ["wn_319_repbar_hide"] = "Barre de réputation : correction de la barre de réputation/honneur Blizzard qui restait parfois visible malgré l'option « Masquer la barre de réputation Blizzard ».",
    ["wn_319_tooltip_bg"] = "Infobulle : fond par défaut moins transparent (opacité 92 % → 97 %) — toujours réglable via le curseur d'opacité du fond.",
    ["wn_319_tooltip_anchor"] = "Infobulle : le repère de position « Personnalisé » ne reste plus affiché en dehors du mode Layout, et un nouveau bouton « Afficher/Masquer le repère » a été ajouté dans Skins → Infobulle.",
    ["wn_319_diag_copy"] = "Diagnostics : correction du bouton « Copy Report » qui semblait ne rien faire — la fenêtre d'export pouvait s'ouvrir cachée derrière la console.",

    -- 3.1.11
    ["wn_3111_castbar_deathstuck"] = "Barres de sort : correction des barres de sort de cible, pisteur, boss et autres unités non-joueur qui pouvaient rester bloquées à l'écran si l'unité mourait ou disparaissait sans qu'aucun événement de fin de sort ne soit émis.",
    ["wn_3111_castbar_targetreset"] = "Barres de sort : changer de cible ou de pisteur réinitialise désormais complètement la barre de sort au lieu de simplement effacer son minuteur d'échec, empêchant un sort résiduel de l'ancienne unité de rester affiché sur la nouvelle.",
    ["wn_3111_ot_lfgbutton"] = "Suivi des quêtes : réduire une catégorie de quêtes masque désormais aussi son bouton « Recherche de groupe », pas seulement le bouton d'objet — les deux sont correctement restaurés lorsque la catégorie est de nouveau développée.",
    ["wn_3112_score_taint"] = "Tableau des scores Mythique+ : correction d'une série d'erreurs de corruption (taint) qui pouvait empêcher le tableau de fin de donjon de s'afficher/se positionner correctement si le joueur était encore en combat au moment où le donjon se terminait.",
    ["wn_3112_config_resize"] = "Fenêtre de configuration : la fenêtre /tm peut maintenant être redimensionnée en tirant son coin inférieur droit et mise à l'échelle via un nouveau curseur 70-130 % dans Général — taille par défaut augmentée à 1240x820, avec un bouton pour tout réinitialiser en un clic.",

    -- ChatFrameUI (panneau de config — libellés affichés dans Skins)
