    ["opt_compass_show_distance"]     = "Afficher la distance sur les marqueurs",
    ["opt_compass_show_quest"]        = "Afficher le marqueur de quête suivie",
    ["opt_compass_show_waypoint"]     = "Afficher le marqueur de point de carte",
    ["opt_skyride_ground_speed"]      = "Afficher la vitesse au sol",
    ["info_skyride_ground_speed"]     = "Affiche ta vitesse de déplacement même au sol (les jauges de vol restent masquées hors vol).",
    ["btn_class_reminder_preview"]    = "Aperçu",
    ["sublabel_class_reminder_coverage"]  = "— Buffs et formes suivis —",
    ["opt_char_skin_movable"]         = "Fenêtre déplaçable",
    ["info_char_skin_movable"]        = "Une fois activé, glisse la fenêtre Personnage pour la déplacer. Sa position est mémorisée.",
    ["btn_char_skin_reset_pos"]       = "Réinitialiser la position",
    ["btn_sound_test"]                = "▶ Écouter ce son",
    ["opt_auras_max_width"]           = "Largeur max (retour à la ligne)",
    ["opt_auras_per_row"]             = "Icônes par ligne",

    -- 3.2.0
    ["wn_320_gsearch"] = "Fenêtre de configuration : la recherche de la barre latérale est désormais globale — elle trouve les options correspondantes dans toutes les catégories et onglets, pas seulement sur la page visible, et cliquer sur un résultat y accède directement avec un flash de surbrillance.",
    ["wn_320_panelcache"] = "Fenêtre de configuration : le changement d'onglet de catégorie est désormais instantané après la première visite — les panneaux sont mis en cache au lieu d'être reconstruits à chaque fois.",
    ["wn_320_configlocale"] = "Fenêtre de configuration : tous les libellés en français codés en dur restants dans les panneaux de réglages sont désormais entièrement traduisibles.",
    ["cfg_tab_cdforge"]           = "Cooldowns",

    -- 3.2.1
    ["wn_321_cdf_intro"] = "Nouveau — CooldownForge : crée des barres de cooldown personnalisées par classe, suivant sorts, objets, presets (potions, pierre de soins...), bijoux ou ta capacité raciale, depuis le nouvel onglet Cooldowns (catégorie Combat).",
    ["wn_321_cdf_movers_io"] = "Les barres CooldownForge peuvent désormais être déplacées via le gestionnaire de déplacement unifié, et partagées entre personnages via une chaîne d'import/export par classe.",

    -- 3.2.2
    ["wn_322_studio_intro"] = "Nouveau — Cooldown Studio : un éditeur plein écran dédié aux barres CooldownForge, avec des onglets par barre Disposition/Style/Sorts/Visibilité/Partage, accessible depuis l'onglet Cooldowns.",
    ["wn_322_studio_fix"] = "Cooldown Studio : correction de la fenêtre qui ne s'affichait pas toujours au-dessus des autres fenêtres, et de ses widgets qui n'héritaient pas toujours de la bonne couleur d'accentuation.",
    ["wn_322_studio_visibility"] = "Cooldown Studio : ajout de la visibilité conditionnelle par barre — afficher ou masquer une barre selon le combat, l'instance, le groupe ou le raid, via de simples menus Indifférent/Oui/Non dans l'onglet Visibilité.",
    ["wn_322_studio_finestyle"] = "Cooldown Studio : ajout de réglages de style fins dans l'onglet Style — opacité, couleur/épaisseur de bordure, couleur de timer personnalisée et ombre portée.",
    ["wn_322_forge_internal"] = "Interne : extraction des mécanismes partagés de CooldownForge et Cooldown Studio dans une nouvelle bibliothèque interne Forge, posant les bases des futurs modules d'édition approfondie — aucun changement visible pour l'utilisateur.",
    ["wn_322_studio_fixes2"] = "Cooldown Studio : correction des boutons de la barre latérale (Nouvelle/Dupliquer/Renommer/Supprimer/modeles) qui ne répondaient parfois pas aux clics et débordaient de leur ligne, correction d'Echap qui fermait la fenêtre en provoquant une erreur de corruption (taint), et correction de l'onglet sélectionné qui se réinitialisait au lieu d'être mémorisé lors du changement de barre.",
    ["wn_322_studio_talents"] = "Cooldown Studio : la bibliothèque de sorts inclut désormais aussi tes talents et talents héroïques actifs, pas seulement les sorts du grimoire, pour pouvoir aussi les suivre sur une barre de cooldown.",
    ["wn_322_talent_scan_fix"] = "Cooldown Studio : correction du scan des talents/talents héroïques de la bibliothèque qui ne trouvait rien en jeu — seuls les talents réellement pris sont désormais pris en compte, avec le bon champ d'API pour lire ton choix sélectionné.",
    ["wn_322_diag_taintown"] = "Diagnostics : correction de faux rapports ADDON_ACTION_FORBIDDEN (UseToy, SetNote...) attribués à des addons au hasard — Diagnostics prend désormais possession exclusive des événements de taint au lieu de laisser la gestion native de Blizzard les repropager.",
    ["wn_322_actionbars_discover"] = "Barres d'action : le texte d'info de l'onglet Gestion des barres mentionne désormais aussi que déplier une barre révèle ses réglages de taille et d'échelle des boutons, rendant cette option plus facile à trouver.",
    ["wn_322_tracker_editmode"] = "Traqueur d'objectifs : correction du traqueur qui se figeait en place lorsqu'on le déplaçait pendant que l'Edit Mode natif de Blizzard était actif.",
    ["wn_323_studio_preview"] = "Cooldown Studio : l'onglet Style affiche désormais un aperçu d'icônes en direct (même rendu que les vraies barres) qui alterne entre les états prêt/en cooldown, pour voir les changements de style instantanément.",
    ["wn_323_studio_copystyle"] = "Cooldown Studio : ajout d'un bouton « Coller le style depuis... » dans l'onglet Style pour copier uniquement le style visuel d'une autre barre sans toucher aux sorts, à la position ou à la disposition.",
    ["wn_323_studio_create"] = "Cooldown Studio : « + Nouvelle » demande désormais le nom de la barre dès le départ au lieu de créer un espace réservé à renommer ensuite, et les popups de renommage/création s'affichent désormais de manière fiable au-dessus de la fenêtre avec le champ de nom auto-focalisé.",
    ["wn_323_slider_entry"] = "Curseurs de configuration : clic droit sur une valeur pour saisir un nombre exact, Ctrl+clic pour réinitialiser à la valeur par défaut, avec un rappel en infobulle pour les deux.",
    ["wn_323_petbar_editmode"] = "Barres d'action : les barres Familier et Formes peuvent désormais être sélectionnées et déplacées en mode édition même lorsqu'elles sont masquées au repos (pas de familier/formes).",
    ["wn_324_studio_real_icons"] = "Cooldown Studio : l'aperçu de l'onglet Style utilise désormais de vraies icônes — d'abord les sorts de la barre, puis le grimoire et les talents de ta classe — au lieu de trois icônes de démo codées en dur venant de classes sans rapport.",
    ["wn_324_chat_contacts"] = "Chat : la barre latérale du chat gagne un bouton Contacts qui ouvre la liste d'amis de Blizzard en un clic, rétablissant un accès que le masquage du bouton social natif par le skin avait supprimé.",
    ["wn_324_editbox_scrollbar"] = "Configuration : les zones de texte multilignes (import/export, notes...) n'affichent plus la barre de défilement dorée de Blizzard — elles utilisent désormais la fine barre d'accentuation de l'addon et gèrent la molette.",
    ["wn_325_friends_window"] = "Contacts : la fenêtre d'amis est désormais entièrement habillée au lieu d'un habillage à moitié fait — corps sombre et plat, bordure d'accentuation dessinée au-dessus de la liste, titre restylé et un simple bouton de fermeture à l'accent.",
    ["wn_325_friends_tabs"] = "Contacts : les onglets du bas et les sous-onglets Amis / Alliés récents / Recruter un ami ont perdu leurs plaques dorées, et affichent désormais un soulignement et un libellé à l'accent sur celui sélectionné.",
    ["wn_325_friends_buttons"] = "Contacts : tous les boutons de la fenêtre (Ajouter un ami, Envoyer un message, les boutons de l'onglet Recherche, Convertir en raid, Infos de raid, Rejoindre la file) partagent désormais un même style plat à l'accent qui s'éclaircit au survol, et les deux boutons de contact se partagent équitablement la rangée du bas.",
    ["wn_325_friends_toggle"] = "Contacts : désactiver le skin dans les réglages rétablit désormais l'apparence de Blizzard immédiatement, sans nécessiter de rechargement.",
    ["wn_325_cdf_radial"] = "CooldownForge : les barres de cooldown peuvent désormais disposer leurs icônes en cercle au lieu d'une ligne — règle le rayon, l'angle de départ, l'amplitude de l'arc et le sens via le nouveau mode de disposition.",
    ["wn_325_cdf_spacing"] = "CooldownForge : l'espacement des icônes se règle désormais en deux valeurs — le long de la rangée et entre les lignes de retour — et le maximum passe de 16 à 64 px.",
    ["wn_325_cdf_glow"] = "CooldownForge : le glow peut désormais se déclencher selon une condition au choix — quand le sort est prêt, tant qu'un buff est actif sur toi (avec un ID de buff optionnel pour les bijoux/talents), ou toujours — réglable par barre ou par sort.",
    ["wn_325_cdf_hidecd"] = "CooldownForge : une barre peut désormais masquer chaque icône pendant son cooldown, les icônes restantes se resserrant pour combler le trou ; elle se réorganise uniquement quand la liste des sorts prêts change.",
    ["wn_326_whatsnew_stuck"] = "Quoi de neuf : fermer cette fenêtre avec Échap laissait l'écran assombri et la souris inerte, et la version non marquée — elle revenait donc à la connexion suivante. Toutes les façons de fermer (croix, bouton, Échap) passent désormais par un seul endroit qui retire l'assombrissement et retient la version.",
    ["wn_326_whatsnew_escape"] = "Quoi de neuf : Échap est désormais capté par la fenêtre elle-même au lieu de passer par UISpecialFrames de Blizzard, ce qui supprime une source de taint via le menu du jeu ; toutes les autres touches continuent de passer.",
    ["wn_326_whatsnew_gates"] = "Quoi de neuf : la fenêtre attend maintenant un moment libre — jamais par-dessus une cinématique, une vidéo ou un combat — et saute entièrement la toute première connexion d'un personnage, pour ne plus t'accueillir en pleine séquence d'intro.",
    ["wn_326_tracker_empty"] = "Suivi d'objectifs : quand rien n'est suivi, le panneau sombre qui couvrait la majeure partie de l'écran a disparu — il se réduit désormais à son en-tête, et « Masquer si vide » est activé par défaut (les profils existants sont mis à jour une fois ; le désactiver à nouveau est définitif).",
    ["wn_326_tracker_drag"] = "Suivi d'objectifs : le panneau peut de nouveau être déplacé vers le bas — le maintien à l'écran s'appliquait au cadre de suivi surdimensionné de Blizzard, dont le bord inférieur était déjà hors écran, ce qui bloquait tout déplacement vers le bas.",
    ["wn_326_repbar_drag"] = "Barre de réputation : corrigé la barre qui affichait sa bordure de déverrouillage en mode Disposition mais refusait d'être attrapée — la souris n'y était jamais activée, le déplacement ne pouvait donc pas démarrer.",
    -- Supports du Cooldown Manager (Movers / mode disposition)
    ["mover_cdm"]                        = "Cooldown Manager",
    ["cdm_drag_hint"]                    = "Glisser pour déplacer",
    ["cdm_preview_aura"]                 = "Aura",

    ["wn_326_suite_card"] = "Config : le tableau de bord gagne une carte « Suite Tomo » présentant TomoBoss (minuteurs de boss avec annonces vocales) — un raccourci vers ses options s'il est installé, une adresse copiable et un « Ne plus afficher » définitif sinon.",

    ["wn_330_cdf_unusable"] = "CooldownForge : une icône peut désormais se teinter quand le sort est hors cooldown mais impossible à lancer sur le moment — pas assez de rage, mauvaise forme, réactif manquant. Trois choix : aucun effet (par défaut), griser, ou griser avec une teinte bleue quand c'est bien la ressource qui bloque ; réglable par barre et par sort.",
    ["wn_330_cdf_glow_usable"] = "CooldownForge : le glow a gagné une condition « quand le sort est utilisable » — prêt *et* lançable, pour qu'un sort à court de ressource cesse de briller pendant qu'il attend au lieu d'inviter à une pression qui échouerait.",
    ["wn_330_cdf_hide_unusable"] = "CooldownForge : une barre peut aussi masquer complètement une icône tant que la ressource manque, en plus du filtre « masquer pendant le cooldown » existant. Les deux sont indépendants et cumulables, et les icônes restantes se resserrent pour combler le trou.",
    ["wn_330_cp_charged"] = "Barres de ressources : les points de combo surchargés sont enfin affichés comme tels — l'emplacement chargé est marqué qu'il soit rempli ou non, pour voir où se trouve la charge avant de la dépenser. La couleur se règle dans CD & Ressources → Couleurs, rouge par défaut.",
    ["wn_330_colorpicker"] = "Configuration : le sélecteur de couleur s'ouvrait derrière la fenêtre des réglages et Cooldown Studio, ce qui donnait l'impression que la pastille ne faisait rien. Il s'ouvre maintenant au-dessus, juste à côté de la pastille cliquée plutôt qu'au centre de l'écran.",
    ["wn_330_locale_escapes"] = "Localisation : les options de la Boussole affichaient des codes d'échappement bruts à la place des accents — « dxC3xA9filer », « xC3x89chelle », « Large (xC2xB190xC2xB0) ». Ces textes utilisaient une syntaxe d'échappement que le Lua du jeu ne comprend pas et recopiait telle quelle ; ils sont de nouveau lisibles, dans les six langues.",
    ["wn_330_diag_filters"] = "Diagnostics : être cloué sur place et tenter d'envoyer par courrier un objet lié étaient enregistrés comme des erreurs dans le rapport. Ce sont des retours normaux du jeu, désormais filtrés comme le reste.",
    ["wn_330_tracker_delve_place"] = "Suivi d'objectifs : avec « Masquer si vide » décoché, le panneau restait affiché mais le bloc du gouffre n'y était jamais positionné — le cas « vide » sortait avant la passe qui le place. Les modules de scénario et de gouffre sont désormais placés en premier, quoi qu'il y ait d'autre en suivi.",
    ["wn_330_tooltip_info"] = "Infobulle : les infobulles d'unité affichent enfin une vraie couche d'informations — rang de guilde, cible de l'unité, score Mythique+, monture, vitesse de déplacement et lieu, plus les icônes de marqueur de raid, de rôle et de classe sur la ligne du nom. Chaque ligne a son propre interrupteur dans Skins → Infobulle.",
    ["wn_330_tooltip_inspect"] = "Infobulle : survoler un joueur affiche désormais son niveau d'objet équipé et sa spécialisation. Les deux nécessitent une inspection, donc ils n'apparaissent qu'à portée ; le niveau d'objet est coloré par l'écart avec le vôtre plutôt que par des seuils de saison qui périment à chaque patch.",
    ["wn_330_tooltip_border"] = "Infobulle : la bordure peut prendre la couleur de l'unité — couleur de classe pour un joueur, hostile / neutre / amical pour un PNJ — et la ligne de niveau est recolorée selon la difficulté, en rouge pour un boss ou une unité « ?? ».",
    ["wn_330_tooltip_bar"] = "Infobulle : la barre de vie est désormais masquée par défaut, la couche d'informations la remplace. Les profils existants sont mis à jour une fois ; décocher l'option remet la barre et ça tient.",
    ["wn_330_pf_leader"] = "Cadres de groupe : le chef de groupe est maintenant signalé par une couronne au-dessus de son cadre, avec son propre interrupteur et un curseur de taille.",
    ["wn_330_stance_bar"] = "Barres d'action : les classes sans forme de métamorphose se retrouvaient avec une barre de posture de dix cases vides, et décocher « afficher les emplacements vides » faisait disparaître la barre entière. Elle n'apparaît plus que si vous avez réellement des formes, avec exactement autant de boutons que de formes.",
    ["wn_330_leveling_panel"] = "Barre de niveau : la survoler ouvre maintenant un panneau stylisé au lieu d'une infobulle, avec le niveau, l'XP, l'XP restante, la progression, le repos, l'XP/h, le temps pour level, l'XP gagnée depuis le dernier passage de niveau et l'apport de la dernière quête. Il bascule sous la barre quand il n'y a pas la place au-dessus.",
    ["wn_330_bags_click"] = "Sacs : désenchanter, broyer ou prospecter depuis le skin de sacs demandait deux tentatives — l'appui consommait le curseur de ciblage et le relâchement ramassait l'objet à la place. Ça marche du premier coup maintenant, et le glisser-déposer n'est pas affecté.",
    ["wn_330_bags_layout"] = "Sacs : la disposition « Catégories » a été retirée, il reste Grille combinée et Sacs séparés. Un profil encore réglé dessus est basculé une fois sur la grille combinée.",
    ["wn_330_chat_copy"] = "Chat : l'icône de copie par message affichait un glyphe de remplacement devant chaque ligne, sa texture ne se résolvant jamais. L'option est supprimée, et effacée une fois pour ceux qui l'avaient activée.",

    ["wn_331_tooltip_secret"] = "Infobulle : toute la couche d'informations d'unité ajoutée en 3.3.0 n'apparaissait jamais sur Midnight — ni rang de guilde, ni cible, ni score Mythique+, ni monture, ni vitesse, ni lieu, ni niveau d'objet, ni spécialisation, ni icônes sur la ligne du nom. La couche relit le jeton d'unité depuis l'infobulle, le jeu le renvoie désormais comme une valeur protégée, et le garde-fou le rejetait : rien n'était jamais écrit.",
    ["wn_331_tooltip_border"] = "Infobulle : la bordure aux couleurs de l'unité était éteinte pour la même raison — elle relisait le jeton via son propre garde-fou et abandonnait, si bien que chaque unité retombait sur la couleur de bordure configurée, ce qui donnait exactement l'impression d'une option sans effet.",
    ["wn_331_tooltip_target"] = "Infobulle : la ligne de cible disparaissait pour tout joueur dont le nom revient protégé, c'est-à-dire la plupart. Le nom n'est plus enveloppé dans un code couleur — construire cette chaîne revient à lire le nom — et la couleur passe par les arguments de couleur de l'infobulle. Identique à l'écran, et fonctionnel.",
    ["wn_331_tooltip_guards"] = "Infobulle : les garde-fous eux-mêmes pouvaient lever une erreur. L'un comparait la valeur à une chaîne vide avant de vérifier si elle était protégée, il plantait donc précisément sur les valeurs qu'il devait intercepter, et une vingtaine de tests vrai/faux (l'unité existe-t-elle, est-ce un joueur, peut-on l'inspecter…) étaient comparés sans protection. Tout est vérifié dans le bon ordre désormais.",
    ["wn_331_inspect"] = "Infobulle : le niveau d'objet et la spécialisation reviennent avec le reste — le moteur d'inspection effectuait les mêmes comparaisons non protégées sur chaque test d'éligibilité, et renonçait sur une valeur protégée avant même d'envoyer une requête.",
    ["wn_330_tracker_delve"] = "Suivi d'objectifs : en gouffre, le suivi n'affichait plus rien — ni palier, ni critère, ni progression. « Masquer si vide » ne comptait que les blocs de quête, or un gouffre suit sa progression dans le module de scénario, que ce décompte laisse volontairement de côté : le panneau entier était donc masqué. Les gouffres, scénarios et objectifs bonus comptent désormais comme du contenu, et le panneau s'ajuste à leur taille quand ils sont seuls à l'écran.",
    ["wn_327_tracker_progressbars"] = "Suivi d'objectifs : les barres de progression des quêtes (compteurs de mobs, forces ennemies, critères de scénario et d'expédition) sont de retour — une barre n'est plus balayée comme orpheline quand son bloc n'est atteignable que par une ancre, elle survit à la fermeture puis réouverture de son groupe, et celles qui restent adoptent enfin le thème du reste du suivi.",
    ["wn_327_tracker_position"] = "Suivi d'objectifs : un suivi déplacé via l'Edit Mode natif de Blizzard revenait à son ancienne place au reload suivant — cette position n'était jamais écrite dans la base de l'addon. Elle est désormais sauvegardée à la fin de la session Edit Mode, et un suivi mis à une échelle autre que 100 % ne dérive plus un peu plus à chaque rechargement.",
    ["wn_327_minimap_indicators"] = "Minimap : le drapeau de difficulté d'instance restait affiché hors instance, car le ré-ancrage des indicateurs natifs les forçait aussi à être visibles et écrasait la règle de Blizzard. Ils suivent de nouveau la visibilité de Blizzard — et le bouton d'extension ne reste plus invisible définitivement une fois désactivé puis réactivé.",
    ["wn_327_resourcebar_frozen"] ="Barres de ressource : la barre de puissance centrée restait bloquée sur la valeur qu'elle avait à sa construction — 0 rage, 0 énergie — pour toutes les specs dont la seule ressource est la principale (Guerrier, Prêtre, Mage Feu, Tisse-brume, Dévastation...), alors que l'unitframe affichait la vraie valeur juste à côté. Elle se rafraîchit de nouveau comme les autres barres.",
    ["wn_327_profile_rename"] ="Profils : renommer ou dupliquer un profil ne faisait absolument rien — la refonte des popups en 11.2 a supprimé le champ dans lequel le gestionnaire lisait le nom saisi. Les deux fonctionnent à nouveau, et Entrée valide désormais comme le bouton de confirmation.",
    ["wn_327_cds_rename"] = "Cooldown Studio : même correctif pour les popups « Renommer la barre » et « + Nouvelle » — le nom saisi était ignoré, donc renommer ne faisait rien et chaque nouvelle barre s'appelait « Nouvelle barre ».",
    ["wn_327_popup_layer"] = "Popups : l'invite de rechargement, les fenêtres d'import / export et toutes les confirmations de profil s'affichaient derrière la fenêtre de config et Cooldown Studio, donnant l'impression qu'il ne se passait rien. Elles passent désormais au-dessus de la fenêtre TomoMod ouverte.",
    ["wn_327_profile_refresh"] = "Profils : créer, supprimer, renommer ou dupliquer un profil rafraîchit maintenant la liste à l'écran au lieu de laisser afficher l'ancienne, servie par le cache des pages.",
    ["wn_327_import_perf"] = "Profils : l'import est nettement plus rapide — la chaîne décodée pour l'aperçu est réutilisée à la validation au lieu d'être décodée une seconde fois, ce qui constituait l'essentiel du gel au clic sur Importer.",
    ["wn_327_gui_split"] = "Config : Profils et Diagnostics redeviennent deux catégories distinctes dans la barre latérale au lieu d'être regroupées sous Outils, chacune avec son icône et sa description ; les anciens liens vers Outils fonctionnent toujours.",

    -- =====================
    -- CHAT FRAME UI (cfui_*) -- were falling back to enUS
    -- =====================
    ["tab_skin_chatframeui"]             = "Interface de discussion",
    ["opt_cfui_enable_desc"]             = "Ajoute des conteneurs décoratifs, une barre de boutons, des icônes latérales et le changement de disposition (Placement). Rechargez l'interface après activation.",
    ["opt_cfui_show_tab_bar"]            = "Afficher la barre d'onglets",
    ["opt_cfui_tab_bar_offset"]          = "Décalage Y de la barre d'onglets",
    ["opt_cfui_window_offset"]           = "Décalage Y de la fenêtre",
    ["opt_cfui_x_offset"]                = "Décalage X",
    ["opt_cfui_y_offset"]                = "Décalage Y",
    ["cfui_show_chat_menu"]              = "Afficher le menu de discussion",
    ["cfui_show_professions"]            = "Afficher les métiers",
    ["cfui_show_shortcuts"]              = "Afficher les raccourcis d'addons",
    ["cfui_copy_chat"]                   = "Copier le texte de discussion",
    ["cfui_click_toggle_status"]         = "Cliquez pour basculer en absent",
    ["cfui_layout_button"]               = "Placement TomoMod",
