    ["cfui_btn_talents"]                 = "Talents",
    ["cfui_btn_achievements"]            = "Hauts faits",
    ["cfui_btn_calendar"]                = "Calendrier",
    ["cfui_btn_lfd"]                     = "Recherche de donjon",
    ["cfui_btn_raid"]                    = "Raid",
