    ["cfui_btn_collections"]             = "Collections",
    ["cfui_btn_macros"]                  = "Macros",
    ["cfui_btn_worldmap"]                = "Carte du monde",
    ["cfui_btn_questlog"]                = "Journal de quêtes",
    ["cfui_btn_reputation"]              = "Réputation",
    ["cfui_btn_pvpscore"]                = "Score JcJ",
    ["cfui_btn_currency"]                = "Monnaies",

    -- =====================
    -- 3.3.2 — Quoi de neuf
    -- =====================
    ["wn_332_perf_auras"] = "Performances : le suivi d'auras et l'habillage des buffs n'écoutent plus que vos propres changements d'auras. Ils n'ont jamais agi que sur vous, mais ils étaient réveillés pour chaque unité dont les auras changeaient — plus de vingt membres de raid et chaque plaque visible, en continu — uniquement pour vérifier l'unité et l'écarter. Le jeu les filtre désormais avant que le moindre code ne s'exécute.",
    ["wn_332_perf_castbar"] = "Performances : idem pour le suivi de latence de la barre d'incantation, réveillé par chaque sort de chaque unité visible — l'équivalent d'un pack de trash entier — alors que seuls vos propres sorts comptaient.",
    ["wn_332_perf_gc"] = "Performances : le suivi d'auras était la principale source de déchets mémoire de l'interface. Son analyse et son agencement tournaient plusieurs fois par seconde en combat et jetaient une pile de tables temporaires à chaque passage ; ils réutilisent maintenant les mêmes tables de travail. Rien ne change à l'écran.",
    ["wn_332_aura_order"] = "Suivi d'auras : deux auras appliquées par le même sort avec la même durée pouvaient visiblement permuter d'une actualisation à l'autre, faute d'un ordre défini. C'est stable désormais.",
    ["wn_332_skyride_leak"] = "Vol libre : /tm skyride reconstruisait une deuxième copie de la barre à chaque utilisation. L'ancienne restait à l'écran, plus reliée à rien et impossible à masquer, car le jeu ne récupère jamais un cadre. La barre n'est plus construite qu'une fois et la commande se contente d'y réappliquer vos réglages.",
    ["wn_332_skyride_ticker"] = "Vol libre : la même commande laissait aussi derrière elle, à chaque fois, une mise à jour permanente à 4 Hz qu'il devenait impossible d'arrêter. Elles ne se cumulent plus, et la mise à jour s'arrête quand le module est désactivé au lieu d'interroger une barre masquée.",
    ["wn_332_tooltip_incombat"] = "Infobulle : le niveau d'objet et la spécialisation disparaissaient de toutes les infobulles dès qu'un combat commençait, et revenaient à la fin. Le test de portée sur lequel s'achevait le moteur d'inspection fait partie de ceux que le jeu refuse de répondre aux addons en combat : toutes les unités étaient donc jugées hors de portée pendant tout le pack — pendant que le journal de contamination se remplissait d'un appel bloqué par survol. Il utilise désormais un test qui fonctionne en combat.",
    ["wn_332_tooltip_backoff"] = "Infobulle : le test de portée de remplacement est moins précis (il voit bien plus loin qu'une inspection ne porte réellement) ; un joueur trop éloigné pour répondre est donc mémorisé et laissé de côté pendant vingt secondes au lieu d'être resollicité à chaque infobulle. Une seule inspection peut être en cours à la fois, et un joueur hors de portée monopolisait cette place encore et encore. Une infobulle restée sans réponse ne reste par ailleurs plus bloquée sur « chargement ».",
    ["wn_332_diag_nopath"] = "Diagnostics : charger par-dessus un vide, bondir sur une corniche ou envoyer un familier là où il ne peut pas marcher était consigné comme une erreur dans le rapport. « Aucun chemin disponible » est un retour de jeu normal, et il est désormais filtré dans les six langues.",
    ["wn_332_locale_castbar"] = "Configuration : la case principale du panneau Barres d'incantation affichait « Activer la barre de consommables » dans toutes les langues — deux options différentes partageaient la même clé de traduction, et celle des consommables l'emportait. Chacune a la sienne maintenant.",
    ["wn_332_locale_translations"] = "Localisation : 173 chaînes par langue traduites en allemand, espagnol, italien et portugais — réglages avancés et de visibilité du gestionnaire de sorts, catégories de quêtes du suivi d'objectifs, interface de discussion, déplacements et textures de curseur — ainsi que les 49 chaînes de l'interface de discussion en français. Elles retombaient discrètement sur l'anglais au lieu d'afficher une erreur, personne ne les avait donc signalées.",
    ["wn_332_locale_search"] = "Configuration : la zone de recherche affichait le texte brut « gs_no_results » au lieu de « Aucune option correspondante » quand rien ne correspondait. Le message est défini dans les six langues.",
    ["wn_332_package"] = "Paquet : le téléchargement n'embarque plus les suites de tests, exemples, documentations générées et fichiers readme des bibliothèques incluses. Rien de tout cela n'était chargé par l'addon.",
    ["wn_332_companion_panel"] = "Rappel de familier : le module qui vous prévient quand votre familier est absent ou mort dispose enfin d'un panneau de réglages, dans QOL. Son activation, sa taille, son échelle, l'affichage de l'icône, du texte ou des deux, et sa position à l'écran n'étaient jusqu'ici modifiables qu'en éditant un fichier à la main.",
    ["wn_332_companion_travel"] = "Rappel de familier : il pouvait rester à l'écran, à quatre fois sa taille, pendant tout un vol. Il ne vérifiait si vous voliez qu'à des moments où vous étiez encore au sol, et plus rien ne pouvait le masquer ensuite. Il est désormais masqué en vol, en trajet de vol et en véhicule — ainsi qu'en monture au sol, ce que vous pouvez désactiver.",
    ["wn_332_companion_locale"] = "Rappel de familier : « Familier absent » et « Familier mort » s'affichaient en anglais quelle que soit la langue du client. Les deux sont traduits, comme tout le nouveau panneau.",

    -- =====================
    -- 3.3.3 — Quoi de neuf
    -- =====================
    ["wn_333_summon_stuck"] = "Cadres de groupe et de raid : l'icône d'invocation restait affichée jusqu'au rechargement de l'interface. Une fois que vous acceptez ou refusez, le jeu continue de renvoyer le dernier état de l'invocation au lieu de l'effacer — l'icône décrivait donc quelque chose qui n'existait plus depuis plusieurs minutes. Elle vérifie maintenant qu'une invocation est réellement en cours avant d'afficher quoi que ce soit.",
    ["wn_333_summon_roster"] = "Cadres de groupe et de raid : lors d'un changement de composition, une icône d'invocation pouvait rester sur un cadre appartenant désormais à un autre joueur. L'état est relu à chaque changement de composition et après chaque changement de zone, et il est rafraîchi avec le reste du cadre au lieu de l'être uniquement quand le jeu signale un changement.",
    ["wn_333_defensives_party"] = "Cadres de groupe : les temps de recharge défensifs actifs sur chaque membre sont désormais affichés. Ils n'existaient que sur les cadres de raid, et il s'agissait d'une seule icône, sans durée et sans indication de sa nature.",
    ["wn_333_defensives_categories"] = "Cadres de groupe et de raid : les défensifs sont répartis en externes (lancés sur ce joueur — Écorce de fer, Cocon de vie, Suppression de la douleur), collectifs (Cri de ralliement, Ténèbres, Zone antimagie) et personnels (Bouclier divin, Bloc de glace, Peau d'écorce), chacun avec sa propre option. Cinquante sorts, triés pour que les externes passent en premier, avec le temps restant et un cadre coloré par catégorie.",
    ["wn_333_defensives_defaults"] = "Cadres de groupe et de raid : seuls les externes sont affichés par défaut. Un défensif collectif allume tous les cadres en même temps — exactement au moment où ils sont le moins lisibles — et les personnels sont permanents. Les deux peuvent être activés.",
    ["wn_333_defensives_size"] = "Cadres de raid : le curseur de taille des icônes défensives ne prenait effet qu'après un rechargement. Il s'applique désormais pendant que vous le déplacez.",
    ["wn_333_hots_drift"] = "Cadres de groupe et de raid : les deux jeux de cadres n'étaient pas d'accord sur les soins sur la durée à afficher. Bénédiction de l'été, Totem de salve de nuages et Souffle enveloppant apparaissaient sur les cadres de groupe mais pas sur ceux de raid — le même buff, sur le même joueur, visible d'un côté et pas de l'autre. Il n'y a plus qu'une seule liste, couvrant les six classes de soigneur.",
    ["wn_333_dispel_border"] = "Cadres de groupe et de raid : l'épaisseur du cadre de dissipation est désormais réglable, de 1 à 6. Il s'étend vers l'extérieur, donc un cadre plus épais n'empiète jamais sur la barre de vie, et la valeur par défaut est identique à l'affichage précédent.",
    ["wn_333_stance_grid"] = "Barres d'action : avec « afficher les emplacements vides » désactivé, la barre de postures pouvait quand même afficher dix cases vides, et elles restaient là jusqu'à ce que vous changiez de posture. La passe qui révèle les emplacements vides pendant que vous déplacez un sort s'appliquait aussi aux barres de postures et de familier, dont les boutons ne sont pas des emplacements d'action — elle les considérait donc tous comme vides et les affichait, tandis que la passe qui les masque à nouveau ignore délibérément ces deux barres, si bien que plus rien ne les remasquait.",
    ["wn_333_diag_display"] = "Diagnostics : les rapports contiennent maintenant votre résolution, votre mode d'affichage et votre échelle d'interface — et signalent le cas où l'échelle a été réglée par autre chose que les options du jeu. Au-delà de 1200 pixels de hauteur, le client refuse de réduire suffisamment l'échelle, donc les configurations haute résolution finissent redimensionnées à la main ou par un autre addon, ce qui était invisible dans un rapport.",
    ["wn_333_diag_scalechange"] = "Diagnostics : un changement d'échelle ou de résolution en cours de session est consigné avec ses valeurs avant et après, pour qu'un redimensionnement apparaisse à côté des erreurs qu'il a pu provoquer. Ce redimensionnement est réappliqué après chaque écran de chargement, et c'est précisément là qu'il casse des choses.",
    ["wn_333_diag_perf"] = "Diagnostics : les rapports indiquent désormais le nombre d'images par seconde (actuel, ainsi que le minimum, la moyenne et le maximum de la session) et la latence, et chaque erreur capturée enregistre le nombre d'images par seconde au moment où elle s'est produite. Une erreur qui n'apparaît que sur un client qui saccade est un problème de synchronisation et non une fonctionnalité cassée, et rien dans un rapport ne permettait de les distinguer.",
    ["wn_333_diag_scale_expected"] = "Diagnostics : le rapport affirmait que votre échelle d'interface avait été réglée par une macro ou un autre addon sur presque toutes les configurations. Quand l'option d'échelle d'interface du jeu est désactivée, la valeur à laquelle il se comparait n'est pas celle que le jeu utilise, et une configuration parfaitement ordinaire était donc signalée. Il calcule maintenant l'échelle attendue pour votre résolution et vos réglages, l'affiche, et n'avertit que lorsqu'il y a un véritable écart.",
    ["wn_333_diag_settle"] = "Diagnostics : l'échelle que le jeu applique de lui-même pendant la connexion était consignée dans chaque rapport comme un redimensionnement en cours de session. La capture d'affichage attend désormais quatre secondes que le client se stabilise avant de prendre une mesure, si bien que la seule entrée d'échelle qui subsiste dans un rapport est celle qui mérite vraiment une explication.",
    ["wn_333_diag_mode"] = "Diagnostics : quand le rapport n'arrive pas à déterminer votre mode d'affichage, il indique maintenant les valeurs brutes renvoyées par le jeu au lieu d'un simple point d'interrogation — ces noms de réglages changent d'une extension à l'autre, et un « ? » seul ne pouvait pas être diagnostiqué sans revenir vers vous. Le plein écran fenêtré et les fenêtres agrandies sont reconnus dans davantage de cas, et les versions des addons ne s'affichent plus sous la forme « vv1.2.3 ».",
    ["wn_333_shared"] = "Interne : les cadres de groupe et de raid conservaient deux copies des mêmes 250 lignes — la logique d'invocation, la liste des soins sur la durée, le suivi des défensifs. Les trois correctifs ci-dessus en découlent tous : un correctif appliqué à une copie et pas à l'autre. Ils partagent désormais une seule implémentation.",
    -- =====================
    -- 3.6.4 — What's New
    -- =====================
    ["wn_364_studio"] = "Nouveau — Studio Mythic+ : une fenêtre Mythic+ dédiée avec onze pages — Tableau de bord, Tracker, TomoScore, Clés, Historique des runs, Statistiques, Planning hebdomadaire, Planificateur de score, Analyse par niveau, Objectifs de saison et Modules. C'est un addon séparé, chargé uniquement à sa première ouverture ou au démarrage d'une clé : il ne coûte rien tant que tu ne t'en sers pas.",
    ["wn_364_open"] = "Nouveau — Ouvre le Studio avec /tmplus, ou avec le nouveau bouton de la page d'options Mythic+. L'ancienne fenêtre Mythic+ ouvre désormais le nouveau tableau de bord elle aussi ; sa vue détaillée des donjons et du coffre est conservée et reste accessible depuis le Studio. Le demander en combat ne reste plus sans effet : il s'ouvre dès la fin du combat, et te le dit.",
    ["wn_364_history"] = "Nouveau — L'historique des runs enregistre chaque clé Mythic+ que tu termines à partir de maintenant : donjon, niveau, temps, dans les temps ou non, morts, affixes, score gagné et splits de boss. Il démarre vide — les runs passés du jeu sont affichés pour le contexte mais ne sont jamais transformés en historique local — et conserve tes 100 dernières clés.",
    ["wn_364_statistics"] = "Nouveau — Une page Statistiques construit des chiffres de saison et par donjon à partir de cet historique : nombre de runs, taux de réussite dans les temps, temps moyen et morts en moyenne.",
    ["wn_364_compare"] = "Nouveau — Deux runs enregistrés peuvent être placés côte à côte, avec leurs splits de boss et l'écart entre eux. Comparer des runs de donjons différents est autorisé : les splits sont alors alignés uniquement par position, et la page le précise.",
    ["wn_364_weekly"] = "Nouveau — Un planning hebdomadaire affiche tes trois emplacements Donjons de la semaine, ta meilleure clé de la semaine et le nombre de clés terminées qu'il te reste à faire pour remplir le suivant.",
    ["wn_364_score_planner"] = "Nouveau — Un planificateur de score propose le prochain niveau de clé à faire et ce qu'il rapporterait. Le chiffre est une estimation de planification : le score de donjon enregistré par le jeu reste la référence.",
    ["wn_364_analysis"] = "Nouveau — L'analyse par niveau détaille ton historique niveau par niveau — runs, dans les temps, taux de réussite, temps moyen et morts — et met en avant ton niveau de confort : le plus haut niveau où tu as au moins trois runs et où tu finis dans les temps sept fois sur dix.",
    ["wn_364_goals"] = "Nouveau — Les objectifs de saison suivent ton score, ta meilleure clé, les clés réussies dans les temps au niveau de ton choix, ton total de runs enregistrés et le fait d'avoir fait tous les donjons de la saison à un niveau donné, chacun avec la cible que tu fixes.",
    ["wn_364_tracker_colors"] = "Nouveau — Le tracker Mythic+ peut utiliser tes propres couleurs : accent, fond, en-tête, texte, forces ennemies et les trois couleurs du chrono. Les nuances plus sombres et plus claires sont dérivées de l'accent : un seul choix garde l'ensemble cohérent. Option désactivée, le tracker est exactement comme avant.",
    ["wn_364_tracker_position"] = "Nouveau — La page Tracker propose un aperçu en direct du tracker et un mode de positionnement qui affiche le vrai tracker à l'écran avec Valider, Annuler et Réinitialiser, pour le placer sans lancer de clé. Pendant une clé en cours, le positionnement est refusé plutôt que de déplacer le cadre que tu es en train de lire.",
    ["wn_364_keys"] = "Modifié — Les clés de ton groupe, le tracker et le tableau de score de fin de clé ont chacun leur page dans le Studio. Ils continuent de tourner dans TomoMod lui-même : ils fonctionnent donc toujours avant même que le Studio ait été ouvert.",
    ["wn_364_mplus_appearance"] = "Nouveau — Le Studio Mythic+ a une page Apparence : taille du texte, échelle de la fenêtre, opacité du fond et une couleur d'accent à toi, avec un aperçu en direct et un bouton de réinitialisation. Ça ne change que le Studio — les couleurs de ton tracker restent où elles sont, sur la page Suivi en donjon.",
    ["wn_364_mplus_reward_ilvl"] = "Nouveau — Chaque emplacement du Grand coffre, sur le tableau de bord comme dans le planning hebdomadaire, affiche désormais l'ilvl de la récompense qu'il donnerait, sous le niveau de clé. Quand le jeu ne répond pas pour un niveau, un tiret s'affiche plutôt qu'une estimation.",
    ["wn_364_mplus_tracker_preview"] = "Modifié — L'aperçu réel du tracker est maintenant une bascule : le même bouton l'ouvre et le range, et il se ferme tout seul quand tu quittes la page Tracker ou que tu fermes le Studio. Pendant une clé en cours, il refuse de se masquer : un aperçu ouvert avant le pull ne peut pas te retirer le vrai tracker de l'écran en pleine course.",
    ["wn_364_hot_size"] = "Correction — Changer la taille de tes icônes de HoT les redimensionne enfin sur les cadres de groupe et de raid, que tu la changes avec le curseur des pages Cadres de groupe et Cadres de raid ou dans le Healer Studio. Leur emplacement, lui, était bien appliqué, ce qui faisait passer le problème pour un souci d'affichage : seule la taille était perdue, et une icône apparue après le changement revenait encore à son ancienne taille.",
    ["wn_364_hot_sliders"] = "Correction — Les curseurs de taille d'icône HoT et de HoTs max des pages Cadres de groupe et Cadres de raid s'appliquent immédiatement. Ils étaient enregistrés dans ton profil mais jamais appliqués aux cadres à l'écran : la rangée de HoTs gardait son apparence précédente jusqu'au rechargement suivant.",
    ["wn_364_hot_duration"] = "Nouveau — Les secondes affichées sur tes icônes de HoT peuvent être masquées. L'icône garde son balayage de temps, donc tu vois toujours le temps s'écouler : tu perds seulement le nombre écrit par-dessus, qui sur une petite icône en recouvre presque toute l'image. Le choix est le tien, et il se règle séparément pour les cadres de groupe, les cadres de raid et le Healer Studio : tu peux garder les chiffres d'un côté et seulement le balayage de l'autre. Laisse l'option activée et rien ne change.",
    ["wn_364_hot_max_size"] = "Modifié — Les icônes de HoT peuvent être bien plus grandes : jusqu'à 50 pixels dans le Healer Studio au lieu de 30, et les curseurs de taille d'icône HoT des pages Cadres de groupe et Cadres de raid montent aussi à 50 au lieu de s'arrêter à 20 et 16. Rien n'empêche une icône de recouvrir toute une cellule, et c'est volontaire : une grande icône se lit parfois mieux en plein pull qu'une rangée de petites.",
    ["wn_364_mythichub_keys"] = "Correction — L'ancienne fenêtre Mythic+ ne capte plus ton clavier. Elle se fermait avec Échap, et une fenêtre qui écoute les touches peut avaler celles dont le jeu a besoin — tes touches de déplacement, le saut, tes raccourcis — tant qu'elle est ouverte. Elle est désormais entièrement à la souris, comme TomoScore et le Mythic+ Studio : ferme-la avec sa croix.",
    ["wn_364_teleport_menu"] = "Nouveau — Ta feuille de personnage gagne un bouton qui ouvre les téléportations de donjon Mythic+ de la saison en cours, toutes au même endroit. Clique sur un donjon pour t'y téléporter. Les téléportations que tu n'as pas encore débloquées restent affichées, grisées, pour voir d'un coup d'œil ce qu'il te reste à obtenir. Le panneau suit la saison tout seul, et il est indisponible en combat.",

    -- =====================
    -- 3.6.3 — What's New
    -- =====================
    ["wn_363_aura_display"] = "Correction — Les icônes d'auras s'affichent de nouveau sur tous les cadres qui passent par le système d'auras du jeu : les indicateurs de Healer Studio, les rangées de soins sur la durée des cadres de groupe et de raid, les indicateurs d'affaiblissements et de dissipation, les auras des barres de noms et celles des cadres d'unité. Leur affichage recevait bien une unité mais n'était jamais activé : il avait tout ce qu'il fallait et ne montrait rien.",
    ["wn_363_aura_spacing"] = "Correction — L'espacement que tu définis entre les icônes d'auras est de nouveau appliqué. Il était transmis au jeu sous les anciens noms d'options, que le système d'auras actuel ignore : chaque rangée était donc dessinée avec l'écart par défaut du jeu, quel que soit ton réglage.",
    ["wn_363_aura_size"] = "Correction — Changer la taille ou le nombre d'icônes d'auras prend de nouveau effet immédiatement. La modification était appliquée en reconstruisant le groupe d'icônes, ce que le jeu n'autorise plus : les icônes gardaient donc leur taille précédente jusqu'à la reconstruction des cadres, c'est-à-dire en pratique jusqu'à un rechargement. Les icônes déjà à l'écran sont désormais redimensionnées sur place, et pas seulement celles qui apparaissent ensuite.",
    ["wn_363_aura_recycle"] = "Correction — Une cellule de groupe ou de raid, ou une barre de nom, réattribuée à une nouvelle unité n'affiche plus les auras de l'unité précédente. Libérer un cadre désactive maintenant son affichage d'auras, ce qui en efface les icônes, au lieu de seulement détacher l'unité en laissant l'affichage à l'écoute.",
    ["wn_363_healer_studio"] = "Correction — Healer Studio profite de tout ce qui précède : ses indicateurs apparaissent dès qu'un sort est sélectionné, le curseur de taille déplace aussi les icônes déjà à l'écran, et désactiver un sort efface son icône immédiatement au lieu de la laisser sur une cellule recyclée.",
    ["wn_363_probe"] = "Correction — Le suivi des buffs du Cooldown Studio s'arrête complètement quand une icône cesse de suivre un buff, au lieu de laisser un observateur inutilisé tourner jusqu'à la fin de la session.",
    ["wn_363_revive_color"] = "Correction — Un joueur ressuscité ne conserve plus la teinte grise de la mort sur son cadre de groupe ou de raid. Le cadre était repeint alors que le jeu signalait encore le joueur comme mort, et plus rien ne le repeignait ensuite : la mauvaise couleur restait donc jusqu'à un rechargement. Il est désormais repeint au moment où l'état du joueur change réellement, ce qui couvre aussi une déconnexion suivie d'un retour.",
    ["wn_363_tomoscore_keys"] = "Correction — Le tableau des scores de fin de donjon ne bloque plus tes touches de déplacement. Il s'ouvre tout seul à la fin d'une clé, et il était réglé pour réagir au clavier afin qu'Échap puisse le fermer, ce qui pouvait empêcher tes touches de déplacement d'atteindre le jeu. Il fonctionne de nouveau uniquement à la souris : ferme-le avec son bouton, toutes les touches continuent de fonctionner pendant qu'il est affiché.",
    ["wn_363_raid_event_gate"] = "Modification — Les cadres de raid n'écoutent plus les mises à jour de vie, de ressource et d'auras quand tu n'es pas en raid. Le module était réveillé par chaque unité du jeu — membres du groupe, barres de noms, boss, ta cible — pour chercher un cadre de raid qui ne pouvait pas exister. Il s'abonne désormais quand tu rejoins un raid et s'arrête quand tu le quittes, y compris en plein combat.",
    ["wn_363_leveling_bar"] = "Correction — La barre de progression peut de nouveau être activée. Son cadre était publié sous le même nom global que le module qui le pilote : construire la barre une seule fois remplaçait donc le module, et à partir de là l'option, les curseurs de largeur et de hauteur, le déplaceur et /tm sr ne faisaient plus rien sans le moindre message — cocher la case laissait le réglage activé sans aucune barre à l'écran.",
    ["wn_363_dk_runes"] = "Modification — Les runes de Chevalier de la mort sont dessinées avec un remplissage uni au lieu de la texture de barre à dégradé partagée. Le dégradé fait office de reflet sur une grande barre de vie, mais sur six petits segments de rune il ne faisait que brouiller la couleur.",
    ["wn_363_forge_drag"] = "Modification — Dans AstralForge, déposer un élément l'accroche désormais au coin, au bord ou au centre le plus proche de ce sur quoi il repose, exactement comme le faisait déjà Healer Studio. Le point d'accroche ne changeait jamais : pousser une pièce dans un coin la laissait suspendue au milieu du cadre par un long décalage, et elle se déplaçait dès que le cadre était redimensionné. Les éléments que tu avais volontairement accrochés à un autre élément plutôt qu'au cadre conservent ce lien.",
    -- =====================
    -- 3.6.2 — What's New
    -- =====================
    ["wn_362_healer_studio"] = "Nouveau — Healer Studio : choisis exactement lesquels de tes soins sur la durée, boucliers et buffs de soin s'affichent sur les cadres de groupe et de raid, et place chaque icône où tu veux sur la cellule. Il remplace la rangée fixe d'icônes de HoT par ta propre disposition, et Groupe et Raid en conservent chacun une. Disponible pour le Prêtre, le Druide, le Paladin, le Chaman, le Moine et l'Évocateur.",
    ["wn_362_healer_editor"] = "Nouveau — La disposition se construit dans une fenêtre dédiée, ouverte depuis Cadres de groupe ou Cadres de raid, onglet Fonctionnalités. Fais glisser une icône sur l'aperçu de la cellule pour la placer, ou règle sa taille, son ancrage et ses décalages exacts avec les contrôles à côté — tout est enregistré au fur et à mesure, sans bouton Appliquer ni rechargement. Un preset de base active les premiers sorts de ta classe, et tu peux préparer la disposition de n'importe quelle classe de soigneur, pas seulement celle que tu joues.",
    ["wn_362_healer_preview"] = "Nouveau — L'aperçu de Healer Studio est ta propre cellule, agrandie : il reprend la largeur et la hauteur réellement réglées pour tes cadres de groupe ou de raid, donc ce que tu places est ce que tu obtiens en jeu. Une icône lâchée s'aimante au coin, au bord ou au centre le plus proche, ce qui lui permet de rester en place si tu redimensionnes tes cadres plus tard.",
    ["wn_362_healer_profile"] = "Nouveau — Les dispositions de Healer Studio sont enregistrées avec le reste de tes réglages : elles suivent l'export d'un profil et reviennent à l'import, au lieu d'être perdues en route.",
    ["wn_362_healer_spec"] = "Nouveau — Par défaut, la disposition avancée ne s'applique qu'en spécialisation de soin : tes spés Ombre ou Farouche conservent la rangée de HoT classique sans que tu aies à changer quoi que ce soit. Le passage d'une spé à l'autre bascule entre les deux tout seul, sans rechargement.",
    ["wn_362_healer_legacy"] = "Note — Rien ne change tant que tu n'actives pas Healer Studio : il est désactivé pour les cadres de groupe comme de raid, et la rangée de HoT classique continue de fonctionner exactement comme avant. Tu peux aussi désactiver complètement cette rangée et ne garder que tes propres icônes placées.",
    ["wn_362_vault_types"] = "Correction — L'aperçu de la Grande Chambre forte du Mythic Hub lit désormais ses lignes Raids, Donjons et Gouffres à partir des types de récompense officiels de Blizzard, au lieu de les deviner d'après ce que l'API des récompenses hebdomadaires renvoyait : la ligne Gouffres n'apparaît donc plus vide ni remplie des activités d'une autre ligne.",
    ["wn_362_vault_progress"] = "Correction — L'aperçu de la Grande Chambre forte ne force plus le rafraîchissement de la fenêtre Récompenses hebdomadaires de Blizzard avant de lire ta progression. Ce rafraîchissement remet la progression des activités à zéro tant qu'une récompense précédente n'a pas été récupérée, ce qui affichait 0 pour des donjons, des boss de raid et des gouffres pourtant terminés.",
    ["wn_362_vault_slots"] = "Correction — Chaque ligne de la Grande Chambre forte demande désormais ses propres activités au jeu et les trie par palier de récompense : les entrées supplémentaires renvoyées par l'API à côté des vraies lignes (récompenses bonus et de rattrapage) ne peuvent plus occuper un emplacement visible.",
    ["wn_362_ab_release"] = "Correction — Les boutons d’action réagissent de nouveau au relâchement du clic. Il manquait aux boutons de TomoMod l’attribut sécurisé de relâchement que Blizzard installe sur ses propres boutons d’action : avec « Lancer à l’appui de la touche » désactivé, plus rien n’était lancé, et les sorts à maintenir comme les sorts focalisés de l’Évocateur pouvaient être commencés mais jamais relâchés.",
    ["wn_362_ab_release_gse"] = "Correction — Un bouton qui a servi à une séquence GSE retrouve désormais le comportement d’appui et de relâchement d’une action normale dès que son action change, au lieu de conserver le contrat GSE jusqu’au prochain rechargement.",
    ["wn_362_ab_cooldown_push"] = "Correction — Les balayages de temps de recharge des boutons d’action suivent désormais exactement le jeu. TomoMod conservait une copie éphémère de l’état de recharge de chaque bouton et la réutilisait pendant une fraction de seconde, ce qui pouvait masquer le début ou la fin d’une recharge — surtout sur les recharges courtes et pendant le court instant où le serveur confirme un sort. Cet état est maintenant relu à chaque fois, les lectures répétées au sein d’une même passe de rafraîchissement restant mutualisées.",
    ["wn_362_ab_counts"] = "Correction — Les compteurs de charges et de cumuls des barres d'action ne déclenchent plus un rafraîchissement complet de tous les boutons à chaque événement d'aura ou de charge. Lors des gros packs en Mythique+, ces événements arrivent en rafales ; en combat, le travail est désormais regroupé quelques fois par seconde, ce qui garde les appuis de touche réactifs. Hors combat, rien n'est limité.",
    ["wn_362_ab_glow"] = "Correction — Le passage de sécurité qui efface les halos de proc résiduels ne réanalyse plus tous les boutons d'action visibles à chaque événement de halo. Le bouton qui perd son halo est toujours mis à jour instantanément, et la vérification complète ne s'exécute plus qu'au maximum dix fois par seconde : les combats riches en procs ne coûtent donc plus de latence d'entrée.",
    ["wn_362_ab_assist_rotation"] = "Modifié — Le Combat assisté localise désormais ses boutons d'action via l'API dédiée aux emplacements de Combat assisté du jeu, au lieu de parcourir toutes les barres à la recherche du sort actuellement suggéré : un changement de suggestion ne touche donc plus de boutons sans rapport.",
    ["wn_362_ab_assist_load"] = "Correction — Un changement de suggestion du Combat assisté ne rafraîchit plus tous les boutons d'action TomoMod, et TomoMod n'accroche plus une fonction de surbrillance de Blizzard qui peut être appelée à la cadence de la rotation en combat. À elles deux, ces sources constituaient l'essentiel du travail supplémentaire lorsque la rotation One Button était active.",
    ["wn_362_ab_assist_highlight"] = "Correction — La surbrillance du Combat assisté est désormais effacée quand le jeu cesse de suggérer un sort, et l'activation ou la désactivation de l'option de surbrillance assistée de Blizzard prend effet immédiatement au lieu de nécessiter un rechargement.",
    ["wn_362_rb_toggles"] = "Nouveau — Deux nouvelles options sous Animations & Barre de puissance : l’une désactive le glow qui apparaît quand une ressource de classe atteint son maximum, l’autre désactive l’affichage des points de combo surchargés du Voleur. Les deux sont activées par défaut, et en désactiver une restaure immédiatement l’apparence normale des points déjà à l’écran.",
    ["wn_362_rb_glow_stop"] = "Correction — Le glow de ressource au maximum ne reste plus affiché alors qu’il devrait avoir disparu. Il est désormais arrêté quand l’option est désactivée et quand l’affichage de ressource de classe est reconstruit, au lieu de continuer à tourner sur un cadre déjà abandonné.",
    -- =====================
    -- 3.6.1 — What's New
    -- =====================
    ["wn_361_assist"] = "Correction — Le cadre de rotation Combat assisté de Blizzard s’affiche et se met à jour désormais correctement sur les boutons d’action TomoMod, au lieu de se figer sur le champ d’action Lua non synchronisé du bouton.",
    ["wn_361_keydown"] = "Correction — Le réglage « Lancer à l’appui de la touche » de TomoMod reste désormais synchronisé avec la CVar d’entrée propre de Blizzard, corrigeant une première pression après connexion qui pouvait être silencieusement ignorée.",
    ["wn_361_safewindow"] = "Correction — Les liaisons override différées par le combat après un /reload en combat se rejouent désormais de façon fiable après le combat, au lieu de dépendre d’une fenêtre de sécurité qui pouvait elle-même autoriser des actions bloquées.",
    ["wn_361_strata"] = "Correction — Les boutons de la Barre d’action 1, Familier et Postures ne s’affichent plus au-dessus des panneaux plein écran de Blizzard tels que la Carte du monde.",
    ["wn_361_flyouts"] = "Correction — Les flyouts de sorts comme Portail/Téléportation du Mage s’ouvrent et lancent de nouveau correctement ; TomoMod ne redimensionne plus les boutons de flyout natifs d’une façon qui pouvait contaminer (taint) le flyout sécurisé.",
    ["wn_361_flyouts_cast"] = "Correction — Les boutons popup natifs du flyout ne sont plus accrochés (hook) ni modifiés du tout, car même des changements cosmétiques pouvaient contaminer (taint) le chemin protégé CastSpellByID/CastSpellByName de Blizzard.",
    ["wn_361_flyout_secure"] = "Correction — Les boutons d’action TomoMod actualisent désormais leur flyout de sorts via la fonction UpdateFlyout de Blizzard, exécutée dans un appel sécurisé, et les méthodes de popup de remplacement de TomoMod ont été retirées des boutons possédés. La flèche du flyout, le popup qu’elle ouvre et le lancement qui suit restent entièrement sur le chemin protégé de Blizzard.",
    ["wn_361_bar6_quarantine"] = "Correction — Les flyouts de sorts de la Barre 6 ne risquent plus de devenir interdits à lancer : cette barre utilise désormais le flyout sécurisé propre à TomoMod plutôt que celui natif de Blizzard, car ce dernier pouvait encore être contaminé spécifiquement lorsqu’il était ouvert depuis la Barre 6. Toutes les autres barres continuent d’utiliser le flyout natif de Blizzard.",
    ["wn_361_flyout_keybind"] = "Correction — Appuyer sur un raccourci clavier assigné pour ouvrir ou fermer un bouton de flyout TomoMod fonctionne désormais correctement ; seul un clic de souris était reconnu auparavant.",
    ["wn_361_flyout_discovery"] = "Correction — TomoMod analyse désormais aussi les emplacements d’action réels de la barre mise en quarantaine pour trouver ses flyouts, au lieu de se fier uniquement à l’énumération du grimoire, afin que les flyouts qui s’y trouvent affichent toujours les bonnes icônes d’emplacement connu/inconnu.",
    ["wn_361_vehicle_mover"] = "Nouveau — Quitter le véhicule dispose désormais de son propre déplaceur en mode disposition : il peut être placé n’importe où à l’écran au lieu d’être fixé au-dessus de la Barre d’action 1. Sa position est enregistrée avec votre profil, et il reste par défaut juste au-dessus de la Barre 1 tant que vous ne le déplacez pas.",
    ["wn_361_vehicle_state"] = "Modifié — Le bouton Quitter le véhicule s’affiche désormais dès que vous pouvez réellement quitter le véhicule, au lieu de s’afficher dès qu’une interface de véhicule est présente ; il n’apparaît donc plus pour les véhicules que l’on ne peut pas quitter.",
    ["wn_361_vehicle_taxi"] = "Correction — Le bouton Quitter le véhicule de Blizzard n’est désormais masqué que lorsque le remplacement sécurisé de TomoMod est utilisable, afin de conserver un contrôle de sortie fonctionnel pendant les vols en taxi et dans les véhicules qui n’autorisent pas une sortie anticipée.",
    ["wn_361_tracker"] = "Correction — Les blocs de quête ignorés pendant le combat dans le Suivi d’objectifs terminent désormais automatiquement leur mise en page une fois le combat terminé, au lieu de rester superposés jusqu’à un événement de quête sans rapport.",
    ["wn_361_buttonbag"] = "Correction — Le collecteur de boutons d’addon de la minimap n’oublie plus les boutons déjà rassemblés lorsqu’il rescanne : les addons qui enregistrent leur bouton plus tard ouvrent désormais une nouvelle ligne au lieu de s’empiler sur la première.",
    ["wn_361_trackdupe"] = "Correction — Le panneau de Pistage n’affiche plus deux fois la même entrée (« Banquier » apparaissait sur deux lignes). Les filtres de pistage que le jeu renvoie sous le même nom sont fusionnés en une seule ligne qui les bascule ensemble.",
    ["wn_361_micromenu_native"] = "Correction — TomoMod ne crée plus son propre conteneur, ne réattache plus les boutons et ne touche plus à la disposition du Micro-menu de Blizzard ; l’ancien module autonome Micro Barre a été entièrement retiré.",
    ["wn_361_micromenu_gui"] = "Modifié — Le panneau d’options Sac & Micro Menu affiche désormais une section compacte pour l’œil de recherche de groupe à la place de l’ancien constructeur de Micro Barre, avec seulement un interrupteur et un curseur de taille.",
    ["wn_361_lfgeye_fix"] = "Correction — L’œil de recherche de groupe ne disparaît plus lorsque le Micro-menu s’estompe au survol ; il dispose désormais de sa propre gestion de visibilité et de taille, actualisée automatiquement en entrant dans le monde, en rejoignant une file d’attente ou lorsqu’un donjon/champ de bataille démarre.",
    ["wn_361_validation"] = "Testé — Combat assisté, lancement à l’appui de la touche, liaisons après un reload en combat, la disposition Barre 1/Familier/Postures près de la Carte du monde, les flyouts de sorts, le report de combat du Suivi d’objectifs et l’œil de recherche de groupe pendant le fondu du Micro-menu et les événements LFG ont été validés en jeu.",
    -- =====================
    -- 3.6.0 — What's New
    -- =====================
    ["wn_360_foundation"] = "Changement — Les barres d’action utilisent désormais une architecture de propriété zéro-taint : les boutons TomoMod restent hors du diffuseur natif de Blizzard et l’état protégé des barres Blizzard reste sous le contrôle de Blizzard.",
    ["wn_360_nativebars"] = "Correction — Les barres d’action standard de Blizzard restent actives pour le paging sécurisé mais sont masquées visuellement, afin de n’afficher que les barres TomoMod sans figer leur état dynamique.",
    ["wn_360_specialvisuals"] = "Correction — Les barres Blizzard de postures, familier et possession restent fonctionnelles en arrière-plan tandis que leurs textures, textes, GCD, effets d’autocast, contours actifs et flashs en double sont masqués.",
    ["wn_360_stance"] = "Correction — Les boutons de postures TomoMod utilisent maintenant des actions de sort sécurisées indépendantes et restent cliquables pour les formes du Druide, les auras du Paladin et les postures du Guerrier.",
    ["wn_360_pet"] = "Correction — Les boutons de familier TomoMod utilisent maintenant des actions de familier sécurisées indépendantes ; commandes, capacités et activation/désactivation de l’autocast au clic droit restent utilisables sans dépendre de la barre Blizzard visible.",
    ["wn_360_possess"] = "Correction — Les états de possession et de véhicule passent par le paging sécurisé de la Barre d’action 1 au lieu d’exiger une manipulation de la PossessActionBar de Blizzard.",
    ["wn_360_paging"] = "Correction — La Barre d’action 1 lit directement son emplacement d’action sécurisé actuel, ce qui maintient le paging des formes, véhicules, override et possession sans le figer dans une copie Lua.",
    ["wn_360_formsafe"] = "Correction — Les passages Druide Humain/Félin/Ours mettent maintenant correctement à jour la Barre d’action 1 en combat comme hors combat, sans erreur d’action protégée ni de cooldown secret observée lors des tests.",
    ["wn_360_extra"] = "Correction — Action supplémentaire conserve le comportement sécurisé de Blizzard tandis que TomoMod fournit le bouton visible, son propre GCD/charges et une zone de clic propre sans hitbox native invisible qui vole les interactions.",
    ["wn_360_zone"] = "Correction — Capacité de zone conserve ses icônes dynamiques, GCD et charges, disparaît lorsqu’elle n’est plus active et préserve le comportement de clic natif requis par certaines capacités de quête.",
    ["wn_360_vehicle"] = "Correction — Quitter le véhicule reste une action TomoMod sécurisée utilisant le skin commun des barres, tandis que le comportement taxi de Blizzard reste disponible quand nécessaire.",
    ["wn_360_gcd"] = "Correction — Les derniers GCD natifs des formes, auras et postures sont masqués visuellement sans toucher aux valeurs de cooldown Blizzard ni à l’état protégé des boutons.",
    ["wn_360_petvisuals"] = "Correction — Les derniers contours d’état actif, flashs et effets d’autocast de la barre de familier Blizzard sont maintenant masqués tout en conservant l’état réel du familier entièrement fonctionnel.",
    ["wn_360_skin"] = "Changement — Action supplémentaire, Capacité de zone et Quitter le véhicule utilisent maintenant le même pipeline d’habillage que les autres boutons d’action TomoMod.",
    ["wn_360_flyouts"] = "Correction — Les flyouts de sorts s’ouvrent de nouveau correctement depuis les barres d’action TomoMod, notamment les portails du Mage et les pièges du Chasseur.",
    ["wn_360_installer"] = "Correction — L’installeur de premier lancement se charge désormais correctement sur une installation neuve et attend la fin des cinématiques, vidéos et combats avant de s’afficher.",
    ["wn_360_rolesafe"] = "Correction — Les cadres de groupe/raid, plaques de nom, TomoScore, chat et infobulles gèrent désormais en sécurité les données de rôle restreintes de Midnight au lieu de provoquer des erreurs de valeurs secrètes.",
    ["wn_360_mythiccombat"] = "Correction — MythicHub et les commandes TomoScore attendent désormais la fin du combat avant d’ouvrir ou d’actualiser leurs contrôles protégés, puis reprennent automatiquement.",
    ["wn_360_profiles"] = "Correction — Les fenêtres Import/Export des profils gèrent maintenant Échap en sécurité pendant le combat sans provoquer d’action clavier bloquée.",
    ["wn_360_validation"] = "Testé — Barres standard, paging Humain/Félin/Ours, postures, familier, possession, boutons spéciaux, souris/clavier et combat ont été validés en jeu sans nouvelle erreur de taint des ActionBars.",
    -- =====================
    -- 3.5.9 — What's New
    -- =====================
    ["wn_359_visibility"] = "Nouveau — Les barres d’action disposent maintenant d’un moteur de visibilité sécurisé avec des règles compatibles combat pour l’état de combat, le type de groupe, les instances, la monture, les cibles, le mode masqué et les conditions sécurisées personnalisées.",
    ["wn_359_gcd"] = "Changement — Le balayage du GCD reste visible là où il doit l’être, mais un GCD seul n’affiche plus de compte à rebours fractionnaire inutile ; le texte numérique est réservé au véritable temps de recharge de l’action.",
    ["wn_359_editmode"] = "Correction — Le mode Édition de Blizzard s’ouvre désormais sans les erreurs protégées TargetUnit/FocusUnit ni les erreurs de valeurs secrètes des cadres de groupe compacts auparavant attribuées à TomoMod.",
    ["wn_359_dormancy"] = "Nouveau — Les barres masquées de façon sécurisée passent maintenant en veille et cessent les mises à jour visuelles inutiles. Les raccourcis restent actifs et la barre effectue un rafraîchissement complet dès qu’elle redevient visible.",
    ["wn_359_nativeglow"] = "Nouveau — TomoMod utilise désormais son propre moteur de lueurs natives à la place de LibCustomGlow, supprimant l’ancien chemin de crash AnimateTexCoords et centralisant les animations de proc.",
    ["wn_359_conditional"] = "Correction — Les capacités conditionnelles comme Toucher mortel du Moine actualisent maintenant leur utilisabilité et leur proc depuis les notifications d’action de Blizzard. Une capacité inutilisable reste grisée au lieu d’être remplacée à tort par la couleur rouge de portée.",
    ["wn_359_specialbars"] = "Correction — Les barres Blizzard de familier, posture et possession restent entièrement sous contrôle de Blizzard pour éviter le taint, mais sont filtrées avec le roleset alwaysBlocked de 12.1 afin d’éviter les doublons sans réintroduire les erreurs du mode Édition.",
    ["wn_359_paging"] = "Nouveau — La pagination sécurisée de la Barre d’action 1 ajoute des pages Alt/Shift/Ctrl, des pages Cible amicale/hostile, ainsi que la pagination optionnelle des formes et du vol dynamique, le tout configurable dans TomoMod_Options.",
    ["wn_359_priority"] = "Changement — La priorité de pagination conserve Véhicule/Override/Possession au premier plan, tandis que les pages manuelles et par modificateur passent avant les pages automatiques de forme ou de vol dynamique lorsque nécessaire.",
    ["wn_359_formsafe"] = "Correction — Les changements de forme du Druide en combat sont désormais fiables, sans erreur d’action protégée ni de recharge secrète lors des passages Humain, Félin et Ours.",
    ["wn_359_zoneability"] = "Correction — Les boutons de capacité de zone gardent désormais leur icône, GCD et charges synchronisés, changent correctement d’état pendant les quêtes et disparaissent quand la capacité n’est plus disponible.",
    ["wn_359_extragcd"] = "Correction — Les boutons Action supplémentaire reproduisent maintenant le GCD et la recharge des charges sur l’habillage TomoMod sans lire ni modifier le widget de recharge natif de Blizzard.",
    ["wn_359_specialbuttons"] = "Modifié — Bouton d’action supplémentaire, capacité de zone et sortie de véhicule conservent le comportement sécurisé de Blizzard tandis que TomoMod fournit l’affichage, sans casser les quêtes, véhicules ou taxis.",
    ["wn_359_specialskin"] = "Modifié — Action supplémentaire, Capacité de zone et Quitter le véhicule utilisent désormais exactement le même habillage que les autres boutons d’action TomoMod ; les zones cliquables Blizzard invisibles ne volent plus les clics ni les infobulles.",
    ["wn_359_validation"] = "Testé — Formes, boutons spéciaux, clics souris, GCD/charges, visibilité, glows natifs, mode Édition et paging sécurisé ont été validés en jeu sans nouvelle erreur de taint des barres d’action.",

    -- =====================
    -- 3.5.8 — What's New
    -- =====================
    ["wn_358_input"] = "Correction — Les commandes des barres d’action répondent désormais immédiatement : interruptions, sorts instantanés, actions avec ou sans GCD, spam rapide et raccourcis Shift/Ctrl ne subissent plus le retard de touches observé auparavant.",
    ["wn_358_state"] = "Correction — Déplacer, remplacer ou vider une action, changer de spécialisation ou de talents, de page, de forme, de véhicule ou utiliser le vol dynamique rafraîchit maintenant correctement les boutons sans ancienne icône, recharge, lueur, état grisé ou nombre de charges incorrect.",
    ["wn_358_range"] = "Changement — Sous Midnight 12.1, la couleur de portée utilise désormais les notifications natives de Blizzard, tandis que mana et utilisabilité sont pilotés par événements. L’ancien scan périodique ne reste qu’en solution de compatibilité.",
    ["wn_358_glowflyout"] = "Correction — Les lueurs de proc suivent mieux les sorts de base et leurs transformations, les lueurs obsolètes sont nettoyées, et les menus déroulants ouverts depuis une barre masquée au survol restent visibles puis rendent correctement le contrôle au fondu.",
    ["wn_358_taintstate"] = "Interne — Les états personnalisés auparavant stockés directement sur des cadres Blizzard sont désormais conservés dans des tables faibles externes, réduisant les données TomoMod attachées aux objets protégés.",
    ["wn_358_registry"] = "Correction — Les boutons TomoMod sont isolés des registres et diffuseurs natifs des barres d’action Blizzard lorsque nécessaire, empêchant le contrôleur du jeu d’exécuter des boutons natifs retirés dans un chemin contaminé.",
    ["wn_358_secretcooldown"] = "Correction — En combat, le journal pouvait être inondé d’erreurs lorsque Blizzard appliquait des valeurs secrètes de recharge à d’anciens boutons natifs. Ces chemins sont maintenant isolés et ne génèrent plus ces erreurs répétées.",
    ["wn_358_stancepossess"] = "Correction — StanceBar et PossessActionBar restent désormais entièrement sous le contrôle de Blizzard. Cela supprime l’erreur protégée MainActionBar reproductible lorsqu’un Moine invoquait un compagnon temporaire en combat.",
    ["wn_358_blizzbars"] = "Correction — Les barres d’action standard de Blizzard sont de nouveau masquées via le chemin visuel sécurisé validé pour 12.1 : seules les barres TomoMod restent visibles, sans réintroduire le taint du contrôleur.",
    ["wn_358_validation"] = "Testé — Le nouveau chemin des barres d’action a été validé en combats intensifs, /reload, changements de talents/spécialisation, formes, véhicules, vol dynamique, sorts transformables, charges, flyouts, procs et invocation du compagnon Moine, sans erreur ActionBar observée.",


    -- =====================
    -- 3.5.7 — Quoi de neuf
    -- =====================
    ["wn_357_talkingheadfix"] = "Correction — Masquer Talking Head pouvait laisser la voix off d'un talking head continuer à jouer sous un cadre masqué. Les cadres de talking head gèrent leur propre visibilité, donc simplement masquer le cadre à l'affichage laissait l'état de lecture et son minuteur de fin continuer à tourner — et sautait chaque ligne après la première d'un talking head à plusieurs lignes, puisque le cadre était déjà visible pour celles-ci. TomoMod s'accroche désormais à la fonction de lecture elle-même et ferme chaque talking head exactement comme le fait Blizzard, ce qui arrête de façon fiable le minuteur et la voix off ensemble.",
    ["wn_357_talkingheadcleanup"] = "Interne — Un appel d'arrêt du son émis au même instant que le démarrage d'une voix off est parfois ignoré par le moteur audio, donc Masquer Talking Head insiste désormais une fraction de seconde plus tard pour s'assurer qu'il s'arrête réellement.",
    ["wn_357_queueeyedb"] = "Correction — La position de l'œil de file d'attente n'était en réalité jamais enregistrée. Son entrée manquait dans la table des réglages par défaut, donc le gestionnaire d'enregistrement ignorait silencieusement l'écriture d'une nouvelle position à chaque fois que vous la déplaciez — l'œil bougeait bien à l'écran, mais oubliait où vous l'aviez mis à la connexion suivante. L'entrée manquante est de retour, et le chemin d'enregistrement la crée désormais à la volée si vos réglages sauvegardés en sont encore dépourvus, de sorte qu'une sauvegarde obsolète ne coûte rien de plus qu'une table supplémentaire.",
    ["wn_357_queueeyeposition"] = "Correction — La position par défaut de l'œil de file d'attente était une estimation à l'aveugle qui atterrissait à un endroit différent selon la résolution — complètement hors écran sur un moniteur ultra-large, ce qui a permis de le détecter. Elle se place désormais par défaut à côté de la minimap, là où l'œil vit réellement.",
    ["wn_357_lfgeyesurvive"] = "Nouveau — L'œil du Groupe Finder disparaissait complètement quand vous masquiez le micro menu de Blizzard, car il vit dans ce même conteneur. Il reste désormais en place — le statut de file d'attente du Groupe Finder est toujours visible, où que vous l'ayez placé, que le micro menu natif soit masqué ou non.",
    ["wn_357_lfgeyeoptions"] = "Nouveau — Deux nouvelles options de Micro Barre vous permettent de désactiver entièrement l'œil du Groupe Finder ou de le redimensionner, à côté du réglage qui masque le micro menu de Blizzard.",
    ["wn_357_lfgeyescale"] = "Correction — Le curseur de taille de l'œil du Groupe Finder ne faisait rien à moins que la Micro Barre soit entièrement activée avec « masquer le micro menu de Blizzard » également activé — sinon, l'échelle était silencieusement réinitialisée à la normale à chaque actualisation. Elle s'applique désormais dans tous les cas.",
    ["wn_357_roletaintguard"] = "Correction — Une erreur de plaque de nom pouvait encore survenir en comparant un rôle non lisible directement, malgré la protection déjà en place. Cette comparaison est désormais doublement vérifiée, si bien qu'un rôle illisible est traité comme l'absence de rôle plutôt que de déclencher une erreur.",
    ["wn_357_cooldowntaint"] = "Correction — Certains boutons de barre d'action pouvaient multiplier une erreur en actualisant leur animation de récupération quand le jeu ne laissait pas lire la valeur directement, même sur des barres avec l'habillage désactivé. Cette actualisation est désormais ignorée en toute sécurité sur chaque bouton concerné et chaque récupération qu'il porte, plutôt que de déclencher une erreur.",
    ["wn_357_mainbartaint"] = "Correction — Une erreur rare pouvait apparaître en tentant de réafficher la barre d'action par défaut après avoir enfourché une monture ou pris place dans un véhicule. Elle est désormais neutralisée de la même manière que des cas similaires.",
    ["wn_357_mailiconcrash"] = "Correction — L'icône de courrier de la minimap pouvait déclencher une erreur à chaque nouveau courrier reçu. Ce n'est plus le cas, et l'icône se comporte exactement comme avant.",
    ["wn_357_buggrabber"] = "Nouveau — Si vous utilisez aussi !BugGrabber, Diagnostics s'appuie désormais aussi sur lui, récupérant les erreurs qu'il a vues avant que le suivi propre à TomoMod ne démarre pour cette session. Rien ne change si vous ne l'avez pas installé.",
    ["wn_357_shieldenchant"] = "Correction — L'avertissement d'enchantement d'arme de la fiche de personnage pouvait signaler un bouclier ou un objet tenu en main gauche (grimoire, fioriture, etc.) comme non enchanté, alors qu'aucun des deux ne peut réellement recevoir d'enchantement — les tanks avec un bouclier et les lanceurs de sorts tenant un objet en main gauche voyaient un avertissement rouge pour quelque chose qui n'a jamais été enchantable. L'avertissement ne s'affiche plus que sur un emplacement contenant une véritable arme enchantable.",
    ["wn_357_inspectiteminfo"] = "Nouveau — Inspecter un autre joueur affiche désormais le même détail par objet que votre propre fiche de personnage : niveau d'objet, palier d'amélioration, texte d'enchantement (ou un avertissement d'enchantement manquant) et emplacements de gemmes à côté de chaque objet équipé, au lieu d'un simple nombre moyené en haut.",
    ["wn_357_inspectiteminfotoggle"] = "Nouveau — Une nouvelle case à cocher permet de désactiver les infos d'objet/enchantements/gemmes de la fenêtre d'inspection indépendamment des réglages de votre propre fiche de personnage.",
    ["wn_357_enemybuffgrid"] = "Nouveau — Le suivi des buffs ennemis sur vos cadres de cible et de focus (les auras utiles portées par ce que vous ciblez) a maintenant ses propres listes déroulantes Direction (droite/gauche) et Ligne suivante (haut/bas), plus un curseur Icônes par ligne — c'était auparavant figé à 3 par ligne, vers le haut, sans moyen de changer ni l'un ni l'autre. Le plafond du curseur de nombre est aussi passé de 8 à 12, et toute pile est plafonnée à 3 lignes, le reste étant simplement masqué plutôt que d'agrandir le conteneur indéfiniment.",
    ["wn_357_aurasgrid"] = "Nouveau — Les Auras normales (buffs, debuffs, ou les deux, sur joueur/cible/focus) utilisent maintenant la même grille icônes-par-ligne que les Buffs ennemis : un curseur Icônes par ligne (6 par défaut) remplace l'ancien retour à la ligne en pixels, avec le même plafond de 3 lignes.",
    ["wn_357_auradirectionfix"] = "Correction — Les réglages de direction des Auras et des Buffs ennemis ne faisaient jusque là silencieusement rien : le rafraîchissement en direct du moteur d'auras ne réappliquait la direction que si la taille ou le nombre d'icônes changeait aussi dans la même mise à jour, et même alors, un coin d'ancrage figé faisait que « vers le haut » laissait la pile d'icônes flotter plusieurs lignes au-dessus de la barre de vie au lieu de s'y coller. Les deux sont corrigés — la direction et le nombre par ligne s'appliquent désormais immédiatement, et la pile part bien de là où elle devrait, sans rien qui flotte.",
    ["wn_357_aurasliverefresh"] = "Correction — Plusieurs réglages Auras/Buffs ennemis (nombre, direction, type) nécessitaient auparavant un `/reload` pour s'appliquer réellement, même s'ils semblaient devoir se mettre à jour instantanément. La plupart le font désormais ; les deux qui en ont encore réellement besoin — Activer et la liste déroulante de type buff/debuff/les deux — l'indiquent maintenant directement dans le panneau.",
    ["wn_357_microbarcombatfade"] = "Correction — Survoler un bouton de la Micro Barre en combat pouvait provoquer une erreur d'action bloquée au lieu de simplement faire apparaître la barre en fondu. Le fondu au survol passe maintenant directement à sa valeur cible au lieu de s'animer en combat, ce qui évite complètement l'appel bloqué.",

    -- =====================
    -- 3.5.5 — Quoi de neuf
    -- =====================
    ["wn_355_barhoverblocked"] = "Correctif : le simple fait de passer la souris sur un bouton de barre d'action pendant un combat déclenchait une erreur d'action bloquée, à chaque fois. La mise à jour de bouton de Blizzard s'exécute au survol et se termine par l'écriture directe d'un réglage d'appui prolongé — une écriture interdite en combat, et imputée à TomoMod puisque les boutons sont les nôtres. Une entrée par survol, c'est ainsi qu'une seule session en a accumulé 127. TomoMod écrit désormais ce réglage depuis son propre chemin sécurisé, où il l'écrivait déjà correctement, et ignore la version redondante de Blizzard.",
    ["wn_355_barpingblocked"] = "Correctif : le même survol effectuait une seconde écriture interdite deux lignes plus loin, celle-ci appartenant au système de pings. Les pings visent les barres de Blizzard et ne se sont jamais appliqués aux boutons de TomoMod : cet appel est donc lui aussi ignoré. Aucun des deux n'a jamais rien cassé à l'écran — mais ils noyaient les vraies erreurs sous du bruit et faisaient passer l'add-on pour le responsable de tout ce qui pouvait mal tourner dans le même combat.",
    ["wn_355_escapekeyblocked"] = "Correctif : avec une fenêtre TomoMod ouverte en combat, chaque touche pressée produisait une erreur d'action bloquée — maintenir une touche de déplacement suffisait à remplir le journal d'erreurs à elle seule. La vérification de combat était déjà présente, elle s'exécutait simplement une ligne trop tard, après l'appel protégé qu'elle devait empêcher. Elle passe désormais en premier.",
    ["wn_355_microportrait"] = "Correctif : sur le micro-menu personnalisé, le bouton de la feuille de personnage s'affichait sous la forme d'un carré uni alors que tous les autres boutons étaient corrects. C'est le seul dont l'illustration n'est pas une icône fixe — c'est le portrait de votre personnage — et TomoMod recopiait une référence de texture qui ne se reproduit tout simplement nulle part ailleurs. Il demande désormais au jeu de dessiner votre portrait directement sur le bouton, et emprunte le masque arrondi et l'ombre portée que Blizzard utilise sur son propre bouton de personnage — votre personnage s'affiche donc avec la même forme et le même relief que les boutons voisins, au lieu d'un carré plat.",
    ["wn_355_perftooltip"] = "Nouveau : l'infobulle de mémoire du micro-menu personnalisé s'ouvre désormais sur un bloc Performances : vos images par seconde, votre latence domicile et monde, et le CPU total des addons. La ligne CPU n'a de sens que si le jeu l'enregistre, ce qui est désactivé par défaut et nécessite un rechargement — plutôt que de vous montrer des zéros qui ressembleraient à une vraie mesure, elle indique « profilage désactivé » tant que vous ne l'avez pas activé.",
    ["wn_355_micronative"] = "Correctif : sur certains clients, cocher « masquer le micro-menu de Blizzard » ne faisait strictement rien : la case restait cochée, la barre restait à l'écran. TomoMod cherchait le menu de Blizzard sous un seul nom, qui a changé au fil des correctifs, et abandonnait dès qu'il ne le trouvait pas — sans même masquer les boutons, ce qui aurait pourtant fonctionné. Il reconnaît désormais tous les noms utilisés par Blizzard et traite les boutons dans tous les cas. Si rien ne répond sur votre client, il vous le dit maintenant une fois dans le chat au lieu d'échouer en silence — signalez-le avec votre version du client si ce message apparaît.",
    ["wn_355_queueanchor"] = "Nouveau : l'œil de file d'attente — la petite icône qui tourne pendant que vous patientez pour un donjon ou un champ de bataille — peut désormais être déplacé. Blizzard l'attache à la minicarte sans lui donner de poignée dans le mode Édition, ce qui en faisait le seul élément d'interface impossible à placer. Il figure maintenant parmi les ancres déplaçables de `/tm sr`, et un déplacement effectué en combat est appliqué dès la fin du combat au lieu d'être refusé.",
    ["wn_355_escapepropagate"] ="Interne : la propagation clavier de ces fenêtres est désormais établie une seule fois, à la construction de la fenêtre, au lieu d'être redéfinie à chaque touche. Elle n'avait jamais besoin de l'être : c'est une propriété persistante du cadre, et la seule chose qui la désactive est la fermeture de la fenêtre avec Échap, ce qui ne peut pas arriver en combat.",

    -- =====================
    -- 3.5.4 — Quoi de neuf
    ["wn_354_preyfix"] = "Correction — La barre de progression du Prey Tracker restait bloquée à 0 %. `GetPreyWidgetInfo` ne conservait que le booléen renvoyé par `pcall`, pas les données réelles du widget, si bien que lire `.progressPercent` dessus levait une erreur chaque seconde et interrompait la mise à jour avant qu'elle ne puisse jamais retomber sur le décompte de l'objectif de la quête. L'appel conserve désormais les deux valeurs de retour, si bien qu'un champ de widget manquant est géré silencieusement et que la progression réelle — lue depuis le décompte d'objectif de la chasse — s'affiche correctement.",
    ["wn_354_extranudge"] = "Changement — Les surcouches de déplacement du bouton d'action supplémentaire et de la capacité de zone perdent les quatre flèches de réglage fin qui les entouraient dans `/tm layout`. Glisser la surcouche à la souris continue de la repositionner exactement comme avant ; seuls les boutons supplémentaires ont disparu.",
    ["wn_354_perflocale"] = "Interne — Charger une langue autre que l'anglais construisait puis jetait immédiatement près de 2900 entrées de traduction, cinq fois de suite, à chaque `/reload` — le fichier se compilait entièrement avant que l'addon ne puisse décider qu'il n'était pas nécessaire. Chaque fichier de langue non active s'interrompt désormais avant de construire sa table, et le test de fusion de la langue de base (qui ne faisait silencieusement rien à cause d'une particularité de métatable) est corrigé pour ne tester que ce qu'il était censé tester.",
    ["wn_354_perfrangeticker"] = "Changement — Le minuteur de vérification de portée des cadres de groupe et de raid, un filet de sécurité pour les cas que l'événement de portée du jeu ne couvre pas, s'exécutait deux fois par seconde par cadre, quelle que soit la taille du groupe. Il s'exécute désormais toutes les deux secondes — toujours plus rapide que n'importe quelle transition qu'il doit détecter — réduisant ce coût des trois quarts.",
    ["wn_354_perfaura"] = "Interne — Scanner les auras défensives d'une unité ouvrait un nouvel appel protégé pour chaque buff vérifié, jusqu'à quarante fois par mise à jour d'aura et par unité suivie. Il n'y a désormais qu'un seul appel protégé autour de tout le scan, avec un comportement de repli identique en cas d'erreur en cours de route.",
    ["wn_354_perfpartylookup"] = "Interne — Les cadres de groupe abandonnent une recherche linéaire de cadre au profit d'une table de correspondance directe, et se désabonnent désormais complètement des événements de vie/ressource/aura en raid — où ces cadres sont masqués et où les cadres de raid gèrent les mises à jour — au lieu de continuer silencieusement à traiter ces événements pour rien.",
    ["wn_354_perfcdf"] = "Interne — L'événement de mise à jour de Cooldown Forge pouvait se déclencher plusieurs fois dans la même image lors d'une rafale de changements de temps de recharge, chacun redessinant seul toutes les barres et icônes. Ces rafales sont désormais regroupées en un seul redessin par image.",
    ["wn_354_perfmisc"] = "Interne — Quelques nettoyages supplémentaires de chemins critiques : le sondage des cadres de boss ne construit plus de nouvelles chaînes à chaque cycle, la passe de mise en page différée du traqueur d'objectifs et son scan récursif de contenu n'allouent plus de tables jetables à chaque nœud, et les calculs de vitesse du Skyriding ne reconstruisent plus une closure à chaque cycle.",
    ["wn_354_optionslod"] = "Changement — Le panneau d'options — Config, 28 fichiers et environ 17 900 lignes — se charge désormais à la demande plutôt qu'à la connexion. Il a été déplacé dans son propre addon TomoMod_Options et ne se charge que la première fois que vous l'ouvrez réellement ; chaque bouton et chaque commande slash qui l'atteignaient directement le chargent désormais de façon transparente au premier usage.",
    ["wn_354_optionsfallback"] = "Interne — Les couleurs de score Mythique+, auparavant lues une seule fois à la connexion depuis une table de thème qui vit désormais dans l'addon d'options à la demande (et qui n'existait donc pas encore), sont désormais lues paresseusement — elles se résolvent correctement dès que le panneau d'options a été ouvert une fois, au lieu de rester figées sur une valeur de repli vide pendant toute la session.",
    ["wn_354_escapefix"] = "Correction — Les fenêtres Bilan de mort, Bilan de run, Détail des sorts et Détail de cible du Damage Meter pouvaient laisser Échap incapable de fermer le menu du jeu après avoir été utilisées, car les fermer à l'ancienne passait par une fonction dont les appels protégés sont refusés une fois le chemin tainted. Elles utilisent désormais le même gestionnaire sûr de fermeture par Échap que toutes les autres fenêtres de TomoMod.",

    -- =====================
    -- 3.5.3 — Quoi de neuf
    ["wn_353_brezvisual"] = "Amélioration — Le compteur Battle Rez a reçu un relooking visuel inspiré par les motifs de conception de Tui. Le frame dispose maintenant d'une toile de fond multicouche professionnelle avec des effets d'ombre intérieure, un espacement amélioré et une typographie raffinée pour une meilleure lisibilité au combat.",
    ["wn_353_brezglow"] = "Nouveau — Un effet de lueur optionnel s'active désormais lorsque des résurrections de combat sont disponibles, offrant une meilleure rétroaction visuelle et rendant le compteur plus visible en un coup d'œil.",
    ["wn_353_brezcolors"] = "Modification — La palette de couleurs du compteur Battle Rez a été améliorée avec les couleurs d'accent teal inspirées de Tui et un meilleur contraste entre les états actif (vert) et cooldown (rouge) pour une indication d'état plus claire.",
    ["wn_353_brezlayers"] = "Interne — La disposition du frame du compteur Battle Rez a été refactorisée avec un ordre de calques approprié : arrière-plan, ombre intérieure, texture d'icône, balayage de cooldown et surlignages de texte. Meilleure géométrie et positionnement de tous les éléments UI.",
    ["wn_353_preytracker"] = "Nouveau — Prey Tracker : une barre de progression déplaçable affichant la progression active de la chasse Prey (fonctionnalité exclusive à l'extension Midnight). Affiche le nom de la chasse, le niveau de difficulté et le pourcentage de progression en temps réel avec un design visuel fluide correspondant au compteur Battle Rez.",
    ["wn_353_preyconfig"] = "Nouveau — Le Prey Tracker est désactivé par défaut (contenu Midnight uniquement) et peut être activé dans Config → QOL → Combat → Prey Tracker. Il se cache automatiquement quand aucune chasse Prey n'est active et affiche un aperçu en mode de placement.",
    ["wn_353_preylayout"] = "Nouveau — Le Prey Tracker est entièrement intégré au système de mover de disposition unifié de TomoMod. Glissez-le pour le positionner aux côtés d'autres éléments HUD en utilisant `/tm layout`, avec un comportement de verrouillage/déverrouillage synchronisé et des aperçus de mode de placement cohérents.",
    ["wn_353_preyapi"] = "Interne — Le Prey Tracker lit les API C_QuestLog et C_UIWidgetManager pour détecter les quêtes Prey actives et suivre la progression en temps réel avec une fréquence de mise à jour d'une seconde, fournissant des informations d'état précises pendant les chasses.",
    ["wn_353_brezcrash"] = "Correction — Le compteur Battle Rez pouvait échouer à se charger entièrement sur certaines versions du client : une méthode de cooldown qui n'existe plus, et un appel de niveau de frame effectué sur une texture au lieu d'un frame, plantaient tous deux l'initialisation du module. Les deux sont corrigés, ainsi qu'un effet de lueur qui plantait dès qu'il devait réapparaître après avoir été masqué une fois.",
    ["wn_353_preyevent"] = "Correction — Le Prey Tracker enregistrait un événement qui n'existe pas sur ce client, provoquant une erreur à l'initialisation. Corrigé, et chaque enregistrement d'événement est désormais protégé afin qu'un événement manquant ne puisse plus faire planter le module.",
    ["wn_353_preygui"] = "Nouveau — Le Prey Tracker dispose désormais d'une véritable section de réglages : Config → QOL → Automatisations, avec une case à cocher d'activation et des curseurs de largeur/taille de police. Il n'y avait auparavant aucun moyen en jeu de l'activer.",
    ["wn_353_abmover"] = "Correction — L'entrée « Action Bars » dans `/tm layout` ne faisait strictement rien. Le code des barres d'action porté depuis Tui s'exécute dans un environnement sandboxé qui ne s'exposait jamais au reste de TomoMod, empêchant le mode de déplacement de s'activer silencieusement. Il atteint désormais correctement les barres.",
    ["wn_353_abflash"] = "Correction — Appuyer sur un bouton d'action rendait son icône entièrement blanche, et la première tentative de correction, plus tôt dans cette même version, ne fonctionnait pas. La texture en cause n'est pas une forme découpée qui aurait eu besoin d'un autre mode de mélange, c'est un carré blanc plein — la mélanger autrement la peignait toujours par-dessus l'icône, et le changement rendait trois autres textures, qui allaient très bien jusque-là, plus claires qu'elles ne devaient l'être. L'effet à l'appui assombrit désormais l'icône au lieu de la recouvrir, ce qu'il était censé faire depuis le début.",
    ["wn_353_abpressopt"] = "Nouveau — Vous choisissez ce que fait un bouton pendant que vous le maintenez enfoncé. Config → Barres d'action → Général propose un réglage « Effet à l'appui » avec trois choix : le flash de Blizzard, désormais celui par défaut, l'assombrissement de TomoMod, ou rien du tout. Il s'applique dès que vous le sélectionnez, sans rechargement.",
    ["wn_353_abposition"] = "Correction — Une barre d'action déplacée revenait à sa position par défaut à chaque `/reload`. La position sauvegardée n'était en réalité jamais écrite, et le chemin de restauration ne la relisait jamais même quand elle l'était. Les deux sont corrigés — les positions des barres persistent désormais correctement.",
    ["wn_353_abcolor"] = "Changement — La surcouche du mode déplacement pour les barres d'action et les boutons d'action supplémentaire/capacité de zone utilise désormais la couleur teal de TomoMod au lieu du bleu d'origine de Tui, en cohérence avec toutes les autres surcouches `/tm layout`.",
    ["wn_353_abextramover"] = "Correction — Les emplacements du bouton d'action supplémentaire et de la capacité de zone avaient leur propre surcouche de déplacement, jamais connectée à `/tm layout` — toujours visible à l'écran mais impossible à déplacer depuis l'outil de disposition unifié. Les deux disposent maintenant d'une entrée « Bouton supplémentaire » dans `/tm layout`.",
    ["wn_353_brezicon"] = "Correction — L'icône du compteur Battle Rez s'affichait comme un carré noir uni : le chemin de texture utilisé n'existe pas sur ce client. Elle affiche désormais correctement l'icône de Résurrection.",
    ["wn_353_nameplaterole"] = "Correction — Les plaques de nom pouvaient générer un flot d'erreurs de taint lors de la lecture du rôle de groupe d'une unité en contenu restreint, car le rôle peut revenir comme une valeur secrète qui ne peut pas être comparée directement. C'est désormais protégé et traité comme inconnu plutôt que de lever une erreur.",
    ["wn_353_abmicrodefer"] = "Correction — Les boutons du micro-menu pouvaient disparaître pour le reste de la session. Quand ils doivent être remis en place et qu'un combat est en cours, le déplacement attend la fin du combat — mais la partie censée le réveiller ensuite n'existait pas, alors il attendait indéfiniment, en silence, sans rien dans le journal d'erreurs pour le signaler. Il s'exécute désormais dès que vous quittez le combat.",
    ["wn_353_abpaging"] = "Correction — Quand la barre changeait sous vos yeux — un véhicule, une barre de possession, une posture, une page de vol libre — les boutons gardaient l'apparence de la page que vous veniez de quitter, ou n'affichaient plus rien du tout, et seule une reconstruction complète ou un /reload y remédiait. Le rafraîchissement censé suivre un changement de page dépendait d'une fonction de Blizzard qui n'existe plus sur le client actuel : il ne s'est donc jamais exécuté. Les barres se redessinent désormais elles-mêmes quand elles changent de page.",
    ["wn_353_aboverride"] = "Correction — La barre de remplacement n'était tout simplement jamais écoutée. C'est celle sur laquelle vous placent un véhicule, une monture de vol libre ou la Forme de vol d'un druide : comme rien ne prévenait les barres que cela s'était produit, elles continuaient d'afficher les actions de la page précédente. Elle est désormais surveillée comme n'importe quel autre changement de page : les emplacements sont relus et les boutons redessinés.",
    ["wn_353_totembar"] = "Nouveau — Une barre de totems. Elle affiche les totems que vous avez posés, dans l'ordre de priorité propre à votre classe, chaque icône portant le temps qui lui reste et un balayage qui la parcourt. Clic droit sur une icône pour rappeler le totem, et la barre disparaît d'elle-même quand plus rien n'est posé. Le cadre de totems du jeu est mis en retrait tant qu'elle est active, et rendu intact dès que vous la désactivez.",
    ["wn_353_totemconfig"] = "Nouveau — La barre de totems s'active dans Config → Barres d'action → Général, sous Totems, et prend effet immédiatement, sans rechargement. Elle est désactivée par défaut. Taille des icônes, espacement, bordure, zoom, sens de croissance, ainsi que l'apparence du texte de durée et du balayage sont entièrement réglables.",
    ["wn_353_totemlayout"] = "Nouveau — Positionnez-la depuis `/tm layout` comme n'importe quel autre élément d'interface. Elle y reste visible et étiquetée même sans aucun totem posé : vous pouvez donc la placer avant même d'en lancer un, au lieu de devoir poser un totem, courir jusqu'à l'outil de disposition et espérer qu'il tienne encore.",
    ["wn_353_petstancelayout"] = "Nouveau — La barre de familier et la barre de postures peuvent enfin être mises en page. On leur avait retiré l'orientation, le nombre de boutons et les colonnes en partant du principe que le jeu maîtrisait leur forme — ce n'est pas le cas : elles passent exactement par le même code de disposition que les huit barres principales, et l'ont toujours fait, si bien que les réglages étaient actifs depuis le début sans rien à l'écran pour les atteindre. Les trois contrôles sont désormais présents pour les deux, plafonnés à dix emplacements au lieu de douze. Régler la barre de postures au-delà du nombre de formes de votre classe est sans conséquence : la valeur est bornée pour vous.",
    ["wn_353_loots17"] = "Nouveau — Les tables de butin sont à jour pour la saison 17. La rotation des donjons a entièrement changé : les huit nouveaux donjons sont donc là — Repos des rois, Temple de Sephraliss, Bassins de l'Essence rubis, Le val Aveuglant, Arène de la Cicatrice du Vide, Antre de Nalorakk, Allée du meurtre et Autel des crochets — avec les deux nouveaux raids, La grotte des marées et L'abîme venimeux, ainsi que les restrictions de classe de chaque objet qu'ils laissent tomber. Les tables de la saison précédente sont retirées plutôt que conservées à côté : plus rien dans l'une ou l'autre rotation ne pointe vers elles.",
    ["wn_353_mplusteleports"] = "Nouveau — Le traqueur Mythique+ connaît les téléportations de la nouvelle rotation. Les cinq donjons de la rotation arrivent avec leurs sorts de téléportation, et le Repos des rois et le Temple de Sephraliss ont enfin les leurs — tous deux étaient vides alors qu'ils font partie de la rotation, si bien que le traqueur n'avait rien à proposer pour ni l'un ni l'autre.",
    ["wn_353_keysync"] = "Correction — `/tmt keysync` fait enfin quelque chose. Le diagnostic de synchronisation des clés avait bien été écrit, et la note juste au-dessus nommait même la commande à laquelle il devait répondre, mais rien dans le gestionnaire n'y menait — si bien que le seul outil permettant de distinguer une synchro qui échoue en silence d'une autre qui n'a simplement rien trouvé à faire correspondre était inaccessible depuis le jeu. Il figure désormais dans `/tmt help` dans les six langues.",
    ["wn_353_totemport"] = "Interne — La barre de totems est un portage et non une réécriture : reprise de Tui telle qu'elle était écrite, chaque ligne modifiée étant marquée, si bien que se remettre à jour avec l'original plus tard consistera à rejouer une poignée de marques plutôt qu'à relire tout le fichier. Ses temps de recharge refusent purement et simplement les valeurs secrètes au lieu de les deviner — c'est ainsi que le reste du code porté traite déjà le contenu restreint — et toute écriture sécurisée attend la fin du combat au lieu d'être tentée en pleine mêlée.",
    ["wn_353_abemptyslot"] = "Correction — Et avec « masquer les emplacements vides » activé, ces mêmes changements laissaient la barre vide plutôt que périmée : les boutons étaient bien là mais invisibles, et décocher l'option faisait disparaître le problème — ce qui a mis sur la piste. Le rafraîchissement s'exécutait une image trop tôt, alors que les boutons pointaient encore sur les emplacements de la page quittée : tous étaient donc jugés vides et estompés, sans que rien ne revienne y regarder ensuite. Il s'exécute maintenant une seconde fois à l'image suivante, une fois les boutons à jour.",

    -- 3.5.2 — Quoi de neuf
    -- =====================
    ["wn_352_icons"] = "Correctif — Les icônes des barres d'action revenaient noires. La vérification censée repérer un emplacement vide s'attendait à ce que l'icône soit fournie sous forme de chemin de fichier, ce que le jeu répondait autrefois et ne répond plus depuis des années — il renvoie désormais un numéro. Chaque véritable icône échouait donc à un test écrit pour attraper celles qui manquaient, se retrouvait effacée, et laissait un carré vide à la place de ton sort. La voie normale comme la solution de secours acceptent maintenant les deux réponses.",
    ["wn_352_tint"] = "Correctif — Hors de portée, plus de mana et action inutilisable ne s'affichaient plus après un rechargement ou un changement de barre, et il suffisait de passer la souris sur le bouton pour les faire réapparaître. TomoMod teintait l'icône exactement là où Blizzard la teinte, si bien que celui des deux qui passait en dernier décidait de ce que tu voyais. La teinte est désormais une couche appartenant à TomoMod, posée par-dessus l'icône, qui l'ombre exactement comme avant sans que les deux ne s'écrasent mutuellement — et quand il n'y a rien à signaler, elle n'est tout simplement pas là.",
    ["wn_352_scope"] = "Correctif — Avec les barres d'action désactivées, l'habillage continuait quand même d'habiller. Il retombe sur une recherche des boutons par leur nom, et ces noms sont ceux des boutons de Blizzard, que TomoMod les ait repris ou non — désactiver les barres laissait donc l'habillage repeindre des cadres qui ne le regardaient pas. Il vérifie maintenant que les barres tournent réellement avant de modifier quoi que ce soit.",
    ["wn_352_move"] = "Interne — Les barres d'action ont déménagé. Elles étaient rangées avec les petits conforts d'utilisation parce que c'est là qu'a commencé l'habillage, et elles ont cessé d'être un confort le jour où la version précédente en a fait un système à part entière, avec son moteur, ses cinq couches et ses propres boutons. Elles siègent désormais avec les cadres d'unité, de groupe et de raid, à leur place, et se chargent comme eux. Rien n'a changé en elles pendant le trajet — les trois correctifs ci-dessus les ont accompagnées.",
    ["wn_352_tui"] = "Interne — Des fondations, et rien de visible pour l'instant. Une partie de ce qui est prévu pour les barres existe déjà dans un autre addon, et le réécrire ligne à ligne pour l'adapter ici serait long et introduirait des erreurs qui ne sont pas dans l'original. Il existe donc désormais une fine couche dont le seul rôle est de permettre à l'un de ces fichiers de tourner ici sans y toucher. Là où TomoMod possède déjà sa propre version de quelque chose — l'ancrage, le mode déplacement — la couche pointe vers elle plutôt que de traîner un second exemplaire, ce qui explique que quatre fonctions en remplacent seize cents lignes. Rien n'appelle encore tout cela ; c'est délibérément mis en place à part, avant que quoi que ce soit n'en dépende.",
    ["wn_352_port"] = "Interne — Et puis la chose pour laquelle cette couche avait été bâtie. Le module de barres d'action de l'autre addon est désormais ici en entier : quatorze fichiers, un peu plus de huit mille lignes, repris tels qu'ils avaient été écrits plutôt que retapés pour s'adapter. Chaque endroit où une ligne a dû changer porte une marque, si bien que le jour où l'original évoluera, se remettre à jour consistera à rejouer une poignée de marques au lieu de tout relire en espérant repérer ce qui a bougé. C'est chargé, c'est vérifié, et c'est éteint volontairement : poser quelque chose de cette taille et l'allumer dans la même version, c'est se retrouver incapable de dire laquelle des deux a cassé tes barres.",
    ["wn_352_portlayers"] = "Interne — Ce qu'il y a dedans, pour le jour où l'interrupteur sera actionné. Les menus volants d'abord : la version précédente livrait les boutons propres à TomoMod et devait dire franchement qu'un portail de mage ou un piège de chasseur ne s'ouvrirait pas sur une barre qui les utilise, parce que le jeu refuse la voie ordinaire sur un bouton fabriqué par un addon et que le contournement représente quelques centaines de lignes que personne n'écrit deux fois. Ces lignes sont venues avec le portage, avec en prime un habillage assorti du menu du jeu lui-même pour les boutons restés à Blizzard. Le bouton d'action supplémentaire et l'aptitude de zone reçoivent une place à eux, dont le jeu ne peut pas les déloger discrètement. Les recharges, l'illumination et le grisage de ce que tu ne peux pas lancer arrivent chacun comme sa propre couche. Rien de tout cela n'est actif pour l'instant.",
    ["wn_352_switch"] = "Modification — L'interrupteur est actionné : les barres d'action tournent désormais sur le module porté, et le système qui les pilotait avant a été retiré plutôt que laissé là, éteint — deux systèmes persuadés chacun de posséder les mêmes boutons, ce n'est pas un état qu'on livre pour voir ce que ça donne. Les trois dernières pièces sont arrivées avec : l'habillage, qui retire d'un bouton l'illustration du jeu lui-même et le redessine entièrement, jusqu'au nom de macro et au nombre de charges ; l'effacement d'une barre jusqu'à ce que tu passes la souris dessus, barre par barre, la barre restant visible tant que ton grimoire est ouvert ; et les surcouches que tu vois quand tu vas déplacer une barre. Masque est également pris en charge maintenant, si tu l'utilises, et tout simplement absent sinon.",
    ["wn_352_bindings"] = "Modification — Tes touches sont conservées, et il y a 106 choses de moins à assigner. La version précédente livrait une liaison par bouton et par barre : mettre les boutons propres à TomoMod sur une barre imposait de l'assigner une seconde fois dans la fenêtre de raccourcis du jeu, sous un en-tête TomoMod, à côté de la liaison que tu avais déjà. Les nouveaux boutons ne demandent pas cela : ils lisent ce que tu as assigné aux commandes de barres d'action du jeu lui-même et se les approprient. Une barre que tu avais configurée continue de fonctionner sans que tu touches à quoi que ce soit, et une touche déjà prise par autre chose est laissée exactement où elle est.",
    ["wn_352_settings"] = "Changement — La page d'options des barres d'action est de retour, et il y a un point à connaître avant de mettre à jour. Quand les barres ont basculé, plus tôt dans cette même version, la page s'était réduite à un simple message, parce que chacun de ses contrôles écrivait dans un système qui n'existait plus. Elle est maintenant reconstruite sur ce que les barres lisent réellement : cinq onglets — les boutons eux-mêmes, le texte écrit dessus, les indicateurs de hors de portée, de ressource insuffisante et de sort inutilisable, l'estompage d'une barre tant que tu ne pointes pas dessus, et un onglet par barre pour le nombre de boutons et le sens dans lequel elle grandit. Le point à connaître : tes anciens réglages de barres ne sont pas repris. L'ancienne façon de les stocker et la nouvelle ne nomment rien pareil, et les rares noms qui se ressemblent ne veulent pas dire la même chose ; les convertir aurait donc voulu dire deviner — et une mauvaise devinette te laisse une disposition que tu n'as jamais choisie et dont tu ne peux rien retracer. Les anciens réglages sont effacés une fois, à ta première connexion après la mise à jour, et les barres démarrent sur des valeurs par défaut propres, à toi de les régler comme tu l'entends.",
    ["wn_352_chatcopy"] = "Nouveau — La copie du texte du chat a été refaite. La fenêtre obtenue ressemble maintenant au reste du chat plutôt qu'à une simple boîte grise : le texte est déjà sélectionné et déroulé jusqu'à la dernière ligne dès l'ouverture, tu peux la redimensionner, et elle retient 500 lignes là où elle s'arrêtait à 128. Il y a aussi un bouton de copie sur la fenêtre de chat elle-même — toujours visible, seulement quand tu pointes le chat, ou pas du tout, comme tu préfères, dans Skins, Fenêtre de discussion. Et la petite fenêtre qui te propose de copier l'adresse d'un lien s'accorde désormais au reste au lieu d'être la boîte de dialogue du jeu.",

    -- =====================
    -- 3.5.1 — Quoi de neuf
    -- =====================
    ["wn_351_engine"] = "Interne — Les barres d'action étaient entièrement repeintes cinq fois par seconde, chaque bouton, que quelque chose ait changé ou non. C'est la forme que prend un habillage quand il grandit jusqu'à devenir un ensemble de fonctionnalités sans qu'on lui ait jamais donné d'endroit où retenir quoi que ce soit. Il existe désormais une seule pièce qui porte la question — dans quel état se trouve ce bouton — et c'est le jeu qui la prévient quand quelque chose se produit, au lieu qu'elle vérifie à intervalle régulier ; elle ne transmet la nouvelle que lorsqu'une valeur a réellement changé. La portée fait exception, parce que le jeu n'a aucun moyen de l'annoncer : cette vérification reste sur un minuteur, et uniquement tant que tu as une cible. Elle ne suppose jamais non plus que le bouton en dessous appartient à Blizzard, ce qui est précisément ce qui a rendu tout le reste de cette version possible.",
    ["wn_351_render"] = "Nouveau — Les icônes et les cooldowns se règlent maintenant. Les chiffres du cooldown et leur taille, la couleur et l'opacité du balayage, le liseré et l'éclat, le texte des charges et des piles et sa taille, le nom de la macro, le grisement d'une action inutilisable, et le recadrage de l'icône — jusqu'à aucun recadrage du tout. S'y ajoute le choix de qui dessine le cooldown : Blizzard, qui conserve son propre balayage et se contente de le restyler, ou TomoMod, qui le dessine. Blizzard reste le réglage par défaut et le plus sûr des deux pour l'instant ; celui de TomoMod est ce dont les nouveaux boutons plus bas ont besoin, et il est là pour pouvoir être éprouvé avant que quoi que ce soit n'en dépende.",
    ["wn_351_glow"] = "Nouveau — Deux lueurs sur les barres, et elles peuvent être allumées en même temps. La première est la mise en avant classique d'un proc ; la seconde suit la suggestion de rotation que le jeu formule lui-même. Chacune a son style — Pixel, Autocast, Bouton, Proc ou Blizzard — sa couleur, et pour la version pixel le nombre de lignes, leur épaisseur et la vitesse d'animation. Elles coexistent au lieu de se relayer, parce que chacune garde sa propre prise sur le bouton. La correspondance se fait sur le sort : une macro qui finit par lancer quelque chose s'illumine exactement comme le sort seul, et un talent qui renomme un sort est suivi lui aussi. La lueur de rotation est désactivée par défaut et exige que la fonctionnalité existe sur ton personnage.",
    ["wn_351_hotkeys"] = "Nouveau — Le texte des raccourcis sur les boutons t'appartient désormais : l'afficher ou non, sa taille, sa couleur, le coin où il se place, son décalage, son abréviation, et sa présence ou non sur un emplacement vide. Il est déduit du raccourci lui-même plutôt que recopié depuis l'étiquette de Blizzard, ce qui compte parce qu'un bouton fabriqué par TomoMod n'a aucune étiquette à recopier — celle de Blizzard est conservée en secours, pour qu'un changement inattendu dans un futur correctif donne un texte légèrement moins bon plutôt qu'aucun texte. S'y ajoute un mode d'assignation : tu l'actives, tu survoles un bouton, tu appuies sur une touche. Un clic droit ou Échap en efface une. Il refuse de s'ouvrir en combat.",
    ["wn_351_special"] = "Nouveau — Des choses que les barres savaient et ne t'ont jamais montrées. Sur une barre habillée, tu ne pouvais pas voir dans quelle posture tu étais, quel enchantement d'arme était équipé, ni quelle capacité de familier était réglée pour se lancer seule : l'habillage supprime les marqueurs de Blizzard et délave sa mise en avant. Il y a maintenant un anneau pour l'action active et pour les objets équipés, chacun avec sa couleur et une épaisseur commune, sur un seul anneau doté d'un ordre de priorité pour que deux états ne s'empilent jamais en un fouillis. L'autocast du familier reçoit son propre éclat, qui cohabite avec les deux lueurs ci-dessus. La barre de familier peut se masquer quand tu n'as pas de familier. Les postures n'ont pas d'équivalent — il n'existe aucun moyen de demander au jeu si une classe possède des formes, et les boutons de posture de Blizzard disparaîssent déjà d'eux-mêmes quand il n'y a rien à montrer.",
    ["wn_351_ownbuttons"] = "Nouveau — TomoMod peut désormais fabriquer ses propres boutons d'action au lieu d'emprunter ceux de Blizzard. C'est désactivé partout, cela s'active barre par barre, et cela se défait en décochant l'option puis en rechargeant. Tout ce qui précède fonctionne dessus sans changement. Lis les limites avant de l'activer, car elles sont réelles : les menus volants ne s'ouvrent pas sur une barre convertie — portails de mage, pièges de chasseur, flacons invoqués. Les barres de véhicule et de remplaçement suivent toujours le changement de page, mais le bouton de sortie spécifique et son habillage ne suivent pas. La mise en avant de rotation du jeu n'y est pas dessinée ; utilise la lueur de rotation ci-dessus à la place. Les barres de familier et de posture restent entièrement sur les boutons de Blizzard. C'est marqué expérimental parce que ça l'est.",
    ["wn_351_bindings"] = "Nouveau — Les nouveaux boutons arrivent avec 106 raccourcis déjà déclarés : ils apparaissent donc dans la fenêtre de raccourcis du jeu, sous un intitulé TomoMod avec une section par barre. Ils sont liés via un clic dédié plutôt qu'un simple clic gauche, et c'est ce qui fait que le lancement à l'appui de la touche se comporte correctement — c'est un écueil connu, et Bartender4 a fait le même déplacement il y a des années pour la même raison.",
    ["wn_351_keybound"] = "Nouveau — Les barres de TomoMod rejoignent le mode d'assignation partagé qu'utilisent Dominos, Bartender4 et Bagnon : une seule passe assigne tes barres et les leurs, au lieu que chaque addon impose le sien. La bibliothèque qui arbitre tout cela est maintenant incluse, si bien que le mode partagé est là que tu utilises l'un de ces addons ou non. Un détail à consigner pour la prochaine mise à jour : elle doit être reprise d'une version empaquetée, jamais de son miroir GitHub, qui calcule sa propre version à partir d'un marqueur qui n'est renseigné qu'à l'intérieur d'un dépôt source — copiée ailleurs, elle échoue dès son chargement.",
    ["wn_351_tabs"] = "Modification — La page d'options des barres d'action compte maintenant cinq onglets au lieu de deux : Habillage, Boutons, Lueur, Raccourcis et Barres. Toute nouveauté atterrissait jusqu'ici dans une longue colonne unique sur l'onglet d'habillage, et trois des cinq couches de cette version y seraient allées aussi.",

    -- =====================
    -- 3.4.6 — Quoi de neuf
    -- =====================

    ["wn_346_probe_secret"] = "Correction — Les icônes de buff du Studio de cooldowns, à qui la 3.4.5 venait d'apprendre à garder leur décompte en combat, provoquaient une erreur dès la première icône surveillant un buff. Le marqueur invisible attaché à chaque icône était interrogé sur sa présence à l'écran, en partant du principe qu'il s'agit d'une question portant sur un élément d'interface et non sur le buff — or ce n'en est pas une. Qu'une icône d'aura soit à l'écran, c'est exactement le fait que le buff soit actif, c'est-à-dire précisément ce que le jeu dissimule : le oui-ou-non renvoyé était lui-même dissimulé, et c'est le fait de le consulter qui échouait. Protéger l'appel ne pouvait rien y faire : l'appel se déroulait très bien, et l'échec survenait une ligne plus loin, au moment de regarder la réponse.",
    ["wn_346_probe_cooldown"] = "Modification — La question est donc posée à autre chose. Chaque icône possède déjà son propre balayage, celui que le jeu pilote directement, et cet élément appartient à TomoMod et non au jeu : le balayage apparaît tant que le buff est actif et disparaît quand il se termine, et rien n'empêche l'addon de le lire. Il donne la même réponse, depuis le côté de la frontière où la lecture reste permise. Le marqueur du jeu est conservé derrière lui comme second avis, désormais interrogé sans risque, et si aucun des deux ne répond, l'icône n'apporte simplement rien pour cette image et continue de piloter le balayage — ce qui a toujours été la plus grande part de son rôle.",

    -- =====================
    -- 3.4.5 — Quoi de neuf
    -- =====================

    ["wn_345_class_secret"] = "Correction — Les barres de vie provoquaient une erreur à chaque mise à jour pour tout joueur dont le jeu masque désormais la classe : 399 fois en une seule session dans le rapport à l'origine de ce correctif. Le patch 12.1 a élargi ce qu'un addon n'a pas le droit de lire, et une valeur masquée n'est pas simplement absente : elle est bien là, et elle échoue dès qu'on en fait quoi que ce soit — la comparer, s'en servir pour chercher quelque chose, la coller à un texte, ou même demander si elle est vraie. La vérification doit donc venir avant ; il n'y a rien à rattraper après. Seize endroits dans TomoMod lisaient chacun la classe d'une unité et cherchaient la couleur de la même manière ; ils passent tous maintenant par un même jeu d'utilitaires qui demande si une valeur est lisible avant d'y toucher. Chaque endroit décide lui-même de ce que signifie une classe inconnue, car la bonne réponse n'est pas la même partout : le rappel de buffs suppose que la personne pourrait en avoir besoin plutôt que de l'ignorer, la teinte lanceur de sorts sur les plaques hostiles est laissée de côté plutôt que devinée, et la liste des clefs comme TomoScore s'affichent simplement sans couleur. La couronne de chef de groupe relève de la même famille — savoir qui dirige le groupe peut désormais être masqué aussi, et dans ce cas la couronne reste cachée, car en afficher une sur un joueur qui n'est peut-être pas le chef est pire que de n'en afficher aucune.",
    ["wn_345_class_passthrough"] = "Nouveau — Et puis les couleurs de classe sont revenues. Se rabattre sur une couleur de faction quand la classe n'est pas lisible est correct, mais en donjon cela concerne absolument tout le groupe : les cadres auraient donc été de la mauvaise couleur en permanence, et non de temps en temps. Il se trouve que le jeu accepte encore de colorer une unité pour vous même quand il refuse de vous dire la classe : la classe entre dans une fonction du jeu et la couleur ressort directement d'une autre, dans la barre, sans que l'addon lise jamais ni l'une ni l'autre. Les barres de vie des cadres d'unité, des plaques, des cadres de groupe et de raid empruntent cette voie en premier et conservent leurs couleurs de classe. Cela ne marche toutefois que là où la couleur est appliquée telle quelle — tout ce qui doit l'assombrir ou la mélanger doit en lire les valeurs, et là la couleur de faction reste la réponse.",
    ["wn_345_nameplate_auras"] = "Correction — Les plaques d'unité ennemies disparaissaient quand on tournait la caméra. Pas leurs auras : la plaque entière. Lire les auras d'une unité fait partie de ce que le patch 12.1 peut désormais refuser, et le refus survenait au milieu du dessin de la plaque : tout ce qui venait ensuite — la barre de vie, le nom, la barre d'incantation — n'avait tout simplement pas lieu, et la plaque semblait supprimée. Tourner la caméra déclenchait le problème parce que c'est ce qui fait apparaître de nouvelles plaques. Chaque lecture d'aura sur une plaque est maintenant protégée individuellement : un refus coûte à cette seule aura son icône ou son compte à rebours, et rien d'autre. Deux des protections écrites pour l'occasion ne protégeaient en réalité rien du tout, pour une raison qui vaut d'être connue quand on écrit du Lua : une protection placée autour d'un appel ne couvre pas un autre appel qu'on lui passe en argument, car l'argument est évalué en premier. L'une des deux entourait précisément l'appel qui échouait.",
    ["wn_345_aura_probe"] = "Interne — Onze endroits différents de TomoMod lisent les auras d'une unité : les auras sur les cadres et sur les plaques, le liseré de dissipation, la rangée de soins persistants, l'icône de buff de groupe, les icônes défensives, le suivi de buffs de CooldownForge. Chacun parcourait jusqu'à quarante emplacements d'aura un par un, en protégeant chaque étape, pour ne découvrir qu'à la fin que le jeu n'allait rien répondre du tout. Ils posent maintenant la question une seule fois, et la réponse est retenue pour le reste de la frame : quarante cadres de groupe coûtent une question au lieu de seize cents étapes protégées. La question est volontairement posée par la voie la plus permissive de lecture d'une aura, si bien qu'une réponse négative signifie que toutes les autres voies étaient déjà fermées et que rien d'affichable n'est écarté. Un vrai bug en est sorti : CooldownForge vidait sa propre liste de buffs suivis chaque fois qu'une relecture était refusée, et ne suivait alors plus rien jusqu'à ce que le jeu autorise une lecture. Autant être clair sur la limite : cela rend les choses moins coûteuses, pas plus complètes. Une icône dont la lecture ne donne rien s'éteint toujours, exactement comme avant.",
    ["wn_345_aura_engine"] = "Nouveau — Les auras manquaient pendant la plus grande partie d'un pull, et rien ne le signalait : aucune erreur, rien sur la plaque ni sur le cadre, juste un vide là où aurait dû se trouver ce qu'on voulait voir. Tout le reste de cette version rend une lecture d'aura refusée inoffensive ; rien n'y fait revenir l'aura, parce que le jeu refuse de la donner tant qu'un combat est en cours. Alors TomoMod cesse de demander. Il décrit désormais ce qu'il veut — ces auras, en telle quantité, disposées ainsi, habillées ainsi — et le jeu se charge lui-même de chercher et de trier, puis rend les icônes terminées. Plus rien côté TomoMod ne lit une aura, il n'y a donc plus rien à refuser. Toutes les rangées d'auras de l'addon fonctionnent ainsi maintenant : affaiblissements et améliorations des plaques, auras et buffs de cible sur vos cadres, icônes de soins persistants du groupe, affaiblissements et soins persistants du raid. Les rangées de soins persistants ont demandé une étape de plus : elles reposaient sur la reconnaissance de sorts précis, et le sort est justement ce qui est masqué — la liste des sorts à surveiller est donc remise au jeu d'avance, et c'est lui qui trie. L'indicateur de dissipation a été le plus long à résoudre, et il change de forme au passage. C'était un liseré coloré autour du cadre d'un joueur, allumé en comparant chaque effet néfaste à ce que vous savez retirer — et comme ni l'un ni l'autre ne peut plus être consulté, il ne s'allumait qu'hors combat, soit l'inverse du moment où un soigneur en a besoin. C'est maintenant une petite icône dans le coin du cadre, et c'est le jeu qui choisit l'effet à montrer : on peut lui demander directement si vous pouvez dissiper quelque chose, et il répond sans laisser personne lire quoi que ce soit. Deux choses à savoir : les saignements n'y apparaîtront jamais, aucune capacité de classe ne les retirant, et les contrôles sont volontairement exclus puisqu'ils ont leur propre affichage. Quatre bugs ont été attrapés en chemin : une erreur à chaque disparition de plaque, des icônes créées en plein combat qui sortaient sans taille et restaient invisibles définitivement, les interrupteurs d'affichage des affaiblissements et des soins persistants qui ne prenaient plus effet avant un rechargement, et un curseur de taille qui ne pilotait discrètement plus rien.",
    ["wn_345_aura_layout"] = "Correction — Les rangées d'auras ne revenaient plus à la ligne et croissaient toujours dans le même sens, quels que soient les réglages. Confier l'affichage au jeu revenait à lui indiquer la taille d'une icône, et cela n'incluait ni le sens de la rangée ni l'endroit où elle doit se replier — ces deux-là appartiennent à la rangée elle-même, et n'étaient tout simplement jamais transmis. Les deux sens fonctionnent de nouveau, horizontal et vertical indépendamment, ainsi que l'espacement entre les icônes. Dans la foulée : une rangée réglée sur huit auras pouvait en dessiner seize quand elle montrait à la fois améliorations et affaiblissements, puisqu'il s'agit de deux listes distinctes et que chacune recevait la totalité du quota. Le quota est maintenant partagé. Revers de la médaille : une rangée de huit ne peut plus être remplie entièrement d'affaiblissements en l'absence d'améliorations — les deux listes ne peuvent pas se prêter de place.",
    ["wn_345_cdf_probe"] = "Nouveau — Les icônes de buff du Cooldown Studio conservent leur décompte en combat. Le studio est le seul affichage qu'on ne peut pas confier au jeu tel quel : il range cooldowns et buffs dans une même rangée, notion que le jeu n'a pas, et ce dont il a besoin est de toute façon plus étroit — ce buff est-il actif, et combien de temps reste-t-il — c'est-à-dire précisément ce qu'il n'a plus le droit de consulter. Il demande donc sans laisser le jeu dessiner : un marqueur invisible est attaché à chaque icône, ne surveillant que ce buff-là, et le jeu pilote directement le balayage de l'icône. Savoir si le buff est actif se résout en demandant à ce marqueur s'il est à l'écran, une question sur un morceau d'interface et non sur le buff. Une conséquence à connaître : une seule chose à la fois a le droit d'écrire le balayage, parce que deux écrivains en alternance étaient la cause du scintillement.",
    ["wn_345_dm_dropdowns"] = "Correction — Sur la page d'options du Damage Meter, les listes déroulantes du thème et de la texture des barres s'ouvraient avec le bon nombre de lignes et aucun texte dessus. Le compteur nomme ses listes d'une manière et la liste déroulante de TomoMod en attend une autre, et contrairement aux autres contrôles celle-ci n'a pas de valeur de repli : chaque ligne était donc dessinée vide. La page Damage Meter a par ailleurs sa propre icône dans le menu — elle partageait celle des Diagnostics, si bien que deux entrées portaient la même image.",

    -- =====================
    -- 3.4.4 — Quoi de neuf
    -- =====================

    ["wn_344_damagemeter"] = "Nouveau — TomoMod a désormais un compteur de dégâts. DPS et HPS, dégâts subis, dégâts évitables, dégâts infligés aux ennemis, absorptions, interruptions, dissipations et morts, répartis en Dégâts, Soins et Actions que tu fais défiler depuis l'en-tête, avec une session En cours et une session Globale et un chronomètre de combat. Il vaut la peine de savoir comment il fonctionne, car cela explique ce qu'il peut et ne peut pas faire : il lit les données de combat de Blizzard au lieu d'écouter le journal de combat et de tout additionner lui-même. Résultat : aucun mur d'événements à filtrer, et des chiffres identiques à ceux du compteur de Blizzard puisque ce sont les mêmes. Un client qui ne fournit pas ces données le dit clairement plutôt que d'afficher une fenêtre vide. Il répond à /tdm et peut rapporter en dire, groupe, raid, guilde, instance, chuchotement, le canal adapté à ton groupe, ou simplement à toi-même.",
    ["wn_344_dm_windows"] = "Nouveau — Jusqu'à cinq fenêtres de compteur à la fois, chacune avec son type, sa session, ses colonnes et son format de nombres : suivre les dégâts et les soins côte à côte est le cas ordinaire, et une seule fenêtre obligeait à faire l'aller-retour pendant tout le combat. Fais glisser une fenêtre contre une autre et elles s'accrochent bord à bord — elles se déplacent ensuite ensemble et partagent le bord qui les relie, si bien que redimensionner l'une redimensionne l'autre, et éloigner une fenêtre la décroche. Neuf styles sont fournis — Tomo Dark, Tomo Neon, Minimal, Glossy, Ember, Frost, Terminal, Void et Parchment — avec la texture des barres, la police et sa taille, la hauteur des barres, la couleur d'accent ou les couleurs de classe, la transparence de la fenêtre en combat et hors combat, et une option pour garder ta propre barre toujours visible.",
    ["wn_344_dm_breakdowns"] = "Nouveau — Un chiffre sur une barre ne dit pas ce qui l'a produit. Clic gauche sur une barre pour ouvrir ses sorts en ligne, clic droit pour leur donner leur propre fenêtre : totaux, coups, critiques et taux de critique par sort. Un détail par cible répond à l'autre moitié de la question — non pas ce que tu as lancé, mais sur quoi tu l'as lancé — et chaque pull peut se lire seul, en segment, plutôt qu'uniquement fondu dans le total courant. Cliquer sur un joueur dans la liste des morts ouvre un récapitulatif de ce qui l'a tué, qui peut aussi s'ouvrir tout seul quand tu meurs ; /tdm resetpos ramène cette fenêtre au centre si elle a fini quelque part de peu pratique.",
    ["wn_344_dm_runrecap"] = "Nouveau — Un récapitulatif de fin de donjon : dégâts, soins, interruptions, morts et dégâts évitables subis pour tout le groupe, qui s'ouvre seul à la fin de la course ou revient avec /tdm recap. Il se construit au fil de la course plutôt que de tout lire à la fin, et ce n'est pas une préférence : au moment précis où une clé se termine, le jeu n'autorise plus un addon à lire ces valeurs, si bien qu'un récapitulatif écrit de la manière évidente ne pourrait même pas classer le groupe. À la place, un instantané discret est pris chaque fois que tu sors de combat, soit une quinzaine de fois dans une clé, pour un coût que tu ne remarqueras pas. Ce qui est illisible à ce moment-là est laissé tel quel plutôt qu'écrasé, si bien que le dernier chiffre valide d'un joueur n'est jamais perdu.",
    ["wn_344_dm_standalone"] = "À noter — Le compteur est aussi publié séparément sous le nom TomoDamageMeter. Si tu l'as installé, la copie intégrée à TomoMod s'efface au chargement et te le dit une fois à la connexion, plutôt que deux compteurs se disputent les mêmes fenêtres, réglages et sessions de combat. C'est toujours la copie intégrée qui cède : installer l'addon autonome est un choix délibéré, et les versions déjà diffusées de celui-ci n'ont aucun moyen de savoir qu'elles devraient s'effacer elles-mêmes.",
    ["wn_344_cds_window"] = "Correction — Dans le Cooldown Studio, la colonne de boutons de barres à gauche s'affichait par-dessus le bouton du mode édition en bas de la fenêtre, et les libellés débordaient des boutons qui les portaient : « Import : Buffs suivis » était tout simplement plus large que la case où il se trouvait. La colonne avait dépassé la place qui lui était réservée quand les boutons d'import ont été ajoutés, et rien dans cette interface ne rogne un élément qui déborde : il se dessine par-dessus ce qui se trouve en dessous. La place est désormais calculée à partir de ce qu'elle doit contenir, les boutons sont assez larges pour leur propre texte, et la fenêtre est plus grande pour l'accommoder. Elle cesse aussi de demander plus de place que ton écran n'en a : on lui avait seulement dit de rester à l'écran, ce qui ne sert à rien pour une fenêtre plus grande que l'affichage — sur un écran plus petit, toute la colonne de gauche pouvait se retrouver au-delà du bord. Elle s'adapte maintenant à l'espace disponible, ce qui est précisément ce qui rend son agrandissement possible. AstralForge repose sur la même fenêtre et en profite de la même façon. Sur le tableau de bord, la carte Cooldown Studio est également remontée à côté de la carte Suite Tomo, puisque toutes deux mènent ailleurs.",
    ["wn_344_changelog_popup"] = "Correction — La page Quoi de neuf n'arrivait pas à disposer les notes qu'elle affichait : ouvrir une version écrivait ses paragraphes les uns par-dessus les autres. La raison : un bloc de texte doit être mesuré avant que la fenêtre n'ait décidé de sa largeur, si bien qu'un paragraphe destiné à tenir sur six lignes était mesuré comme une seule, et tout ce qui suivait était placé dans la place qu'une seule ligne aurait occupée. Plutôt que d'apprendre à la page à mesurer du texte, elle transmet désormais la version choisie à cette fenêtre-ci, qui a toujours su défiler. La page elle-même devient un index : chaque version sous forme de bouton avec le nombre de notes qu'elle contient, quatre par ligne, de la plus récente à la plus ancienne — cinquante-neuf dans une seule colonne, cela faisait beaucoup de défilement pour atteindre quoi que ce soit d'ancien. Deux petites choses l'accompagnent. Lire une ancienne version ne compte plus comme avoir lu la version actuelle : aller voir par curiosité ce qui a changé en 3.2.1 n'avalera plus l'annonce d'une mise à jour que tu n'as pas encore vue. Et la barre de défilement de cette fenêtre gardait les deux flèches dorées de Blizzard à chaque extrémité d'une piste par ailleurs verte ; elles ont disparu, et la barre récupère la place qu'elles occupaient.",
    ["wn_344_dm_config"] = "Nouveau — Les réglages du compteur sont désormais une véritable page Damage Meter dans les options de TomoMod, et non plus un bouton qui vous renvoyait vers une autre fenêtre. Le thème, la texture des barres, la police et sa taille, la hauteur des barres et l'accent à la couleur de classe ; l'opacité du fond, hors combat et sur les panneaux de détail ; masquer les royaumes, garder sa propre barre en vue, les infobulles sur les barres, le chronomètre de combat et le côté où il se place, la réinitialisation en entrant en instance, l'aimantation des fenêtres ; les récapitulatifs automatiques de donjon et de mort, et le nombre de lignes qu'un rapport envoie. En dessous, cette page et la fenêtre propre au compteur passent maintenant par une seule et même description de ce qu'il faut rafraîchir quand un réglage change — sans quoi il en existerait deux copies, qui divergeraient dès la première modification de l'une d'elles. Si un rafraîchissement échoue, le réglage est tout de même enregistré, plutôt que de vous montrer une erreur et d'annuler discrètement ce que vous veniez de changer. Les colonnes, l'ajout de fenêtres et le filtrage par catégorie restent volontairement dans la fenêtre du compteur, puisqu'ils agissent sur une fenêtre précise et non sur l'ensemble ; la page le dit et vous y emmène. Cette fenêtre s'ouvrait par ailleurs derrière les options au lieu de passer devant, ce qui est corrigé.",
    ["wn_344_aura_secret"] = "Correction — Les auras des cadres d'unité provoquaient une avalanche d'erreurs sur le patch 12.1 — 189 dans une seule session dans le rapport à l'origine de ce correctif. Le jeu se contentait auparavant de ne rien renvoyer quand un addon demandait les auras d'une unité dans un état qu'il n'approuvait pas ; il refuse désormais la demande franchement, et ce refus n'était pas intercepté, si bien qu'il se déclenchait à chaque événement d'aura. Il l'est maintenant, et le refus a une issue : les auras sont lues une par une à la place, ce qui est plus lent mais reste la seule voie ouverte, et une aura qui s'affiche encore vaut mieux qu'une aura qui produit une erreur. Le suivi de buffs de CooldownForge avait le même problème dans l'autre sens — la mise à jour d'aura envoyée par le jeu peut désormais arriver entièrement illisible, et le simple fait de tester s'il s'agissait d'une mise à jour complète suffisait à échouer, 38 fois de plus dans une session. Une mise à jour illisible est maintenant traitée comme une mise à jour complète et tout est simplement relu, seul moyen de rester à jour quand le détail ne peut pas être consulté.",

    -- =====================
    -- 3.4.3 — Quoi de neuf
    -- =====================
    ["wn_343_changelog"] = "Nouveau — Une page Quoi de neuf dans les options, avec toutes les versions que TomoMod a publiées. Jusqu'ici les notes de version n'apparaissaient que dans la fenêtre qui suit une mise à jour, et celle-ci ne montre que la version que tu viens d'installer : une fois fermée, le texte est perdu. La nouvelle page liste toutes les versions, de la plus récente à la plus ancienne, et cliquer sur l'une d'elles ouvre ses notes. Elle lit exactement les mêmes notes que la fenêtre, il n'y a donc pas de seconde liste qui pourrait prendre du retard.",
    ["wn_343_cdf_resync"] = "Nouveau — Cooldown Studio : une barre construite depuis le gestionnaire de temps de recharge de Blizzard peut désormais être remise en phase avec lui. Ces barres étaient justes le jour où tu les créais et n'avaient ensuite aucun moyen de revenir : une refonte de classe t'obligeait à comparer les listes à la main. Resynchroniser relit la catégorie : les sorts que Blizzard a ajoutés depuis arrivent, ceux qu'il a retirés sont retirés. Tout ce que tu as fait sur la barre survit — un sort toujours listé conserve son entrée exactement comme tu l'avais réglée, condition de glow, visibilité par spécialisation et effets par entrée compris — et ce que tu as ajouté toi-même n'est jamais touché ni supprimé, quoi que fasse la liste de Blizzard. Un sort que tu avais ajouté à la main et que Blizzard ajoute ensuite à la catégorie reste le tien plutôt que d'être récupéré, si bien qu'une resynchronisation ultérieure ne pourra jamais supprimer une entrée que tu as créée.",
    ["wn_343_cds_icons"] = "Cooldown Studio : la liste de ce qu'une barre suit affichait « Sort 384100 » — exact, et d'aucune utilité. Chaque entrée montre maintenant son icône et son nom, l'identifiant restant entre parenthèses à la suite. Tant que le jeu n'a pas mis le sort en cache tu obtiens encore le numéro seul, ce qui est la réponse honnête plutôt qu'une ligne vide.",
    ["wn_343_cds_scale"] = "Nouveau — Cooldown Studio : un curseur d'échelle des icônes, sur les deux dispositions. Agrandir une barre voulait dire déplacer un curseur de largeur puis amener celui de hauteur exactement au même endroit ; c'est désormais un seul réglage. C'est une vue sur la taille que tu avais déjà et non un nouveau réglage, il n'y a donc toujours qu'un seul nombre en dessous et rien à maintenir en accord. Un bouton remet les icônes carrées en conservant la taille que tu avais sous les yeux plutôt qu'en revenant à la valeur par défaut. Dès que tu écartes volontairement la largeur et la hauteur, le curseur d'échelle se grise — « agrandir de 1,2 » n'a plus de réponse unique à ce moment-là — et c'est ce bouton qui le réactive.",
    ["wn_343_iconsize_range"] = "Correction — Cooldown Studio : une taille d'icône inférieure à 24 ou supérieure à 64 semblait acceptée alors qu'elle ne l'était pas. La barre s'affichait à la taille demandée et la conservait, puis une action ultérieure — une resynchronisation, un import, une duplication — la ramenait en arrière sans rien qui permette de relier ce changement à quoi que ce soit que tu avais fait. Pendant ce temps, les réglages séparés de largeur et de hauteur acceptaient 8 à 128, si bien que la même petite icône était atteignable par un réglage et refusée par l'autre. Il n'y a plus qu'une seule plage, 8 à 128, pour les trois. Elle est plus large qu'avant et non plus étroite : aucune barre existante ne change de taille.",
    ["wn_343_studio_shortcut"] = "Nouveau — Un bouton Cooldown Studio sur le tableau de bord : ouvrir le studio ne demande plus de passer d'abord par le panneau CooldownForge.",

    -- =====================
    -- 3.4.2 — Quoi de neuf
    -- =====================
    ["wn_342_astralforge"] = "Nouveau — AstralForge, un éditeur plein écran pour les éléments d'un cadre d'unité. Jusqu'ici, chaque partie d'un cadre se trouvait là où TomoMod avait décidé qu'elle se trouve, et tout ce qu'on te donnait était un curseur pour la décaler de quelques pixels — déplacer le nom de l'autre côté n'était donc pas un réglage, c'était un chiffre assez gros pour l'y pousser. Tu fais désormais glisser chaque élément là où tu veux : quel coin de l'élément s'accroche, et à quoi il s'accroche — le cadre, la barre de vie, la barre de ressource, la barre d'infos. Ça s'aligne sur une petite grille, ça se cale sur les autres éléments quand tu passes devant, et maintenir Maj permet de poser où bon te semble. Les curseurs restent là pour un ajustement de deux pixels, et les deux écrivent la même chose. Ça s'ouvre depuis les options Cadres d'unité et, comme le Cooldown Studio, ça ne se charge que si tu le demandes. Ce que tu déplaces est une copie d'aperçu, jamais un vrai cadre : le jeu protège ces derniers en combat, et les modifier directement est précisément ce qui provoque les problèmes d'interface que TomoMod a passé deux versions à éliminer.",
    ["wn_342_af_nameplates"] = "Nouveau — Les plaques de nom ont droit au même éditeur, et pour elles c'est un terrain entièrement neuf : à part la marque de raid, rien sur une plaque n'avait le moindre réglage de position. Le nom, la valeur et le pourcentage de vie, le niveau, l'icône et le texte de classification, la barre d'incantation avec son icône, son nom, son minuteur et son bouclier, ainsi que l'icône de quête peuvent chacun être placés où tu veux. Ta position de marque de raid est reprise telle quelle, et tout le reste démarre exactement là où il était déjà. Deux choses ne sont volontairement pas déplaçables : les auras, dont la position est calculée à partir de leur rang dans la rangée plutôt que définie, et les éléments accrochés au remplissage d'une barre — une poignée sur ceux-là prétendrait déplacer quelque chose qu'elle ne peut pas déplacer.",
    ["wn_342_af_props"] = "Nouveau — Opacité, échelle et forçage de la taille du texte, par élément. Le forçage démarre à zéro, ce qui signifie « laisse la taille que le module a calculée » : rien ne change tant que tu ne le dis pas. Seuls les réglages qu'un élément donné peut réellement honorer sont affichés : l'opacité a un sens sur un texte, l'échelle non, et une simple image n'accepte ni l'une ni l'autre — tu obtiens donc ceux qui s'appliquent à ce que tu as sélectionné plutôt qu'une rangée figée de curseurs dont la moitié ne fait rien.",
    ["wn_342_af_customtext"] = "Nouveau — Du texte que tu écris toi-même. Ajoute jusqu'à six textes personnalisés sur un cadre d'unité et quatre sur une plaque de nom, écris quelque chose comme « [name] - [level] », et place-le comme n'importe quel autre élément. Les jetons sont nom, niveau, classe, race et guilde sur un cadre, et nom, niveau, classe, race et classification sur une plaque. Il vaut la peine de savoir pourquoi ce n'est pas simplement l'addon qui colle des mots bout à bout : sous Midnight, le jeu transmet le nom et le niveau d'une unité sous une forme qu'un addon n'a pas le droit de lire, donc une opération aussi banale que joindre un nom à un tiret échouerait. Ton modèle est transformé en motif, les valeurs y passent sans être touchées et c'est le jeu lui-même qui assemble le tout.",
    ["wn_342_af_presets"] = "Nouveau — Des préréglages de disposition, et des chaînes de partage. Enregistre sous un nom toute la disposition de ce que tu es en train d'éditer — chaque position, chaque opacité et échelle, chaque texte personnalisé — réapplique-la plus tard, ou transmets-la à quelqu'un sous forme de chaîne à coller. Tout ce qui rentre est vérifié de la même façon, que ce soit le tien ou celui d'un inconnu : les valeurs que l'addon ne reconnaît pas sont écartées, une ancre impossible est refusée avant d'atteindre le jeu, et une disposition qui se référence elle-même en boucle est cassée. Le pire qu'une chaîne collée puisse décrire, c'est une disposition.",
    ["wn_342_af_migration"] = "Tes cadres ne bougent pas. Chaque position que tu avais réglée est convertie dans la nouvelle forme, accompagnée de l'ancre sur laquelle le moteur l'appliquait, si bien qu'un profil converti et un profil tout neuf dessinent exactement le même cadre. Un ancien réglage est abandonné plutôt que converti : un décalage d'auras que le moteur a cessé de lire en 3.0.5. Il n'a aucun effet depuis plusieurs versions, et le convertir aujourd'hui déplacerait des auras qui se trouvent précisément là où tu les as mises. Les conteneurs d'auras cessent également de conserver leur position dans un second endroit à eux : les déplacer en jeu, les placer dans l'éditeur et les régler aux curseurs écrivent désormais au même endroit, ils ne peuvent donc plus se contredire.",
    ["wn_342_af_secret"] = "Correction — Ouvrir AstralForge sur une unité réellement présente pouvait te laisser une fenêtre vide. L'aperçu qu'il construit était alimenté en données réelles, et sur le jeu actuel tout élément d'interface dont le contenu provient d'informations protégées — une valeur de vie, par exemple — cache aussi sa propre position et sa taille aux addons. Or mesurer tout ça est précisément le travail de l'éditeur : la toute première mesure échouait et emportait l'aperçu avec elle. L'aperçu fonctionne désormais sur des données inventées : un nom fictif, une valeur de vie fictive, que rien n'empêche de mesurer et qui ressemblent exactement à ce que tu es en train d'agencer. Deux garde-fous l'accompagnent : ce qui reste malgré tout non mesurable est simplement laissé sans poignée au lieu de bloquer tout ce qui l'entoure, et si l'aperçu ne peut pas être construit du tout, la fenêtre s'ouvre quand même avec sa liste d'éléments, son inspecteur et ses préréglages plutôt que de s'ouvrir vide.",
    ["wn_342_keysync_realm"] ="Mythique+ : la liste des clés du groupe était vide pour toutes les personnes de ton propre royaume. Leur clé était bien reçue et bien conservée depuis le début — elle ne pouvait simplement plus être retrouvée. Quand l'addon de quelqu'un t'envoie sa clé, le jeu le désigne comme « Alice-Varimathras », que ce royaume soit le tien ou non : chaque clé est donc classée sous un nom complet. Mais quand TomoMod interroge le jeu sur la personne qui se tient à côté de toi sur ton royaume, il récupère « Alice » sans royaume, et ça ne correspond à rien. C'est apparu avec le nouveau partage de clés de la 3.4.1, parce que la bibliothèque qu'il a remplacée masquait cet écart dans son propre code. Un nom sans royaume est désormais réessayé avec le tien, donc une clé du même royaume se retrouve à nouveau — et c'est fait une seule fois, à l'endroit où les clés sont stockées, plutôt que d'être quelque chose que chaque écran qui les lit doit penser à faire.",
    ["wn_342_escape_keys"] = "Correction — Tant qu'une fenêtre de TomoMod était ouverte, tes touches ne faisaient plus rien : impossible de te déplacer, et tes sorts ne partaient pas. Toute fenêtre qui se ferme avec Échap doit réclamer le clavier au jeu, et une fenêtre qui tient le clavier garde toutes les touches pour elle à moins de transmettre délibérément le reste — ce qu'elle ne faisait qu'accessoirement, en recevant une touche qui ne l'intéressait pas, et jamais en combat, c'est-à-dire précisément là où perdre ses touches coûte le plus cher. Toutes les touches passent désormais directement ; la fenêtre ne garde qu'Échap, et seulement hors combat. S'y ajoute l'autre moitié du problème : une fenêtre ne tient le clavier que tant qu'elle est réellement affichée. Une fenêtre fermée avec Échap le gardait après coup, si bien que le souci survivait à la fenêtre qui l'avait causé et que la suivante en héritait. Cela concerne toutes les fenêtres de l'addon qui se ferment avec Échap : les options, l'installateur, la fenêtre de butin, le hub Mythique+, TomoScore, l'assistant de métiers, l'habillage des sacs, la fenêtre de copie du chat et le Cooldown Studio.",
    ["wn_342_keysync_debug"] ="Nouveau — /tmt keysync. La commande affiche le canal utilisé par le partage, si tu es en guilde, toutes les clés actuellement en mémoire, puis chaque membre de ton groupe avec l'indication de savoir si sa clé est réellement retrouvée. C'est cette dernière ligne qui compte : une clé stockée mais introuvable est un problème différent d'une clé qui n'est jamais arrivée, et vue depuis la liste du groupe les deux se ressemblent exactement — ce qui explique pourquoi le bug ci-dessus a été plus long à identifier qu'à corriger. La commande demande aussi leurs clés aux membres du groupe en terminant : la relancer une seconde plus tard te dit si quelqu'un a répondu.",
    ["wn_342_cdf_viewer"] = "Nouveau — Cooldown Studio : construis une barre depuis le gestionnaire de temps de recharge de Blizzard en un clic. Trois boutons — Essentiels, Utilitaires et Buffs suivis — créent une barre déjà remplie avec les sorts que Blizzard sélectionne pour la spécialisation où tu es, dans son propre ordre, et les buffs suivis arrivent en tant que buffs et non en tant que temps de recharge : ils s'affichent tant qu'ils sont actifs et décomptent ce qu'il en reste. La liste est lue au moment où tu cliques et n'est jamais stockée : Blizzard tient ces trois catégories à jour au fil des refontes de classes, donc une barre importée suit le jeu au lieu de figer une copie qui serait juste le temps d'un patch et discrètement fausse à partir du suivant. Là où un talent remplace un sort par un autre, c'est le remplaçant qui arrive sur la barre, pour que l'icône corresponde à celle de ton grimoire. C'est un point de départ, pas une contrainte : ce que tu obtiens est une barre ordinaire que tu peux réordonner, élaguer et restyler. Et si ton client n'a pas le gestionnaire de temps de recharge, ou si Blizzard ne sélectionne rien pour la spécialisation où tu es, le studio te le dit au lieu de te donner une barre vide.",

    -- =====================
    -- 3.4.1 — Quoi de neuf
    -- =====================
    ["wn_341_style"] = "Suivi Mythique+ : c'était le dernier écran de TomoMod à porter ses propres couleurs. La version précédente avait aligné le tableau de fin de clé et disait que le suivi affiché pendant la clé ne s'accorderait pas tant qu'il n'aurait pas eu le même traitement — le voici. Il utilise désormais le même vert, le même texte et les mêmes bordures que tous les autres panneaux, sur un fond presque noir teinté de menthe. Un réglage de taille de police l'accompagne, de 0,70 à 1,60 : il agrandit le texte sans agrandir le panneau.",
    ["wn_341_segments"] = "Suivi Mythique+ : le chrono est maintenant découpé en trois segments, un par coffre, chacun décomptant le temps restant avant que ce coffre soit perdu. Jusqu'ici le panneau affichait le temps écoulé et l'écart avec la limite totale, et « combien de temps avant de perdre le +2 » était un calcul que tu faisais de tête entre deux packs. Les segments sont dimensionnés sur les vrais paliers du donjon, ils se lisent menthe, jaune puis rouge de gauche à droite — la fenêtre en cours se désigne donc toute seule par sa couleur — et un segment dépensé s'atténue au lieu de disparaître, pour que la barre reste l'historique de la clé. Si tu préfères lire la barre par la forme plutôt que par la couleur, un réglage peint les trois dans le même vert.",
    ["wn_341_presets"] = "Suivi Mythique+ : un panneau figé est devenu trois allures. Panneau, c'est ce que tu avais déjà. ATH retire le fond et le bloc d'en-tête et liste les objectifs en texte simple, un peu plus grand, dans une police condensée. Minimal, c'est trois lignes et rien d'autre — informations, chrono, packs — la liste des boss disparaît et son compte remonte dans l'en-tête : tu sais toujours que tu es à 2 sur 4 sans y consacrer quatre lignes. Tout ce qu'un préréglage définit est aussi un réglage à part : fond, bloc d'en-tête, nom du donjon, liste des boss, disposition du chrono, couleurs des segments, taille du texte. Change-en un à la main et le préréglage affiche « personnalisé » au lieu de faire comme si tu y étais encore.",
    ["wn_341_forces"] = "Suivi Mythique+ : la barre de packs pouvait mentir plutôt qu'avouer qu'elle ne voyait rien. Le jeu masque de plus en plus de valeurs en combat, et la barre faisait quand même ses calculs dessus — un compte illisible ressortait donc à zéro, et une barre qui se vide en plein pack ne ressemble pas à une donnée manquante, elle ressemble à un reset. Elle conserve désormais le dernier chiffre réellement lu et se replie par paliers : comptes exacts, puis pourcentage seul, puis figée. Elle affiche aussi ce qu'il reste à tuer plutôt que 730 / 1000, et annonce l'heure à laquelle le compte a été bouclé.",
    ["wn_341_bossnames"] = "Suivi Mythique+ : les noms de boss venaient d'une table écrite à la main qui périme à chaque saison. Blizzard ajoute des donjons et réutilise les entrées du journal de l'un à l'autre : une liste pareille est fausse le jour où le patch sort et rien ne t'en avertit — les noms se dégradent simplement en « Boss 1 ». Les noms sont désormais résolus en direct depuis le jeu, de trois façons dans l'ordre : la carte où tu te trouves, puis le nom du donjon comparé au journal, puis le texte brut de l'objectif si rien d'autre n'aboutit. Ce qui est trouvé est retenu par donjon : c'est appris et non écrit d'avance, donc ça ne peut pas périmer.",
    ["wn_341_splits"] = "Suivi Mythique+ : tu n'avais rien à quoi comparer une clé. Chaque clé terminée est maintenant enregistrée par donjon et par niveau, et à la tentative suivante chaque boss indique ton avance ou ton retard sur ton meilleur run. Les packs ont droit au même traitement : à chaque kill, le suivi note où en était ton meilleur run sur le trash à ce moment-là et t'affiche l'écart. Une clé dépletée est enregistrée aussi — c'est peut-être ta seule référence sur ce donjon, et une lente vaut mieux que rien. Rien n'est préchargé : une table « trash attendu au boss 2 » livrée par un addon serait l'itinéraire de quelqu'un d'autre et serait fausse le jour où le donjon est rééquilibré. Un bouton dans les options efface ce qui a été enregistré.",
    ["wn_341_banner"] = "Suivi Mythique+ : la fin d'une clé passait sans un mot. Il y a désormais une bannière — dans les temps ou dépletée, le temps du run, les upgrades, et la marge entre parenthèses. La marge, c'est le chiffre que tout le monde annonce à voix haute quand la clé se termine, et c'était la seule chose que tu devais reconstituer toi-même à partir d'un chrono déjà arrêté.",
    ["wn_341_options"] = "Suivi Mythique+ : il avait sa propre fenêtre d'options, avec les mêmes réglages que la page Mythique+ de la configuration de TomoMod — deux endroits pour changer une même valeur, et ils divergeaient. Elle a disparu : /tmt ouvre désormais la configuration sur la page Mythique+. Toutes les autres commandes /tmt sont inchangées.",
    ["wn_341_legibility"] = "Suivi Mythique+ : le texte écrit par-dessus une barre remplie était illisible. Chaque libellé du suivi porte un contour noir, et ce texte-là était lui-même presque noir : il se dissolvait donc dans son propre contour — les marqueurs de coffre sur le chrono et le libellé de la barre de trash n'étaient que des taches, alors que l'horloge blanche juste à côté restait nette. Ils sont clairs désormais. Deux détails suivent : une durée négative pouvait s'afficher comme une grande valeur positive, -3:40 devenant 56:20, et le premier boss ne répète plus son temps de kill deux fois sur la même ligne.",
    ["wn_341_cds_taint"] = "Cooldown Studio : l'ouvrir pouvait t'empêcher de te déconnecter, par deux chemins distincts. Une ligne écrivait dans une table appartenant à Blizzard — sans rien changer à sa valeur, mais y écrire suffit pour que le jeu se méfie ensuite de toutes les fenêtres construites à partir de cette table, y compris la confirmation de déconnexion. Par ailleurs, la fenêtre « copier le style depuis » gérait Échap avec sa propre copie d'un code qui existe déjà ailleurs dans l'addon, et cette copie avait dérivé : elle avait perdu sa vérification de combat et rendait les touches au jeu d'une façon qui empêchait le menu de s'ouvrir. Les deux sont corrigés, et la fenêtre partage désormais l'implémentation commune au lieu d'en garder une à elle. Ni l'un ni l'autre ne touchait une session où tu n'avais pas ouvert le Studio, ce qui explique le temps qu'il a fallu pour les identifier.",
    ["wn_341_keysync"] = "TomoMod se signalait lui-même comme source de problèmes d'interface des dizaines de fois à chaque combat, sans en être un. La cause était une bibliothèque embarquée, LibOpenRaid, qui détermine si le jeu masque une valeur en essayant de la lire et en rattrapant l'erreur — la réponse est juste, mais le jeu inscrit le nom de TomoMod dans son journal à chaque tentative, et ça arrive sans arrêt. La bibliothèque n'est plus livrée. Elle n'était là que pour quatre fonctions de clés, alors qu'elle synchronisait aussi cooldowns, équipement, talents et durabilité — et c'est la partie cooldowns qui causait tout. Le partage de clés est désormais celui de TomoMod, dans un fichier bien plus petit : ta clé vient directement du jeu, le reste est échangé avec ton groupe et ta guilde, et conservé jusqu'au reset hebdomadaire. Une chose devrait fonctionner pour la première fois : la liste des clés du groupe se rafraîchit toute seule quand une clé change — l'ancien rappel était branché d'une façon que la bibliothèque n'appelait jamais.",
    ["wn_341_buffskin"] = "Le skin des buffs et debuffs a été retiré — la fonctionnalité entière, avec son onglet et ses réglages. Elle ne peut pas fonctionner sur le jeu actuel : les boutons que Blizzard utilise pour les auras masquent désormais leur propre taille aux addons, et poser une bordure sur l'un d'eux lève une erreur à l'intérieur du code de Blizzard, et non dans celui de TomoMod où elle aurait pu être rattrapée. À cela s'ajoute que ces boutons sont remaniés à presque chaque patch : cette version à elle seule y a consacré cinq tentatives. C'est un entretien sans fin, sur la seule partie de l'interface où l'affichage de Blizzard est déjà correct. Ta fenêtre de buffs revient à celle du jeu, et les réglages sont effacés de tes profils faute d'endroit où les reporter. Si un skin de buffs compte vraiment pour toi, un addon d'auras dédié est la réponse honnête.",
    ["wn_341_auratracker"] = "Le suivi d'auras a été retiré. CooldownForge fait le même travail en mieux, et faire tourner deux surcouches qui se disputent le même coin de l'écran ne pouvait pas finir autrement. Son onglet, ses préréglages, son mover et ses réglages partent avec lui, et un nettoyage unique retire les réglages résiduels de tes profils au lieu de les trimballer indéfiniment. Si tu y avais ajouté des sorts à la main, ils ne disparaissent pas en silence : ils ne peuvent pas être convertis automatiquement, alors TomoMod les liste une fois à ta prochaine connexion, avec leurs noms, et tu peux recréer ceux qui comptent encore dans le Cooldown Studio.",
    ["wn_341_cds_reload"] = "Cooldown Studio : le fermer peut maintenant recharger ton interface, et le fait par défaut. Le Studio ne se charge que si tu le demandes, mais le jeu ne sait pas décharger un addon — un rechargement est la seule chose qui le libère, et c'est aussi ce qui efface ce que la session aurait pu accrocher au passage. La proposition attend un moment raisonnable : jamais en combat, jamais pendant une clé, jamais dans un donjon ou un raid, et elle revient une fois dehors. Tu peux la désactiver dans les options de CooldownForge. Par ailleurs, quitter le Studio alors que les barres étaient déverrouillées les laissait bloquées en mode édition, avec le bouton de reprise flottant à l'écran ; les deux façons de fermer la fenêtre font maintenant le ménage.",

    -- =====================
    -- 3.3.6 — Quoi de neuf
    -- =====================
    ["wn_336_cdf_active"] = "CooldownForge : un buff actif ressemblait exactement à un sort en recharge. Depuis qu'une icône peut suivre un buff plutôt qu'un cooldown, les deux états arrivaient à l'écran sous la même image, et le seul moyen de les distinguer était de lire le chiffre dessus. Deux nouveaux réglages les séparent : le balayage du cooldown et la bordure peuvent chacun prendre votre couleur de classe, ou une couleur de votre choix, pendant que le buff suivi est actif. Les deux sont désactivés partout par défaut, donc rien de ce que vous avez déjà construit ne change, et ils ne s'appliquent qu'aux entrées qui suivent réellement un buff.",
    ["wn_336_cdf_threshold"] = "CooldownForge : le minuteur peut changer de couleur quand un sort est presque revenu. Réglez un seuil en secondes, jusqu'à 60, et choisissez la couleur qu'il prend en dessous — lire une couleur en plein combat est plus rapide que déchiffrer un chiffre. Zéro le désactive, et c'est la valeur par défaut. Là où le jeu refuse d'indiquer à un addon le temps restant, ce qui est le cas en contenu restreint, le minuteur garde sa couleur normale au lieu de deviner : un décompte qui se trompe serait pire qu'un décompte resté neutre.",
    ["wn_336_cdf_font"] = "CooldownForge : le texte de vos icônes était figé sur une seule police. Le réglage existait dans chaque barre depuis la sortie de la fonctionnalité et rien ne l'avait jamais lu — le minuteur, les cumuls, le nom du sort et le minuteur miroir étaient tous codés en dur sur la Poppins de TomoMod. Vous pouvez désormais choisir n'importe quelle police partagée par vos autres addons, opter pour un contour fin, épais ou absent, et donner au minuteur sa propre taille indépendamment du texte des cumuls et du nom, si bien que changer de police n'oblige plus à abandonner les tailles de votre preset. Les deux curseurs de taille vont maintenant de 8 à 28 pixels au lieu de 9 à 20. Sans addon de partage de polices installé, la liste ne contient que Poppins et le dit.",
    ["wn_336_cdf_glow_charges"] = "CooldownForge : le glow peut attendre que toutes les charges soient revenues. Un sort à deux ou trois charges était prêt ou non du point de vue du glow, si bien qu'une charge sur trois s'allumait exactement comme trois sur trois. La nouvelle condition se déduit de la recharge elle-même plutôt que d'un comptage — le jeu masque le nombre de charges en cours de combat, et compter est précisément ce qui n'y est pas possible. Un sort sans charges retombe sur la simple disponibilité, pour que la condition ne soit pas silencieusement inutile sur la plupart de vos entrées.",
    ["wn_336_cdf_glow_stacks"] = "CooldownForge : le glow peut attendre qu'un buff suivi atteigne un nombre de cumuls, réglable par barre et redéfinissable par icône. Le jeu ne publie pas de maximum pour un buff, c'est donc à vous de donner le nombre — 2 à 20 sur une barre, jusqu'à 99 sur une entrée. Si le nombre de cumuls est illisible, le glow reste éteint plutôt que de se déclencher sur une supposition, puisqu'un glow est fait pour être suivi d'une action.",
    ["wn_336_escape_taint"] = "Fenêtres : appuyer sur Échap pouvait ne plus ouvrir le menu du jeu du tout, vous laissant sans moyen normal de quitter. Huit fenêtres de TomoMod se fermaient avec Échap en s'inscrivant sur une liste que Blizzard parcourt depuis le code de son menu, et ce code passe trois appels que le jeu refuse dès que quelque chose a été perturbé dans votre session — le menu ne s'ouvrait donc jamais et Échap ne faisait rien. Ces fenêtres gèrent maintenant Échap elles-mêmes et ne touchent plus au menu du jeu. Toutes les autres touches continuent de passer. Une conséquence à connaître : sur ces huit fenêtres, Échap ne ferme plus pendant un combat, car l'appel qui rend cela possible est lui-même restreint en combat. Leur bouton de fermeture, lui, fonctionne toujours.",
    ["wn_336_statusbar2"] = "Nouveau — Masquer la barre d'état 2 de Blizzard, dans QOL, Automatisations. La seconde barre d'état du mode édition est placée à côté de la principale et non à l'intérieur, si bien que l'option qui masque les barres d'état de Blizzard ne l'atteignait pas, et que rien nulle part ne le faisait. Elle est rendue invisible et non cliquable plutôt que supprimée, et c'est précisément ce qui évite les erreurs : la barre reste celle de Blizzard, donc elle demeure en place dans le mode édition et vous pouvez toujours l'y déplacer. Décocher l'option la rétablit après un rechargement.",
    ["wn_336_ab_empty_refresh"] = "Barres d'action : emplacements vides masqués, glisser un sort sur l'un d'eux laissait le bouton vierge. Le sort s'y trouvait bel et bien et se lançait au clic, mais rien n'était dessiné dessus jusqu'au rechargement — et déposer sur une barre effaçait les emplacements voisins qui venaient d'apparaître pour le glisser-déposer. Le masquage des emplacements vides a changé de méthode à la version précédente pour cesser de provoquer des erreurs sur les boutons de Blizzard, et la nouvelle méthode laissait la barre ignorer qu'un emplacement venait d'être rempli. Elle s'en aperçoit désormais, y compris quand un changement de page ou de posture modifie ce que pointe un bouton.",
    ["wn_336_uf_aura_growth"] = "Cadres d'unité : les auras ne poussaient que vers le bas. Le réglage de direction couvrait la gauche et la droite, et la moitié verticale de la question n'avait aucun réglage — si bien qu'un cadre placé en bas de l'écran envoyait sa deuxième rangée de debuffs hors du bord inférieur, sans rien nulle part pour l'en empêcher. Une direction verticale s'ajoute désormais à côté de l'horizontale dans l'onglet Auras de chaque unité, et les rangées peuvent s'empiler vers le haut. Vers le bas reste la valeur par défaut et rien de ce que vous avez déjà réglé ne bouge ; le cadre lui-même ne bouge pas non plus, c'est le bloc d'auras qui grandit dans l'autre sens.",
    ["wn_336_ts_palette"] = "Mythic+ : le tableau de fin de clé était le seul écran de TomoMod à avoir ses propres couleurs — un accent cyan là où le reste de l'addon est vert, sur un fond bleuté là où le reste est neutre. Il datait d'avant son intégration à TomoMod et n'avait jamais été mis au diapason, si bien qu'il donnait l'impression d'être la fenêtre de quelqu'un d'autre. Il reprend maintenant le même thème que tout le reste. Deux couleurs restent volontairement inchangées : la barre « dans les temps » et son texte gardent leur vert propre, car sur un panneau déjà vert partout, un repère « dans les temps » du même vert n'indique plus rien. Le tracker affiché pendant la clé n'est pas encore touché, les deux ne s'accorderont donc qu'une fois qu'il aura reçu le même traitement.",
    ["wn_336_cdf_talent"] = "CooldownForge : une icône peut être liée à un talent — affichée seulement s'il est pris, ou seulement s'il ne l'est pas. La seconde moitié est aussi utile que la première : un build qui abandonne un talent en gagne généralement un autre à la place, et les deux icônes peuvent désormais cohabiter dans la même barre avec une seule à l'écran. Vous indiquez le sort que le talent accorde plutôt qu'un numéro de nœud : les nœuds sont renumérotés à chaque refonte des talents, pas les sorts, donc la condition survit à un patch. Elle suit aussi vos loadouts maintenant — changer de build ne s'annonce pas de la même façon que modifier des talents, et un seul des deux signaux était écouté, de sorte qu'une condition pouvait continuer à répondre selon le build précédent jusqu'à ce qu'autre chose force un rafraîchissement.",

    -- =====================
    -- 3.3.5 — Quoi de neuf
    -- =====================
    ["wn_335_cdf_border"] = "CooldownForge : tirer le curseur d'épaisseur de bordure faisait disparaître la bordure au lieu de l'épaissir. Chaque réglage de style était stocké d'un bloc, alors que l'éditeur écrit un champ à la fois — régler l'épaisseur jetait donc le mode de bordure rangé à côté, et sans mode l'icône était dessinée sans aucune bordure. Choisir une couleur produisait la même chose, et choisir un mode remettait discrètement l'épaisseur à 1. Ces réglages conservent désormais les champs auxquels vous n'avez pas touché. Aucune barre ne change d'elle-même ; refaites le réglage et vous obtenez ce que vous demandiez la première fois.",
    ["wn_335_cdf_border_paint"] = "CooldownForge : même une fois qu'elle a cessé de disparaître, la bordure restait à peine visible, et 1 pixel rendait exactement comme 4. Le contour est dessiné juste à l'intérieur du bord de l'icône, et l'image de l'icône le recouvrait entièrement — la bordure était donc peinte puis cachée dessous, et l'épaissir ne faisait qu'en enterrer davantage. L'image s'arrête désormais avant la bordure et lui laisse la place. Deux conséquences à prévoir : une icône bordée affiche son image très légèrement plus petite, ce qui est le prix d'une bordure, et une épaisseur réglée à l'époque où le curseur semblait ne rien faire devient d'un coup visible — une barre restée sur 4 paraîtra donc bien plus lourde tant que vous ne l'aurez pas remise à ce que vous vouliez réellement. Les icônes sans bordure ne changent pas.",
    ["wn_335_cdf_preset"] = "CooldownForge : toucher au moindre réglage fin transformait discrètement votre barre en barre Tomo. Choisir une couleur de bordure sur une barre Net ou Verre faisait basculer son style sur « Personnalisé », et Personnalisé n'était pas un vrai style — l'icône retombait donc sur Tomo et la base que vous aviez choisie disparaissait. Le preset utilisé par une barre et le fait qu'elle ait des réglages fins sont désormais deux choses distinctes : changer de preset conserve vos réglages fins par-dessus le nouveau, et modifier un réglage fin ne touche plus au preset. Les barres déjà enregistrées en Personnalisé deviennent Tomo en gardant leurs réglages, ce qui correspond à la façon dont elles étaient déjà dessinées : rien ne change à l'écran.",
    ["wn_335_cdf_thickness"] = "CooldownForge : le curseur d'épaisseur de bordure monte jusqu'à 10 au lieu de 4. Quatre était une limite raisonnable tant que la bordure était invisible ; maintenant qu'elle est réellement dessinée, elle ne l'est plus. Gardez à l'esprit que la bordure prend son épaisseur sur l'image de l'icône : à 10 sur une petite icône, il n'en reste presque rien.",
    ["wn_335_cdf_target"] = "CooldownForge : une barre peut maintenant dépendre du fait que vous ayez une cible, aux côtés des conditions de combat, d'instance, de groupe et de raid, avec les mêmes trois choix — indifférent, exiger, exiger le contraire. Pour la barre que vous ne voulez voir que quand vous êtes réellement sur quelque chose, ou la barre utilitaire qui doit s'effacer dès que vous sélectionnez une cible.",
    ["wn_335_cdf_dim"] = "CooldownForge : une barre dont la condition de visibilité n'est pas remplie peut désormais s'atténuer au lieu de disparaître. Choisissez « réduire l'opacité » plutôt que « masquer », et réglez jusqu'où elle s'efface, de 5 % à 95 %. La barre atténuée reste vivante — elle continue de suivre les cooldowns au lieu de se figer — si bien que « en combat = oui » avec cette option vous laisse hors combat une barre lisible à demi visible, plutôt qu'une barre qui revient déjà périmée. Masquer reste le comportement par défaut, et rien ne change pour les barres déjà configurées.",
    ["wn_335_cdf_iconwh"] = "CooldownForge : les icônes ne sont plus forcément carrées. La largeur et la hauteur ont désormais chacune leur curseur, de 8 à 128 pixels, au lieu d'une seule taille pour les deux — des icônes larges et plates pour une rangée en haut de l'écran, hautes et étroites pour une colonne à côté de vos cadres. Les barres déjà construites ne bougent pas : les nouvelles valeurs démarrent non définies, et non défini veut dire « garder l'ancienne taille carrée ».",
    ["wn_335_cdf_aura"] = "CooldownForge : une icône peut suivre un buff au lieu d'un cooldown. Passez une entrée en « buff suivi » et elle reste hors écran tant que le buff est absent, puis apparaît avec sa durée restante et ses cumuls tant qu'il est actif — un proc peut ainsi voisiner sur la même barre avec le cooldown qui le déclenche. Vous pouvez aussi indiquer un autre ID de buff, pour les procs accordés par un sort et appliqués sous un autre. En Mythique+, le jeu masque l'essentiel de ce qu'un addon peut lire d'un buff ; c'est traité séparément ci-dessous.",
    ["wn_335_cdf_secret"] = "CooldownForge : un buff suivi disparaissait dès qu'un combat commençait et revenait dès qu'il se terminait. Toutes les recherches passaient par l'ID du sort du buff, or dans Midnight le jeu masque ce nombre pendant le combat — mesuré comme parfaitement lisible hors combat contre 6,5 % en combat, chaque buff suivi devenant introuvable dans la frame même où le pull démarrait. Le jeu communique bien cet ID une fois, au moment où le buff est appliqué, accompagné d'une référence à cette application précise : TomoMod retient désormais le couple et interroge ensuite cette application, ce à quoi le jeu continue de répondre. La durée restante et les cumuls sont également de retour en Mythique+, lus de la même manière — la note précédente affirmant que les buffs suivis y fonctionnent mais sans minuteur n'est plus exacte.",
    ["wn_335_cdf_aura_sources"] = "CooldownForge : les buffs suivis sont désormais retrouvés par deux chemins au lieu de quatre. Chacun avait été ajouté pour couvrir un cas que le précédent manquait, et rien ne disait lequel faisait réellement le travail — ils ont donc été mesurés sur quelque 12 700 recherches chacun. Deux portaient toute la fonctionnalité, et ils en couvrent des moitiés opposées : l'un fonctionne pendant un combat, l'autre en dehors. Les deux qui ne produisaient presque rien ont été retirés, avec eux un balayage de tous vos buffs qui tournait à chaque image et pour chaque barre. Une lacune de plus disparaît au passage : un buff qui gagne seulement un cumul est signalé par le jeu comme une mise à jour et non comme un nouveau buff, si bien qu'un proc repéré ainsi en plein combat n'était jamais enregistré. Reste une limite du jeu, bonne à connaître plutôt qu'à chercher : en combat, il ne nomme qu'une partie des auras. Un buff déjà actif à l'entrée en combat est suivi normalement ; un buff appliqué en plein milieu n'est parfois pas identifiable, et son icône reste masquée. Il n'y a aucun réglage pour cela, et l'option de buff suivi le dit maintenant sur place.",
    ["wn_335_cdf_viewer_source"] = "CooldownForge : un proc qui tombe au milieu d'un combat est désormais suivi lui aussi — la limite décrite juste au-dessus est en grande partie levée. Le jeu refuse de dire à un addon de quel buff il s'agit, mais il le dessine à l'écran depuis le début : l'affichage des buffs suivis de Blizzard n'est pas soumis aux restrictions qui pèsent sur un addon. TomoMod lit maintenant cet affichage — icône présente ou non, temps restant, nombre de cumuls — au lieu de poser une question à laquelle le jeu ne répondra pas en combat. Rien n'est écrit en dur et rien de protégé n'est touché : il lit la même image que vous. Cela ne couvre que les buffs que l'affichage des buffs suivis de Blizzard porte réellement : pour tout le reste, les deux méthodes précédentes répondent exactement comme avant, donc cela ajoute des cas sans en retirer aucun. À savoir si vous utilisez le nouveau masquage barre par barre : masquer une barre du Cooldown Manager ne vous coûte pas cette source, car le masquage passe par la transparence et la barre continue de tourner en dessous. Un détail visuel à prévoir en combat : là où le jeu retient les nombres tout en dessinant quand même le décompte, TomoMod recopie ce chiffre sur votre icône — vous avez le temps restant sous forme de nombre, sans le balayage derrière, et il avance par paliers plutôt qu'en continu, car la barre se rafraîchit sur événements et non sur un minuteur.",
    ["wn_335_cdf_aura_timer"] = "CooldownForge : un buff suivi pouvait apparaître sans minuteur ni balayage alors même que le jeu avait indiqué exactement le temps restant. Il existait deux façons d'afficher un décompte sur l'icône, et c'est la mauvaise qui était choisie : celle qui prend un objet de durée, que le jeu renvoie sous une forme différente de celle attendue par l'affichage de recharge. Elle l'acceptait, ne dessinait rien et ne signalait aucune erreur — le filet de sécurité censé rattraper cet échec ne se déclenchait donc jamais, et la voie numérique, qui aurait fonctionné, n'était jamais atteinte. Les nombres lisibles sont désormais utilisés en premier, et l'objet uniquement quand le jeu refuse de donner les nombres. Si vos buffs suivis s'affichaient en icône nue, ils retrouvent leur minuteur et leurs cumuls.",
    ["wn_335_cdf_glow_aura"] = "CooldownForge : la condition de halo « tant qu'un buff est actif sur vous » s'éteignait pendant toute la durée des combats, et personne n'avait fait le lien avec les buffs suivis. Elle interrogeait le jeu de la même manière que les buffs suivis à l'origine — celle qui cesse de répondre dès l'entrée en combat — si bien que le halo s'arrêtait simplement, ce qui ressemble à un halo mal configuré plutôt qu'à un bug. Elle retrouve désormais les buffs exactement comme le font les icônes de buff suivi, de sorte que les deux ne peuvent plus être en désaccord sur ce que vous portez.",
    ["wn_335_microbar"] = "Nouveau — Micro Barre : la petite rangée de boutons de menu de Blizzard devient une barre à vous. Choisissez quels boutons apparaissent et dans quel ordre, à l'horizontale ou à la verticale, combien par ligne, leur taille, leur espacement, leur échelle et leur opacité, et placez-la où vous voulez via le panneau Déplacements. Elle peut rester à l'écran, apparaître au survol, ou apparaître au survol tout en restant visible en combat. Les icônes peuvent prendre la couleur de votre classe, une couleur de votre choix ou leur apparence d'origine, avec désaturation optionnelle et zoom sous le curseur. Chaque bouton se contente de transmettre votre clic à celui de Blizzard : tout continue donc de fonctionner en combat, et rien ne casse quand un nouveau panneau est ajouté au jeu. Les boutons d'origine continuent aussi de tourner en dessous, si bien que leurs alertes, leurs états grisés et leurs raccourcis peuvent être répercutés sur les vôtres — avec quatre styles de halo d'alerte au choix, l'atténuation de ce qui est indisponible, et le raccourci dessiné sur l'icône.",
    ["wn_335_cdf_aura_gate"] = "CooldownForge : un buff suivi n'a plus besoin d'être un sort que vous pouvez lancer. Avant d'afficher la moindre icône, la barre vérifie que l'entrée vous concerne, et pour un sort elle consultait votre grimoire — ce qui est juste pour un cooldown et faux pour un buff. Les buffs de proc vous sont accordés par un talent ou appliqués par un autre sort : votre grimoire répond donc que vous ne les avez pas, et l'entrée était écartée avant que quoi que ce soit ne regarde si le buff était réellement actif. L'icône n'apparaissait jamais — ce qui est l'essentiel de l'intérêt des buffs suivis. Un buff suivi est désormais jugé sur le buff.",
    ["wn_335_cdf_aura_link"] = "CooldownForge : suivre un proc n'impose plus d'aller dénicher l'ID du buff lui-même. Une capacité et le buff qu'elle accorde n'ont presque jamais le même ID : saisir la capacité — le geste évident — surveillait donc un buff que personne n'a jamais, et l'icône restait simplement hors écran. Une entrée essaie désormais aussi ce que le jeu relie à l'ID que vous avez saisi : le Cooldown Manager de Blizzard résout déjà ce problème pour son propre affichage des buffs suivis, et TomoMod en lit la réponse. Rien n'est codé en dur, si bien que cela suit tout seul un patch qui redirige un proc ou un talent qui l'échange. Le champ d'ID de buff optionnel fonctionne toujours et reste prioritaire, pour les cas que le jeu ne relie pas.",
    ["wn_335_cds_reorder"] = "Cooldown Studio : les entrées d'une barre peuvent être déplacées vers le haut et vers le bas. Réordonner ses icônes imposait jusqu'ici de retirer une entrée puis de la rajouter à la fin, et de refaire tout ce qui suivait. Si le panneau d'options est ouvert sur l'entrée que vous déplacez, il suit cette entrée au lieu de rester sur l'emplacement — il finissait auparavant par éditer celle qui avait pris sa place.",
    ["wn_335_mplus_teleport_override"] = "Mythique+ : un téléporteur de donjon présent dans votre grimoire pouvait quand même être annoncé comme non appris — la ligne grisée, l'infobulle indiquant qu'il n'était pas disponible, le clic sans effet. Quand un donjon revient dans une saison ultérieure, Blizzard réémet son téléporteur sous la forme d'un autre sort : celui de Culmination du ciel se lance désormais sous le nom « Voie des cieux », et non le sort de Warlords que la table de TomoMod répertorie. La vérification ne portait que sur le sort répertorié : posséder le sort actuel était donc indiscernable de ne rien posséder. Elle demande maintenant aussi au jeu quel sort remplace celui qu'elle connaît, et accepte l'un ou l'autre — par numéro de sort et non par nom, donc cela fonctionne quelle que soit la langue de votre client, et cela suivra une future saison qui redéfinit un téléporteur sans avoir besoin d'une mise à jour.",
    ["wn_335_ab_taint"] = "Barres d'action : l'option « afficher les emplacements vides » était à l'origine d'une rafale d'erreurs d'action bloquée sur les boutons de la barre en bas à gauche — des erreurs que le jeu imputait à l'addon qui se trouvait en train de tourner à cet instant, ce qui a récemment donné l'impression que Cooldown Studio en était responsable. L'affichage des emplacements vides passait par l'écriture dans l'état interne des boutons de Blizzard et par un affichage forcé, ce que le jeu refuse ensuite de toucher. L'option utilise désormais le réglage « toujours afficher les barres d'action » du jeu lui-même, et les barres qui ne doivent pas montrer leurs emplacements vides sont rendues invisibles et non cliquables à la place. Blizzard garde la main sur ses boutons. Deux choses à savoir : ce réglage est global, il s'active donc dès qu'une seule de vos barres veut ses emplacements vides, et si vous l'aviez activé vous-même dans les options de Blizzard, il sera remis sur inactif dès qu'aucune barre TomoMod n'en a besoin. Déposer un sort sur un emplacement vide fonctionne exactement comme avant.",
    ["wn_335_cdm_viewers"] = "Cooldowns : les quatre barres du Cooldown Manager de Blizzard peuvent désormais être masquées une par une, depuis le panneau Cooldowns à côté du bouton du Cooldown Studio — Essential, Utility et les deux affichages de suivi des buffs ont chacun leur case. En cocher une retire cette barre de l'écran et du mode placement de TomoMod, et laisse les trois autres où elles sont. Elle remplace une case unique qui ne masquait rien : elle se contentait d'arrêter l'habillage TomoMod de ces barres, qui restaient donc à l'écran dans l'apparence d'origine de Blizzard — une case intitulée « masquer les barres du Cooldown Manager » qui les rendait plus visibles au lieu de moins. Une barre masquée est rendue invisible et non cliquable, pas supprimée : c'est toujours la barre de Blizzard, elle continue de tourner en dessous, et son existence même se décide toujours dans le mode édition de Blizzard. La décocher la remet exactement là où vous l'aviez placée. L'interrupteur de CD & Ressources n'a pas bougé et répond à une autre question — si TomoMod habille ces barres, et non lesquelles vous voulez voir. Les deux fonctionnent aussi ensemble désormais : masquer une barre continue de marcher quand le module Cooldown Manager lui-même est désactivé, seule combinaison où la case était enregistrée sans jamais être appliquée à quoi que ce soit — et c'est précisément ce qu'essaiera quelqu'un qui veut voir ces barres disparaître.",
    ["wn_335_cdf_entry_spec"] = "CooldownForge : la spécialisation d'une entrée ne pouvait être choisie qu'au moment où vous l'ajoutiez. Ensuite, plus rien nulle part ne permettait d'en changer — une icône ajoutée sur la mauvaise spé, ou ajoutée avant que vous décidiez de la restreindre à une seule, devait être supprimée puis rajoutée, ce qui lui faisait aussi perdre sa place dans la barre. Le menu déroulant se trouve désormais sur l'entrée elle-même, aussi bien dans Cooldown Studio que sur la page de réglages Cooldowns.",
    ["wn_335_scrollbar_click"] = "Réglages : la barre de défilement de la fenêtre des réglages se voit et s'utilise enfin. C'étaient cinq pixels de gris sombre sur un panneau sombre — quasiment impossible à attraper, et déjà difficile à remarquer, si bien que la molette était en pratique le seul moyen de descendre une longue page. Cliquer sur le rail au-dessus ou en dessous du curseur fait maintenant sauter presque un écran dans cette direction, et le curseur se saisit sans avoir à le viser au pixel près. Son aspect change aussi, volontairement : un peu plus large, dans un gris plus clair, avec un fin trait sombre le long de son bord intérieur pour le détacher du panneau. Les zones de texte qui contiennent les chaînes d'import et d'export ont la même barre, et s'alignent désormais dessus. Cela vaut pour toutes les pages des réglages, pas seulement une.",
    ["wn_335_cds_tabjump"] = "Cooldown Studio : changer à peu près n'importe quoi vous projetait sur un autre onglet. Modifier le style d'une icône vous déposait sur Partage, cocher une condition de visibilité vous déposait sur Disposition. L'éditeur se reconstruit après presque chaque modification et rouvrait l'onglet qu'il avait mémorisé — mais il ne mémorisait un onglet que la toute première fois que celui-ci était construit, si bien qu'il restait bloqué sur le dernier que vous aviez ouvert pour la première fois, et revenir sur un onglet déjà visité ne le mettait jamais à jour. Il suit maintenant l'onglet où vous vous trouvez réellement.",

    -- =====================
    -- 3.3.4 — Quoi de neuf
    -- =====================
    ["wn_334_studio_reasons"] = "Cooldown Studio : le bouton « Ouvrir le Cooldown Studio » pouvait ne rien faire du tout. Toutes les raisons possibles d'un échec de chargement de l'éditeur étaient annoncées par le même message — « non installé » — y compris la plus fréquente de loin : il est bel et bien installé, simplement décoché dans votre liste d'addons. Chaque raison indique désormais ce qu'elle est et ce qu'il faut faire.",
    ["wn_334_studio_enable"] = "Cooldown Studio : si le seul problème est qu'il est décoché dans la liste des addons, cliquer sur le bouton le coche et ouvre l'éditeur. Lorsque le jeu exige d'abord un rechargement, il le dit au lieu de vous envoyer chercher le réglage vous-même.",
    ["wn_334_studio_preflight"] = "Cooldown Studio : la carte de l'onglet Cooldowns vous prévient que l'éditeur ne peut pas s'ouvrir avant que vous cliquiez, pas après. Le bouton reste cliquable volontairement : pour un addon décoché, cliquer dessus est précisément ce qui répare la situation.",
    ["wn_334_studio_init"] = "Cooldown Studio : un éditeur qui se chargeait sans parvenir à démarrer avalait votre clic sans un mot. Il annonce maintenant qu'il s'est chargé mais n'a pas pu s'initialiser, et pourquoi.",
    ["wn_334_studio_toc"] = "Cooldown Studio : le sous-addon affiche désormais l'icône TomoMod, une catégorie et le vrai numéro de version de l'addon dans votre liste d'addons. Il annonçait encore 1.0.0 sans icône, ce qui lui donnait l'air d'être l'addon de quelqu'un d'autre partageant le même nom.",
    ["wn_334_package_builder"] = "Empaquetage : le téléchargement est maintenant construit par un script qui refuse de le produire si le Cooldown Studio se retrouve à l'intérieur du dossier TomoMod au lieu d'être à côté. WoW ne regarde que le premier niveau du dossier AddOns : un Studio rangé un cran plus bas est un Studio que personne ne voit dans sa liste d'addons — c'est exactement la situation que la moitié des correctifs ci-dessus servent à diagnostiquer.",
    ["wn_334_diag_export"] = "Diagnostics : la fenêtre d'export vous demandait de copier le rapport, puis affichait l'adresse du tracker dans son titre — une adresse que vous ne pouviez récupérer qu'en jetant le rapport tout juste copié. Elle bascule désormais entre le rapport et le lien, vous dit lequel des deux vient d'atterrir dans votre presse-papier, et affiche l'adresse en clair à l'écran pour que vous puissiez simplement la lire.",
    ["wn_334_diag_reminder"] = "Diagnostics : la fenêtre précise maintenant que votre rapport est enregistré et peut être rouvert à tout moment avec /tmdiag tracker — prendre le lien d'abord ne vous coûte donc rien. Sa fermeture affiche également l'adresse dans le chat, une fois par session, au cas où vous auriez refermé trop vite.",
    ["wn_334_presets_roles"] = "Presets : les presets Tank, Soigneur et DPS n'écrivaient que trois ou quatre réglages chacun et reprenaient tout le reste de la base commune — trois archétypes qui étaient la même configuration sous des noms différents. Chacun écrit désormais une vraie configuration de rôle sur les cadres de groupe et de raid, les nameplates, les auras de la cible, les ressources, les cooldowns et les barres d'incantation : plaques larges colorées selon la menace et menace chiffrée pour les tanks, cadres nettement agrandis avec HoTs, dissipations et boucliers pour les soigneurs, barres de ressource agrandies et uniquement vos propres debuffs pour les DPS.",
    ["wn_334_presets_reset"] = "Presets : passer d'un preset à l'autre conservait les réglages du précédent. Un preset n'écrivait que ses propres modifications, donc tout ce qu'il ne mentionnait pas restait tel que le preset précédent l'avait laissé — passer de Tank à Soigneur vous faisait soigner avec des nameplates en mode tank. La base commune contient maintenant une valeur pour chaque réglage qu'un preset peut toucher et elle est écrite en premier à chaque fois : appliquer un preset donne le même résultat quel que soit ce qui le précédait.",
    ["wn_334_presets_cards"] = "Accueil : les presets sont désormais des cartes au lieu de quatre boutons colorés ne portant qu'un nom. Chacune affiche son icône de rôle, sa phrase de résumé et trois points sur ce qu'elle change réellement, avec la description complète au survol — et celle que vous utilisez actuellement est marquée « Actif », ce que ce panneau n'indiquait nulle part.",
    ["wn_334_role_badges"] = "Réglages : les sections utiles à un rôle précis portent maintenant une petite icône tank, soigneur ou DPS dans leur en-tête — HoTs et dissipations, cooldowns défensifs, mode tank, suivi des interruptions, texte de menace, etc. Survoler les icônes nomme les rôles concernés.",
    ["wn_334_role_filter"] = "Réglages : une barre de focus de rôle a été ajoutée en haut de la barre latérale — Tous, Tank, Soigneur, DPS. En choisir un garde en pleine lumière les réglages de ce rôle et estompe les autres. C'est volontairement un estompage et non un masquage : une option dont vous connaissez déjà l'emplacement reste exactement là où vous l'avez laissée, quel que soit le focus actif. Votre choix est conservé d'une session à l'autre.",
    ["wn_334_chat_history_settings"] = "Historique du chat : la seule chose que vous pouviez en faire était l'activer. Il a désormais sa propre section — durée de conservation des messages (de 1 heure à 3 jours, ou sans limite), nombre de lignes conservées (10 à 500) et un repère de session affiché après les lignes restaurées, pour que tout ce qui suit provienne clairement de la session en cours. La limite de stockage était par ailleurs décalée d'une unité : elle annonçait 128 lignes et en gardait 127.",
    ["wn_334_chat_history_delay"] = "Historique du chat : les lignes restaurées s'affichaient exactement au moment où les messages de chargement des addons et les erreurs Lua arrivent dans le chat, en les noyant sous une page entière de rappel. L'historique attend maintenant quelques secondes avant d'apparaître — réglable, ou zéro pour retrouver l'ancien comportement.",
    ["wn_334_chat_history_channels"] = "Historique du chat : le choix des canaux conservés — chuchotements, guilde, officier, groupe, raid, instance, canaux, dire, crier, émotes — existait depuis la sortie de la fonction et n'apparaissait nulle part dans l'interface. Il est maintenant sur le panneau. Un canal décoché n'est pas enregistré du tout, et pas seulement exclu de la restauration : le recocher ne ramènera donc pas ce qui est passé pendant qu'il était coupé.",
    ["wn_334_chat_history_clear"] = "Historique du chat : un bouton permet désormais de tout effacer, derrière une confirmation, et désactiver la fonction efface ce qui est déjà enregistré au lieu de laisser chaque ligne dormir dans vos données sauvegardées. Le panneau le précise avant que vous ne décochiez la case — ainsi que le fait que l'historique est enregistré pour tout le compte et donc partagé par tous vos personnages.",
    ["wn_334_roles_guides"] = "Rôles : une nouvelle catégorie Rôles, avec une page guide pour le tank, le soin et les dégâts. Chacune explique ce qui compte vraiment pour ce rôle, et chaque point porte un bouton qui ouvre le panneau contenant le réglage et le met en surbrillance. La page applique aussi le preset du rôle et bascule le focus de la barre latérale en un clic.",
    ["wn_334_search_nested_tabs"] = "Recherche de la config : un résultat situé dans un onglet imbriqué — les HoTs des cadres de raid, les couleurs des barres de ressource, tout ce qu'un panneau range derrière sa propre seconde rangée d'onglets — ouvrait la bonne catégorie puis atterrissait sur son premier onglet, pas celui contenant ce que vous cherchiez. L'index ne retenait que le nom de l'onglet le plus profond, que la barre d'onglets extérieure ne pouvait jamais reconnaître. Il enregistre maintenant un nom par niveau, et chaque barre d'onglets lit le sien.",
    ["wn_334_search_index_all_tabs"] = "Recherche de la config : la majorité des réglages n'était tout simplement pas dans l'index. Les pages que vous n'avez jamais ouvertes sont construites une fois, hors écran, pour que la recherche puisse les trouver — mais un panneau ne construit que son premier onglet, si bien que tout ce qui se trouve derrière un deuxième ou un troisième sous-onglet, c'est-à-dire l'essentiel de l'interface, était introuvable en le cherchant. Tous les onglets sont désormais parcourus. Cela représente beaucoup plus à construire, donc le travail se fait en arrière-plan par tranches de quelques millisecondes au lieu de figer le jeu à votre première recherche, et une liste de résultats déjà affichée se rafraîchit d'elle-même une fois terminée.",
    ["wn_334_search_index_duplicates"] = "Recherche de la config : les panneaux qui réutilisent une même page pour plusieurs onglets — chaque unité de barre d'incantation, chaque unit frame — se réduisaient à un seul résultat. L'index ne retenait que le nom de l'onglet le plus profond : la barre de la cible et celle du focus écrivaient donc la même entrée sur la même section, et toutes les copies sauf la première disparaissaient. Les entrées portent maintenant le chemin complet, et les sections de chaque unité sont listées séparément.",
    ["wn_334_roles_deeplink"] = "Rôles : les boutons des pages guides ouvraient la bonne catégorie puis vous laissaient sur l'onglet que vous aviez consulté en dernier. Ils cherchaient leur réglage dans l'index de recherche, et ces réglages — HoTs des cadres de raid, défensifs de groupe, mode tank — étaient précisément ceux qui manquaient à l'index. Chaque bouton nomme désormais son propre itinéraire, onglet par onglet : il atterrit sur la bonne page et met la section en surbrillance, sur un client qui vient de démarrer comme sur ce que vous regardiez juste avant.",
    ["wn_334_cr_detection"] = "Rappel de classe : il lisait la barre de postures par position. Félin en case 2, Ours en case 1, Sélénien en case 4 — sauf que l'emplacement d'une forme sur cette barre dépend de vos talents. Dès qu'il bougeait, le rappel comparait votre forme réelle à une case sans rapport : il vous annonçait une forme manquante alors que vous étiez dedans, ou restait muet alors que vous en étiez sorti. Les formes sont désormais reconnues par sort. Les guerriers récupèrent leurs trois postures, une par spécialisation, au lieu d'une entrée couvrant trois cases sur toutes les spés. Et les auras de paladin étaient cherchées parmi les formes, où elles n'avaient aucune chance d'être trouvées — ce sont des buffs, et elles sont vérifiées comme tels.",
    ["wn_334_cr_false"] = "Rappel de classe : certains rappels ne pouvaient tout simplement pas s'éteindre. L'évocateur ne suivait qu'un seul buff Bénédiction du Bronze, or ce sort en applique un différent à chaque classe — douze classes sur treize s'entendaient donc dire qu'il leur manquait un buff qu'elles portaient, aussi longtemps que le module restait actif. Même chose pour les versions talentées de Marque du fauve, Intelligence des Arcanes, Forme de sélénien et Forme d'ombre : seule la version de base était connue, si bien que ceux qui jouaient la variante étaient avertis pour un buff déjà présent.",
    ["wn_334_cr_icons"] = "Rappel de classe : c'était une ligne de texte clignotante au centre de l'écran nommant ce qui manquait. C'est désormais une rangée d'icônes, une par buff, forme, posture ou aura manquant, et hors combat un clic gauche suffit à le lancer au lieu de lire son nom puis d'aller le chercher sur une barre. Le clic milieu écarte un rappel jusqu'au prochain écran de chargement, pour le buff que vous avez décidé de ne pas prendre aujourd'hui. Rien n'est cliquable en combat, volontairement — une rangée qui resterait armée mentirait sur ce qu'un clic déclenche.",
    ["wn_334_cr_options"] = "Rappel de classe : taille des icônes, espacement, échelle de la rangée, opacité, libellé et sa taille, et un effet lumineux avec sa propre couleur. Les deux curseurs de position ont disparu — la rangée se place avec le déplaceur, comme tout ce qui se déplace, et elle a sa propre entrée dans le panneau Déplacement. Si vous l'aviez déplacée avec les curseurs, cette position est reprise une fois.",
    ["wn_334_cr_panel"] = "Rappel de classe : la page de réglages s'ouvre sur un aperçu vivant de la rangée, dessiné par le module lui-même : chaque curseur déplace donc ce que vous avez sous les yeux. Cliquer une icône vous emmène à son interrupteur, son libellé aux options de libellé, l'espace autour aux curseurs de taille. Et la liste des classes prises en charge — un paragraphe de texte par classe — devient une grille, une case par buff ou forme suivi, colorée par classe, chacune étant un interrupteur que vous pouvez couper pour ce dont vous préférez ne pas être averti.",
    ["wn_334_cr_enchants"] = "Rappel de classe : les imbues d'arme n'étaient pas suivies du tout. Arme langue de feu, furie-des-vents, terre vivante, garde de l'appel des marées et gardien de frappe-tonnerre ont chacune leur rappel, et les deux rites du Forgelumière n'en partagent qu'un, puisqu'ils s'excluent mutuellement et que l'un ou l'autre suffit. Les imbues ne sont pas des auras : le jeu ne les annonçait pas comme un buff, elles disparaissent désormais dès que vous en appliquez une, au lieu d'attendre un rafraîchissement sans rapport.",
    ["wn_334_cr_poisons"] = "Rappel de classe : les poisons de voleur, un rappel par catégorie plutôt que par poison — mortel et non mortel. Ce qui compte, c'est que les emplacements soient remplis : le module compte combien de poisons de la catégorie sont actifs face au nombre que vous pouvez réellement appliquer, un ou deux avec Lames trempées par les dragons. Aucune liste de builds à tenir à jour, et rien à reconfigurer quand vous changez de talents.",
    ["wn_334_cr_shields"] = "Rappel de classe : les boucliers de chaman sont suivis, et Orbite élémentaire est pris en compte au lieu d'être ignoré. Avec le talent vous portez Bouclier de terre sur vous et l'un des deux autres, les deux sont donc vérifiés ; sans lui, un seul bouclier suffit. Le rappel nomme la catégorie et son icône pointe vers le bon bouclier pour votre spécialisation — eau pour Restauration, éclairs sinon.",
    ["wn_334_cr_context"] = "Rappel de classe : vous choisissez désormais où il apparaît — partout, en donjons et raids uniquement, ou en groupe uniquement. Il est masqué en ville et à l'auberge par défaut, puisque c'est précisément là que vous allez tout réappliquer, et il reste muet quand vous êtes mort, en véhicule ou en vol sur une monture : des états où rien de la rangée ne peut être pressé.",
    ["wn_334_cr_group"] = "Rappel de classe : il peut aussi surveiller le groupe. Activez « avertir aussi quand un membre du groupe n'a pas le buff » et un buff de groupe que vous portez déclenche quand même son rappel tant que quelqu'un à portée ne l'a pas — le cas qu'il ratait depuis toujours, puisque l'avoir soi-même ne dit rien du reste du groupe. Seuls les membres que la statistique intéresse sont comptés, et seulement hors combat : les auras d'un autre joueur sont illisibles pendant un combat, et deviner laisserait un rappel affiché tout le pull. Désactivé par défaut, car surveiller les auras de tout le monde n'est pas gratuit.",
    ["wn_334_cr_perf"] = "Rappel de classe : il rebalayait vos auras et votre barre de postures une fois par seconde, indéfiniment, que quelque chose ait changé ou non. Le jeu annonce déjà un buff gagné, perdu ou expiré, et la barre de postures a ses propres événements : ce sondage ne servait à rien. Il réagit maintenant aux événements, et remarque aussi un changement de talents ou de grimoire — c'est-à-dire le moment où l'ensemble des formes concernées change réellement.",
    ["wn_334_uf_preview_engine"] = "Unit frames : l'aperçu des réglages était une maquette. Il dessinait ses propres fausses barres à partir des mêmes valeurs mais avec son propre code, et pouvait donc diverger de ce que vous obteniez en jeu — ce qu'il faisait. Il est désormais construit par les mêmes fonctions que vos vrais cadres : texture des barres, polices, bordures, bandeau d'info, décalages d'éléments, grille d'auras, buffs ennemis et menace viennent tous du moteur réel, et l'aperçu ne peut plus s'en écarter.",
    ["wn_334_uf_preview_live"] = "Unit frames : l'aperçu affiche vos vraies unités. Quand l'unité existe — votre cible, votre focus, votre familier — les cadres sont alimentés par les vraies données et marqués RÉEL ; sinon, ils retombent sur des valeurs simulées marquées SIM. Un bouton Ajusté / 1:1 permet aussi de vérifier les cadres à leur taille réelle en pixels plutôt que dans la bande réduite.",
    ["wn_334_uf_texture_live"] = "Unit frames : changer la texture des barres ne faisait rien tant que vous n'aviez pas rechargé — elle n'était lue qu'à la construction du cadre. Idem pour les chiffres de durée sur les auras. Les deux s'appliquent maintenant au fur et à mesure, sur vos vrais cadres et pas seulement dans l'aperçu.",
    ["wn_334_tmkeys"] = "Mythique+ : /tm keys ouvre le tableau sur votre groupe réel — le nom, la classe, le score M+ et la clé que chacun porte. Jusqu'ici ce tableau n'apparaissait que tout seul à la fin d'une course, et la seule commande qui l'ouvrait à la main affichait des données d'exemple, pas de vraies personnes. Le moment où l'on choisit quelle clé lancer était précisément celui où l'on ne pouvait pas le consulter. Il fonctionne hors donjon, là où on en a besoin.",
    ["wn_334_score_roleicon"] = "Mythique+ : chaque ligne du tableau affiche désormais une icône de rôle à côté de l'icône de spécialisation, dans les couleurs des presets de rôle et des badges des réglages. La spé dit ce que la personne a amené, le rôle dit ce qu'elle en fait, et une liste de clés qu'on lit avant de pull veut les deux.",
    ["wn_334_score_spec"] = "Mythique+ : votre propre spécialisation manquait sur votre ligne du tableau — le jeu ne la renvoie pas par l'appel qu'il utilise pour les autres. Elle est lue directement désormais. Les joueurs partageant un même rôle ressortaient aussi dans un ordre différent à chaque ouverture du tableau hors course, puisque le chiffre de dégâts qui les départage normalement y vaut zéro pour tout le monde ; les égalités retombent maintenant sur le niveau de clé, puis le score, puis le nom.",
    ["wn_334_mplus_teleports"] = "Mythique+ : les téléportations de donjon que vous aviez obtenues étaient affichées comme non apprises. Le panneau et le tableau des scores grisaient le donjon, l'infobulle annonçait une téléportation indisponible, et cliquer la ligne affichait « non apprise » sans rien lancer. Le test employé ne signale que les sorts accordés par votre classe ou votre familier, or les téléportations de donjon viennent des hauts faits — il répondait donc non pour absolument toutes, quel que soit le contenu réel de votre grimoire. Signalé pour Le Pic-du-ciel, et cela concernait toute la liste. Les téléportations fonctionnent désormais depuis le panneau.",
    ["wn_334_delete_confirm"] = "Confirmation de suppression : la fonction qui tape le mot de confirmation à votre place cherchait encore un élément de cette fenêtre que Blizzard a retiré en 11.2, et ne fonctionnait plus que grâce à une solution de repli qui devine le nom interne de la fenêtre. Elle demande désormais le champ de texte au jeu par la voie officielle, les anciens chemins restant derrière — elle continuera donc de remplir la case quoi que Blizzard fasse ensuite de cette fenêtre.",
    ["wn_334_friends_removed"] = "Contacts : le skin de la fenêtre de contacts a été retiré, ainsi que son onglet dans les réglages. Blizzard reconstruit cette fenêtre dans la 12.1, et le skin fonctionnait en allant chercher plusieurs dizaines de ses éléments un par un, par leur nom — des noms que cette reconstruction est libre de déplacer ou de renommer. Cela ne vieillit pas en douceur : le jour du patch, il reste une fenêtre à moitié dépouillée, chez vous et pas chez nous. Le skin était désactivé par défaut ; si vous l'aviez activé, la fenêtre retrouve simplement l'apparence de Blizzard. Le bouton Contacts de la barre latérale du chat n'est pas concerné.",

    -- =====================
